// 文法詳解 N1 簡體版(scripts/gen-grammar-detail-cn.mjs 由繁體正本轉出,別手改)
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["zh-CN"]=Object.assign(window.GRAMMAR_DETAIL_L10N["zh-CN"]||{},{"n1-14":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜なり」就是中文的<b>「一～就…」</b>，还带点「欸，这么快？」的惊讶。像你在跟朋友讲：「他一进门，鞋都没脱就冲进房间。」通常是在描述<b>别人</b>刚做完一个动作，马上又做了下一个让人有点意外的动作。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词的辞书形（就是字典里查得到的原形）直接加「なり」，不用变化。<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るなり</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くなり</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るなり</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>描述别人的反应</span>前一个动作才刚做完，同一个人马上有了下一个动作，而且这个动作有点突然。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るなり、部屋にこもってしまった。</span>（他一回到家，就把自己关进房间）</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞くなり、彼女は泣き出した。</span>（一听到那个消息，她就哭了出来）</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は私の顔を見るなり、走って逃げた。</span>（儿子一看到我，拔腿就跑）</div><div class='gd-sec'><span class='gd-tag'>讲故事的口吻</span>多半出现在小说、文章，或把一件事「说给别人听」的时候。平常聊天讲「一～就」，比较常用 N3 学过的「〜たとたん」。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>前后要是同一个人</b>。「他一回家，<b>他</b>就关进房间」可以；「铃一响，学生就冲出去」主角换人了，用なり会怪。<br>・<b>通常不拿来讲自己</b>。なり有种旁观者在描述的感觉，讲自己「我一回家就睡了」，说<span class='gd-jp'>家に帰ってすぐ寝た。</span>比较自然。<br>・后面接的是<b>已经发生的事</b>，不能接命令、邀约、打算：<br>×<span class='gd-jp'>家に帰るなり、宿題をしなさい。</span>（不能用来叫人做事）<br>・前面一定是辞书形。换成た形的「<span class='gd-jp'>〜たなり</span>」是另一个意思：「～之后就一直那样」，例如<span class='gd-jp'>出かけたなり、帰ってこない。</span>（出门之后就一直没回来）<br>・「<span class='gd-jp'>〜なり〜なり</span>」（～或～都行）、「<span class='gd-jp'>私なりに</span>」（用我自己的方式）长得一样，是完全不同的文法，不要混在一起。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>N1 有好几个「一～就」，同样接辞书形，后面也都是已经发生的事，差别在<b>谁做的、强调什么、用在哪</b>。<br><br><b>なり</b>：同一个人，做出有点意外的动作。<br><span class='gd-jp'>部長は会議室に入るなり、大声で怒鳴り始めた。</span>（部长一走进会议室，就开始大吼）<br><br><b>や否や</b>：很书面，<b>前后可以是不同的人或事</b>。<br><span class='gd-jp'>ベルが鳴るや否や、学生たちは教室を飛び出した。</span>（铃一响，学生们就冲出教室）<br><br><b>が早いか</b>：重点在<b>快</b>，前面刚做完，后面几乎同时就做了。<br><span class='gd-jp'>子どもたちは「いただきます」と言うが早いか、料理に手を伸ばした。</span>（孩子们「我开动了」才刚说完，手就伸向菜了）<br><br><b>たとたん</b>（N3）：日常口语，<b>讲自己也可以</b>，后面常是自己控制不了的事。<br><span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（一站起来就头晕）</div><div class='gd-warn'>判断小诀窍：同一个人突然做了什么 → なり；两件不同的事紧接着发生、又是写文章 → や否や；想强调手脚超快 → が早いか；讲自己、平常聊天 → たとたん。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着看同一组的「<span class='gd-jp'>〜が早いか</span>」「<span class='gd-jp'>〜や否や</span>」，再对照「<span class='gd-jp'>〜そばから</span>」（才刚～马上又～，讲一再重复的事），这几个一起记最不会搞混。</div>","n1-15":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜が早いか」就是中文的<b>「一～就立刻…」</b>，而且是快到<b>分不清哪件事先发生</b>的那种。字面意思是「（前面那件事）比较快吗？」：前一个动作才刚开始，后一个动作已经发生了。就像下课钟才刚响，学生已经冲到走廊上。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>描写看到的场面</span>用来讲<b>已经发生</b>的事，句尾大多是过去式。小说、文章、新闻描写很常见，日常聊天几乎不会讲。</div><div class='gd-ex-line'>・<span class='gd-jp'>チャイムが鳴るが早いか、子供たちは教室を飛び出した。</span>（钟声一响，孩子们就冲出教室）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るが早いか、ベッドに倒れ込んだ。</span>（他一回到家就倒在床上）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるが早いか、売り切れてしまった。</span>（新商品一开卖就卖光了）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词的辞书形（字典上查到的原形）直接加「が早いか」，不用改形。<br><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>発売される</span> → <span class='gd-jp'>発売されるが早いか</span></span><br>就算整句是过去的事，前面也还是用辞书形，时态交给句尾。偶尔也会看到た形，例如<span class='gd-jp'>言ったが早いか</span>，不过先记辞书形就够用。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面<b>不能接命令、拜托、自己的打算</b>：×<span class='gd-jp'>家に着くが早いか、電話してください。</span>想说「到家马上打给我」，要说<span class='gd-jp'>家に着いたら、すぐ電話してください。</span><br>・中文的「一～就～」用途很广，像「一到春天花就开」这种<b>规律、条件</b>不能用が早いか，那是<span class='gd-jp'>春になると、花が咲く。</span><br>・语气很硬。跟朋友讲「我一到家就睡了」，说<span class='gd-jp'>家に帰って、すぐ寝ちゃった。</span>就好，用が早いか会像在念小说。<br>・前面不要加ます：×<span class='gd-jp'>鳴りますが早いか</span>。<br>・「早い」念<b>はやい</b>。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个场面，三种说法都对：<br><span class='gd-jp'>息子は帰ってくるが早いか、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるなり、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるや否や、かばんを置いて遊びに行った。</span><br>（儿子一回来，就放下书包跑去玩了）</div><div class='gd-sec'><b>なり</b>：前后一定是<b>同一个人</b>做的动作，后面常是让人有点意外的举动。所以「钟一响，学生就冲出去」不能用なり：×<span class='gd-jp'>チャイムが鳴るなり、生徒が飛び出した。</span><br><b>や否や</b>：前后可以是不同的人或事，语气<b>最书面、最正式</b>，新闻报导很爱用：<span class='gd-jp'>ドアが開くや否や、客が店内になだれ込んだ。</span>（门一开，客人就涌进店里）<br><b>が早いか</b>：前后也可以不同主词，重点放在<b>快到分不出先后</b>，常带有迫不及待、抢着做的画面。</div><div class='gd-warn'>判断小诀窍：同一个人、后面的举动有点出人意料，用なり；想强调「快到几乎同时」，用が早いか；正式的书面报导，用や否や。三个后面都不能接命令、拜托或自己的打算。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>「〜そばから」看起来也像「一～就～」，但它是<b>一再重复</b>的「才刚～就又…」：<span class='gd-jp'>覚えるそばから忘れてしまう。</span>（才刚背好就又忘了）。要讲的是「每次都这样」，不是单一次的「快」。</div>","n1-16":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜や否や」就是中文的<b>「一～就～」</b>，而且是<b>刚做完、下一件事马上就发生</b>的那种快。它是很正式的<b>书面说法</b>，常出现在小说、新闻、文章里。你可以把它想成<span class='gd-jp'>〜たとたん</span>的书面版。</div><div class='gd-h'>先搞懂这个字</div><div class='gd-sec'>念<b>やいなや</b>。「否」就是「不」。整句原本的意思是「到底做了没，都还分不清楚」，也就是<b>前一个动作才刚发生，后面就接着来了</b>。记住这个画面，就知道它强调的是「快」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形＋や否や<br><span class='gd-pair'><span class='gd-jp'>目を覚ます</span> → <span class='gd-jp'>目を覚ますや否や</span></span>（一睁开眼就～）<br><span class='gd-pair'><span class='gd-jp'>ドアが開く</span> → <span class='gd-jp'>ドアが開くや否や</span></span>（门一开就～）<br>文章里有时只写一个「や」，意思一样：<span class='gd-jp'>家に着くや</span>（一到家就～）。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>描述已经发生的事</span>讲故事、报导一件事「A 一发生，B 马上就发生了」。后面通常是过去式。</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開くや否や、子どもたちが飛び出してきた。</span>（门一开，孩子们就冲了出来）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるや否や、売り切れた。</span>（新商品一开卖就卖光了）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長が現れるや否や、会場は静まり返った。</span>（社长一出现，会场立刻安静下来）</div><div class='gd-sec'>前后可以是<b>不同的人或东西</b>：上面「门开」跟「孩子冲出来」就是两个不同的主角，这样用没问题。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要用<b>辞书形</b>，不是た形：是<span class='gd-jp'>帰るや否や</span>，不是「帰ったや否や」。中文说「一回来就」，很多人会顺手写成过去式。<br>・「否」念<b>いな</b>，不是ひ。<br>・后面不能放「我要～」「请～」「～吧」这种请求或打算。<br>　× 駅に着くや否や、電話してください。<br>　○ <span class='gd-jp'>駅に着いたら、すぐ電話してください。</span>（到了车站请马上打给我）<br>・它很硬、很文章，跟朋友聊天说「我一到家就睡了」，讲<span class='gd-jp'>家に着いたとたん、寝ちゃった</span>或<span class='gd-jp'>帰ってすぐ寝た</span>就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境「他一进房间就哭了」：<br><span class='gd-tag'>や否や</span><span class='gd-jp'>彼は部屋に入るや否や、泣き出した。</span><br>最正式、最书面，前后可以不同主角。<br><span class='gd-tag'>なり</span><span class='gd-jp'>彼は部屋に入るなり、泣き出した。</span><br>前后一定是<b>同一个人</b>，常带「怎么突然这样」的意外感。<br><span class='gd-tag'>が早いか</span><span class='gd-jp'>彼は部屋に入るが早いか、泣き出した。</span><br>更强调「快到几乎同时」，小说味很重；前面也可以用た形。<br><span class='gd-tag'>たとたん</span><span class='gd-jp'>彼は部屋に入ったとたん、泣き出した。</span><br>日常版，讲话写字都能用，前面是た形。</div><div class='gd-sec'>另外两个也常被拿来混：<br><b>次第</b>可以接请求、打算：<span class='gd-jp'>着き次第、連絡します。</span>（一到就跟你联络）这句换成や否や就不行。<br><b>そばから</b>是「做了马上又被抵消，而且一直重复」：<span class='gd-jp'>覚えるそばから忘れてしまう。</span>（刚记住马上又忘，一直这样）。这不是单一次的「一～就～」。</div><div class='gd-warn'>判断小诀窍：要请对方做事用「次第」；一直重复的白做工用「そばから」；描述一次已经发生的事，聊天用「たとたん」，写文章用「や否や」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>把<span class='gd-jp'>〜なり</span>、<span class='gd-jp'>〜が早いか</span>、<span class='gd-jp'>〜そばから</span>一起看，这组「一～就～」在 N1 考试很常一起出来比。</div>","n1-8":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ならでは」就是中文的<b>「只有～才有的」「不愧是～才做得到」</b>。比如说「京都才有的风景」「手工才有的温度」，你要强调<b>这个东西别的地方没有、只有它有</b>，而且通常是在称赞。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面直接接<b>名词</b>，后面最常再接「の＋名词」。<br><span class='gd-pair'><span class='gd-jp'>職人</span> → <span class='gd-jp'>職人ならではの技術</span></span>（只有工匠才有的技术）<br><span class='gd-pair'><span class='gd-jp'>地元</span> → <span class='gd-jp'>地元ならではの料理</span></span>（只有当地才吃得到的料理）<br>前面放的通常是<b>人、地方、店、某种做法</b>这类有自己特色的东西。</div><div class='gd-h'>最常看到的样子</div><div class='gd-sec'><span class='gd-tag'>ならではの＋名词</span>最常用，九成都是这个样子。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもならではの自由な発想に驚いた。</span>（小孩子才有的自由想法让我很惊讶）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅館ならではのおもてなしを楽しんだ。</span>（享受了只有日式旅馆才有的款待）</div><div class='gd-sec'><span class='gd-tag'>ならではだ</span>放在句尾，等于「这正是～才做得到的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、老舗ならではだ。</span>（这个味道，只有老店才做得出来）</div><div class='gd-sec'><span class='gd-tag'>ならでは〜ない</span>比较书面、老派的说法，意思是「不是～就没办法～」。看得懂就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、この店ならでは味わえない。</span>（这个味道，不是这家店就吃不到）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的「なら」<b>不是「如果」</b>，不要翻成「如果是～的话」。<br>・「では」的「は」念<b>わ</b>，整个念ならでわ。<br>・前面直接接名词，<b>不要多加の</b>：是<span class='gd-jp'>日本ならではの</span>，不是日本のならではの。<br>・它的重点是「<b>只有它有</b>」。大家都有的普通特征不能用，例如说「东京才有的便利商店」就很怪，因为到处都有便利商店。<br>・大多用在称赞。偶尔会看到「<span class='gd-jp'>都会ならではの悩み</span>」（都市才有的烦恼）这种中性说法，但拿来讲单纯的缺点、失败，听起来会很奇怪。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>らしい</b>＝很有～的感觉、很像～（别的地方也可能有类似的）：<br><span class='gd-jp'>京都らしい景色だ。</span>（很有京都味的景色）<br><b>ならでは</b>＝只有那里才有，别处找不到：<br><span class='gd-jp'>京都ならではの景色だ。</span>（只有在京都才看得到的景色）</div><div class='gd-sec'><b>をおいて</b>＝讲<b>人选</b>，除了他没有别人可以选：<br><span class='gd-jp'>この役ができるのは、彼をおいてほかにいない。</span>（能演这个角色的，除了他没有别人）<br><b>ならでは</b>＝讲<b>特色</b>，这种东西只有他做得出来：<br><span class='gd-jp'>この演技は彼ならではだ。</span>（这种演技只有他演得出来）</div><div class='gd-warn'>判断小诀窍：「很像～」用らしい；「只有～才有的特色」用ならでは；「要选的话只有他」用をおいてほかにない。</div>","n1-33":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とはいうものの」就是中文的<b>「说是这样说没错啦，可是…」</b>。前面先承认一件事是真的，后面再补一句：实际情况没有照那样走。像「虽说已经是春天了，但还是好冷」就是这个感觉。<br>拆开就好记：<span class='gd-jp'>と</span>（这样）＋<span class='gd-jp'>いう</span>（说）＋<span class='gd-jp'>ものの</span>（虽然），合起来是「虽然说是～」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>放在句子中间</span>A とはいうものの、B。A 是事实，或大家都这么说；B 是「照理说应该这样，结果却不是」。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い日が続いている。</span>（虽说已经是春天了，还是一直很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>（虽说在日本住了十年，敬语还是不太行）</div><div class='gd-ex-line'>・<span class='gd-jp'>便利になったとはいうものの、失われたものも少なくない。</span>（虽然变方便了，但失去的东西也不少）</div><div class='gd-sec'><span class='gd-tag'>放在句子开头</span>前一句已经讲完，下一句用「<span class='gd-jp'>とはいうものの</span>、」开头，就是「话虽如此，…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今月から節約すると決めた。とはいうものの、コンビニに行くとつい買ってしまう。</span>（我决定这个月开始省钱。话虽如此，一进便利商店还是忍不住买）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面用普通形，也就是不加です・ます的说法。<br>动词：<span class='gd-pair'><span class='gd-jp'>習った</span> → <span class='gd-jp'>習ったとはいうものの</span></span><br>い形容词：<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいうものの</span></span><br>な形容词：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとはいうものの</span></span>，だ也可以拿掉：<span class='gd-jp'>便利とはいうものの</span><br>名词：<span class='gd-pair'><span class='gd-jp'>春だ</span> → <span class='gd-jp'>春とはいうものの</span></span>，留着だ说<span class='gd-jp'>春だとはいうものの</span>也可以</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面一定要接「跟预期不一样」的事。<span class='gd-jp'>春とはいうものの、暖かい。</span>就很怪，春天本来就暖和，根本没有转折。<br>・语气偏书面、正式，文章、新闻、演讲常见。跟朋友聊天说「<span class='gd-jp'>けど</span>」或「<span class='gd-jp'>とはいっても</span>」比较自然，讲「とはいうものの」会像在念稿。<br>・后面通常是在描述现实状况或自己的感受，很少接「请～」「～吧」这种拜托、邀约的话。<br>・<span class='gd-jp'>いう</span>实际念起来是「ゆう」，但写的时候还是写いう，不要写成ゆう。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境「虽说是春天，但还是冷」：<br><b>とはいえ</b>（N2）：<span class='gd-jp'>春とはいえ、まだ寒い。</span>意思几乎一样，比较短，也一样偏书面，也能放句首。<br><b>とはいうものの</b>：<span class='gd-jp'>春とはいうものの、まだ寒い。</span>意思跟とはいえ一样，只是比较长。<br><b>とはいっても</b>：<span class='gd-jp'>春とはいっても、まだ寒いね。</span>嘴巴讲话最常用的版本。<br><b>ものの</b>（N2）：<span class='gd-jp'>春になったものの、まだ寒い。</span>直接接一个事实，少了「说是～」那一层。<br><b>とは言い条</b>（N1）：<span class='gd-jp'>春とは言い条、まだ寒い。</span>意思一样，但非常古典，现在几乎只在文章里看到。</div><div class='gd-warn'>判断小诀窍：讲话用「とはいっても」，写文章用「とはいえ」「とはいうものの」，「とは言い条」看得懂就好，自己不太需要用。</div>","n1-40":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜にひきかえ」很像中文的<b>「反观～」「相较之下」</b>。先讲一边，再讲完全相反的另一边，而且通常一边好、一边不好，说话的人心里有感觉。比如「人家哥哥那么认真，<b>反观</b>弟弟……」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>直接接：<span class='gd-pair'><span class='gd-jp'>去年</span> → <span class='gd-jp'>去年にひきかえ</span></span><br><b>一句话</b>要先加「の」把它变成名词，再接にひきかえ：<br><span class='gd-pair'><span class='gd-jp'>兄はよく勉強する</span> → <span class='gd-jp'>兄がよく勉強するのにひきかえ</span></span><br><span class='gd-pair'><span class='gd-jp'>姉は明るい</span> → <span class='gd-jp'>姉が明るいのにひきかえ</span></span><br>「社交的」这种要加な才能接の：<span class='gd-pair'><span class='gd-jp'>社交的</span> → <span class='gd-jp'>社交的なのにひきかえ</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>两边落差很大</span>拿两个人、两个时期、两个地方来对照，强调差很多。</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の猛暑にひきかえ、今年の夏は過ごしやすい。</span>（跟去年的酷暑比起来，今年夏天舒服多了）</div><div class='gd-ex-line'>・<span class='gd-jp'>前の部長にひきかえ、今度の部長はとても話しやすい。</span>（跟之前的部长比起来，这次的部长好沟通多了）</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が社交的なのにひきかえ、弟は人見知りだ。</span>（哥哥很外向，反观弟弟却很怕生）</div><div class='gd-sec'><span class='gd-tag'>それにひきかえ</span>放在句子开头，意思是「反观～」。前面先讲别人多好，后面接自己或自家人，常带抱怨或自嘲。</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の子は毎日勉強している。それにひきかえ、うちの子はゲームばかりだ。</span>（隔壁的小孩每天都在念书。反观我家小孩，整天只会打电动）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・接句子时中间的「の」不能少：要说<span class='gd-jp'>社交的なのにひきかえ</span>，不能说社交的にひきかえ。这里的「のに」是「の＋に」，不是「明明～却」的のに。<br>・它带着说话者的评价，<b>不适合拿来比纯数据</b>。像「男性占三成，女性占五成」这种只是陈述数字的句子，用にひきかえ会很怪。<br>・语气偏书面、偏正式。日常聊天比较常听到的是句首的<span class='gd-jp'>それにひきかえ</span>。<br>・别跟<span class='gd-jp'>〜と引き換えに</span>搞混，那是「用～交换」：<span class='gd-jp'>代金と引き換えに商品を渡す。</span>（一手交钱一手交货）。意思完全不同。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲哥哥外向、弟弟内向：<br><b>に対して</b>＝客观列出两边不一样，没有情绪：<span class='gd-jp'>兄は社交的なのに対して、弟は内向的だ。</span>（哥哥外向，弟弟则内向）<br><b>にひきかえ</b>＝带着「怎么差这么多」的感慨或不满：<span class='gd-jp'>兄が社交的なのにひきかえ、弟は内向的だ。</span>（哥哥那么外向，反观弟弟却这么内向）<br><b>に比べて</b>＝单纯比程度高低：<span class='gd-jp'>去年に比べて、今年は暑い。</span>（今年比去年热）</div><div class='gd-warn'>判断小诀窍：心里有「反观～」「人家都…你却…」的感觉，用にひきかえ；只是客观说两边不同，用に対して；只是比谁多谁少，用に比べて。</div>","n1-2":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜をもって」就是中文公文里的<b>「以～」</b>。一个意思是<b>「用～来做」</b>（以书面通知、以诚意处理），另一个意思是<b>「以～为界线」</b>（以本日为限、到今天为止）。你在公告、通知信、典礼主持人嘴里最常看到它，平常聊天几乎不会用。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接放在前面，再加をもって：<span class='gd-pair'><span class='gd-jp'>書面</span> → <span class='gd-jp'>書面をもって</span></span><br>前面接的多半是正式或抽象的名词，例如书面、诚意、拍手，或是本日、3月这种时间。<br>讲话时想更客气，会说成<span class='gd-jp'>をもちまして</span>，意思一样。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>用什么方式</span>「用～来做某件事」，像正式场合里的「で」。</div><div class='gd-ex-line'>・<span class='gd-jp'>合否は書面をもってお知らせします。</span>（录取与否会以书面通知）</div><div class='gd-ex-line'>・<span class='gd-jp'>誠意をもって対応いたします。</span>（我们会诚心诚意处理）</div><div class='gd-ex-line'>・<span class='gd-jp'>盛大な拍手をもってお迎えください。</span>（请以热烈的掌声欢迎）</div><div class='gd-sec'><span class='gd-tag'>时间的界线</span>以某个时间点为分界，多半是「到这天为止、结束」，也可以是「从这天起生效」。</div><div class='gd-ex-line'>・<span class='gd-jp'>本日をもって、閉店いたします。</span>（本店营业到今天为止）</div><div class='gd-ex-line'>・<span class='gd-jp'>以上をもちまして、本日の会議を終了いたします。</span>（以上，今天的会议到此结束）</div><div class='gd-ex-line'>・<span class='gd-jp'>4月1日をもって、社名を変更いたします。</span>（自 4 月 1 日起更改公司名称）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<span class='gd-jp'>本日をもって閉店</span>是说<b>今天还有开，今天是最后一天</b>，不是今天已经不开了。翻成「自本日起结束营业」很容易让人误会。<br>・这是很硬的书面说法，日常生活别乱用。跟朋友说「用笔写」就讲<span class='gd-jp'>ペンで書く</span>，讲成ペンをもって書く会很怪。<br>・它跟「拿着」的<span class='gd-jp'>持って</span>是不同用法。<span class='gd-jp'>傘を持って出かける</span>是真的手上拿着伞出门；<span class='gd-jp'>書面をもって</span>则是「以书面的方式」，没有人拿着东西。所以文法用法常写成平假名。<br>・<span class='gd-jp'>以上をもちまして</span>是活动、典礼收尾的固定说法，听到这句就知道要结束了。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>で</b>＝日常说法的「用～」：<span class='gd-jp'>結果はメールで知らせるね。</span>（结果我再用 email 跟你说）<br><b>をもって</b>＝正式公告的「以～」：<span class='gd-jp'>結果は書面をもってお知らせします。</span>（结果将以书面通知）<br>两句意思差不多，差别在场合：一个是跟人随口说，一个是公司或学校发的正式通知。</div><div class='gd-sec'><b>を限りに</b>也能讲「到～为止」，但它强调<b>「这是最后一次，之后不再做」</b>，常带着个人下定决心的感觉：<span class='gd-jp'>今日を限りにタバコをやめる。</span>（从今天起我不再抽烟了）<br><b>をもって</b>比较像机关、公司发的<b>正式公告</b>，而且也能讲「从这天起开始生效」，这是を限りに没有的用法：<span class='gd-jp'>本日をもって受付を締め切ります。</span>（受理到今天截止）</div><div class='gd-warn'>判断小诀窍：平常讲「用～」用で；公告、通知、典礼上的「以～」用をもって；自己下决心「到今天为止不再～」用を限りに。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'><span class='gd-jp'>をもってしても</span>＝「就算用上～也…」，后面接做不到的事：<span class='gd-jp'>最新の技術をもってしても、完全には防げない。</span>（就算用上最新技术，也无法完全防止）</div>","n1-3":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜をものともせず」就是中文的<b>「不畏～」「不把～放在眼里」</b>。前面放困难、危险、阻碍，后面接「结果还是做到了」，用来称赞一个人很勇敢、很拚。新闻报导「不畏风雨，坚守岗位」那种语气，就是它。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋<span class='gd-jp'>をものともせず</span>（后面也可以多一个に：<span class='gd-jp'>をものともせずに</span>，意思一样）<br><span class='gd-pair'><span class='gd-jp'>病気</span> → <span class='gd-jp'>病気をものともせず</span></span>（不畏疾病）<br><span class='gd-pair'><span class='gd-jp'>周囲の反対</span> → <span class='gd-jp'>周囲の反対をものともせず</span></span>（不畏周遭反对）<br>拆开来看，<span class='gd-jp'>もの</span>是「东西」，<span class='gd-jp'>せず</span>是「不做」，字面上就是「连当成一回事都不当」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>前面放困难</span>病痛、受伤、坏天气、危险、失败、反对、压力这类「挡在前面的东西」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は度重なる失敗をものともせず、挑戦し続けた。</span>（他不畏一再的失败，持续挑战）</div><div class='gd-ex-line'>・<span class='gd-jp'>救助隊は激しい雨をものともせず、山へ向かった。</span>（救难队不畏大雨，朝山上出发）</div><div class='gd-sec'><span class='gd-tag'>后面放做到的事</span>通常是已经发生的事实，带有佩服、赞赏的口气。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は周囲の反対をものともせず、自分の店を開いた。</span>（她不顾周遭反对，开了自己的店）</div><div class='gd-ex-line'>・<span class='gd-jp'>その選手は怪我をものともせず、最後まで走り抜いた。</span>（那位选手不畏伤痛，跑完全程）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它是在<b>称赞别人</b>，一般不拿来讲自己。<span class='gd-jp'>私は寒さをものともせず</span>听起来像在自夸，很怪。<br>・后面不接「请你～」「我们～吧」。像「不畏困难，加油吧」这种话，不要用它来讲，它是拿来<b>描述已经做到的事</b>。<br>・前面一定要是<b>阻碍</b>。「应援」「机会」这种好东西不能放，因为没有东西可以「不畏」。<br>・助词是<b>を</b>，不是が。<br>・这是书面、新闻、演讲用的硬词，跟朋友聊天几乎不会讲。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>をよそに</b>＝<b>不管别人的担心或期待</b>，自顾自去做。前面常放<span class='gd-jp'>心配</span>、<span class='gd-jp'>期待</span>，带点「不听劝」的感觉。<br>・<span class='gd-jp'>親の心配をよそに、彼は一人で海外へ行った。</span>（他不管父母的担心，自己一个人出国了）<br><b>をものともせず</b>＝<b>不怕困难</b>，勇敢撑过去，是称赞。<br>・<span class='gd-jp'>言葉の壁をものともせず、彼は海外で成功した。</span>（他不畏语言障碍，在国外成功了）<br>「父母的担心」不是要克服的难关，所以说成<span class='gd-jp'>親の心配をものともせず</span>就不自然。</div><div class='gd-sec'><b>にもかかわらず</b>＝单纯的「尽管～还是～」，不带褒贬，好事坏事都能用。<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（尽管下雨，还是来了很多人）<br>如果想强调「这些人很了不起」，才换成<span class='gd-jp'>雨をものともせず</span>。</div><div class='gd-warn'>判断小诀窍：前面是「难关」，而且你想夸对方勇敢，就用をものともせず；前面是「别人的心情」，对方不理会，就用をよそに；只是单纯说「尽管」，用にもかかわらず。</div>","n1-9":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AはおろかB」就是中文的<b>「别说A了，连B都～」</b>。A 是「本来就理所当然」的那件事，提都懒得提；B 是更出乎意料的那件事，用来强调「状况夸张到这种地步」。而且顺序跟中文一样，直接照中文的语序套就好。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>基本是<b>名词＋はおろか</b>：<span class='gd-pair'><span class='gd-jp'>漢字</span> → <span class='gd-jp'>漢字はおろか</span></span><br>如果 A 是动作，先在动词后面加「こと」把它变成名词：<span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることはおろか</span></span><br>后半句通常会配<b>も、さえ、すら、まで</b>，这些字就是中文的「连～都」。</div><div class='gd-h'>A 和 B 怎么排</div><div class='gd-sec'>判断方法：A 放「这件事本来就理所当然」的，B 放更极端、更让人意外的。</div><div class='gd-sec'><span class='gd-tag'>否定句（最常见）</span>A 是比较难的，B 是比较基本的。「难的不会很正常，但连简单的都不会」才有强调效果。</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はおろか、ひらがなさえまだ読めない。</span>（别说汉字了，连平假名都还不会读）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、休みはおろか、昼ご飯を食べる時間もない。</span>（忙到别说休假了，连吃午餐的时间都没有）</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがして、走ることはおろか、歩くこともできない。</span>（脚受伤了，别说跑步，连走路都没办法）</div><div class='gd-sec'><span class='gd-tag'>正面句</span>反过来，A 是比较普通的，B 是范围更大、更厉害的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は国内はおろか、海外でも人気がある。</span>（这首歌别说国内了，连国外都很红）</div><div class='gd-warn'>顺序不要放反：<span class='gd-jp'>ひらがなはおろか、漢字も読めない。</span>就不合逻辑了。连平假名都不会的人，不会汉字本来就很正常，根本不用拿出来强调。<br>不管是否定句还是正面句都一样：A 是「本来就这样」，B 是「连这个都这样」。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后半句<b>不能放命令、请求、自己的打算</b>。<span class='gd-jp'>漢字はおろか、ひらがなも覚えなさい。</span>是错的，这时要改用<span class='gd-jp'>はもちろん</span>。<br>・は已经在里面了，前面不要再多加を或が。也不能直接接动词，要记得先加「こと」。<br>・这里的おろか跟「愚か」（愚蠢）没有关系，不要理解成「笨」。<br>・语气偏硬，常带「真是夸张」「太惨了」的不满或惊讶，多用在书面或比较正式的场合。跟朋友聊天，日本人比较常讲<span class='gd-jp'>どころか</span>。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境比较看看：<br><b>はおろか</b>＝带着感叹或不满强调「连B都」，后半句只能是陈述：<span class='gd-jp'>漢字はおろか、ひらがなも書けない。</span>（别说汉字，连平假名都不会写）<br><b>はもちろん</b>＝单纯的「A当然，B也」，语气中性，后面可以接请求：<span class='gd-jp'>漢字はもちろん、ひらがなもちゃんと書いてください。</span>（汉字当然要写好，平假名也请好好写）<br><b>どころか</b>＝意思跟はおろか接近，比较口语。它另外还能表示「不但不A，反而B」：<span class='gd-jp'>安いどころか、すごく高かった。</span>（不但不便宜，反而贵得要命）。はおろか没有这个「反而」的用法。</div><div class='gd-warn'>判断小诀窍：要叫别人做事就用はもちろん；跟朋友讲话就用どころか；写文章、想加强「夸张到连这个都」的感叹，就用はおろか。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>后半句常搭配的<span class='gd-jp'>すら</span>（连～都），可以接着学。</div>","n1-10":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ないまでも」就是中文的<b>「就算没到～那么好，起码也要～」</b>。先把高标准放下（满分、每天、像母语者那样），再说一个<b>退一步、最低限度</b>的目标。就像你跟自己说「不求每天运动，至少一周动一次」，就是这种口气。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词ない形＋までも。前半段放「高标准」，后半段放「至少要做到的程度」。<br><span class='gd-pair'><span class='gd-jp'>取れない</span> → <span class='gd-jp'>取れないまでも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ネイティブのようには話せないまでも、日常会話はこなしたい。</span>（就算没办法讲得像母语者，至少想应付得了日常会话）</div><div class='gd-sec'>实际上更常见的是下面两个固定组合，前面直接放名词，建议整组背起来：</div><div class='gd-sec'><span class='gd-tag'>とは言わないまでも</span>「不要求到～的程度」，常用来讲希望、要求。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日とは言わないまでも、週に一度は運動したい。</span>（不说每天，至少想一周运动一次）</div><div class='gd-sec'><span class='gd-tag'>とはいかないまでも</span>「虽然没达到～」，常拿来讲已经有的结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>（虽然没拿到满分，至少有及格）</div><div class='gd-h'>后半段长什么样子</div><div class='gd-sec'>后半段通常是「想～」「应该～」「希望对方～」，或是已经做到的结果。而且常搭配<b>「は」「くらいは」「せめて」</b>，强调「至少这个」。</div><div class='gd-ex-line'>・<span class='gd-jp'>謝罪とは言わないまでも、せめて一言説明してほしい。</span>（不要求道歉，至少也解释一句吧）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前后要是<b>同一把尺上的高低</b>：满分对及格、每天对一周一次。前面高、后面低。后面比前面还高，或两件事根本不相关，就不能用。<br>・后半段是<b>肯定</b>的「至少有做到／想做到」。如果要说「连低标都没做到」，要换别的句型（看下面的はおろか）。<br>・别跟「〜までもない」搞混：<span class='gd-jp'>言うまでもない</span>是「不用说也知道」，前面接辞书形，意思是「没必要做」；<span class='gd-jp'>言わないまでも</span>是「虽然不说到那个地步」。差一个ない，意思完全不一样。<br>・整体偏书面、正式的感觉，不过「とは言わないまでも」在日常对话里也蛮常听到。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>最容易混的是<b>〜はおろか</b>，两个都是「高标准没做到」，但后面的方向相反。同样讲考试：<br><span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>（虽然不到满分，至少有及格）→ 低标<b>有做到</b>，往好的方向收尾。<br><span class='gd-jp'>満点はおろか、合格点も取れなかった。</span>（别说满分了，连及格都没拿到）→ 连低标都<b>没做到</b>，往坏的方向强调。</div><div class='gd-warn'>判断小诀窍：「高的没有，<b>但低的有</b>」用ないまでも；「高的没有，<b>连低的也没有</b>」用はおろか。</div>","n1-22":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜べく」就是<b>「为了～」</b>，但它是书面、正式的说法，感觉很像中文新闻或公文里的「为求～」「以期～」。意思跟「ために」差不多，只是更硬、更正式，平常聊天几乎不会讲。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>新闻・报导</span>交代某人为了什么目的采取了行动。</div><div class='gd-ex-line'>・<span class='gd-jp'>真相を確かめるべく、記者は現地へ向かった。</span>（为了查明真相，记者前往当地）</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格すべく、毎日10時間勉強した。</span>（为了考上，每天念 10 小时书）</div><div class='gd-sec'><span class='gd-tag'>正式场合表决心</span>致词、记者会、公司公告里说「为了～我们会努力」。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご期待に応えるべく、全力を尽くします。</span>（为了不辜负各位的期待，我们会全力以赴）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词的<b>辞书形</b>（字典上查到的原形）直接加「べく」：<br><span class='gd-pair'><span class='gd-jp'>確かめる</span> → <span class='gd-jp'>確かめるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>応える</span> → <span class='gd-jp'>応えるべく</span></span></div><div class='gd-sec'><b>する</b>比较特别，两种都可以，<b>すべく</b>更常见：<br><span class='gd-pair'><span class='gd-jp'>達成する</span> → <span class='gd-jp'>達成すべく</span></span>（也可以说<span class='gd-jp'>達成するべく</span>）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面<b>不能接否定</b>：没有「遅刻しないべく」这种说法。要说「为了不～」请用<span class='gd-jp'>遅刻しないように</span>。<br>・后面<b>不能接请对方做事</b>（请求、命令、邀约）：<span class='gd-jp'>合格すべく、毎日勉強してください</span>是错的，要改成<span class='gd-jp'>合格するために、毎日勉強してください</span>。<br>・<b>名词不能直接接</b>：可以说<span class='gd-jp'>健康のために</span>，但没有「健康のべく」。要用べく就得接动词：<span class='gd-jp'>健康を維持すべく</span>。<br>・前后通常是<b>同一个人</b>、而且是<b>有意图去做</b>的事。像「下雨」这种人控制不了的事，不能放在べく前面。<br>・小心跟副词<span class='gd-jp'>なるべく</span>（尽量）撞字：<span class='gd-jp'>なるべく早く来てください</span>是「请尽量早点来」；<span class='gd-jp'>医者になるべく</span>才是「为了成为医生」。看前面有没有接东西就分得出来。<br>・跟朋友聊天说「〜べく」会很像在念公文，口语请用ために。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「为了考上而努力」：<br><b>ために</b>＝一般说法，讲话写字都能用：<span class='gd-jp'>合格するために、毎日勉強している。</span>（为了考上，每天都在念书）<br><b>べく</b>＝书面、正式：<span class='gd-jp'>合格すべく、毎日勉強した。</span>（为求考上，每天苦读）<br><b>んがため（に）</b>＝更古、更硬，带有「拚了命也要」的强烈感觉，接法也不同（<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span>）：<span class='gd-jp'>合格せんがため、寝る間も惜しんで勉強した。</span>（为了考上，连睡觉时间都舍不得，拚命念书）</div><div class='gd-warn'>判断小诀窍：平常用ために；新闻、演讲、正式文章用べく；要强调「无论如何都要达成」才用んがため。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>・<span class='gd-jp'>べくして</span>：「本来就注定会～」，意思跟「为了」不同。<span class='gd-jp'>起こるべくして起こった事故だ。</span>（这是迟早会发生的事故）<br>・同一家族的<span class='gd-jp'>べき</span>（应该）、<span class='gd-jp'>べからず</span>（不可以），意思都不是「为了」，不要混在一起。</div>","n1-23":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ゆえ（に）」就是中文书面语的<b>「由于～」「因～之故」</b>。意思跟「から」「ので」一样是「因为」，只是穿上了西装、说话文诌诌。新闻评论、小说、演讲稿里常看到，朋友聊天几乎不会讲。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><span class='gd-tag'>名词</span>最常见的是直接接，中间也可以加「の」。<br><span class='gd-pair'><span class='gd-jp'>若さ</span> → <span class='gd-jp'>若さゆえ</span></span><span class='gd-pair'><span class='gd-jp'>貧しさ</span> → <span class='gd-jp'>貧しさのゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>动词・い形容词</span>用一般的普通形（就是字典上那种不加ます的说法），后面接「がゆえ」或「ゆえ」都可以，「がゆえ」语气更硬。<br><span class='gd-pair'><span class='gd-jp'>人気がある</span> → <span class='gd-jp'>人気があるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いがゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>な形容词・名词当句子</span>把「だ」换成<b>である</b>再接。<br><span class='gd-pair'><span class='gd-jp'>真面目だ</span> → <span class='gd-jp'>真面目であるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるがゆえに</span></span></div><div class='gd-h'>最常看到的样子</div><div class='gd-sec'><span class='gd-tag'>ゆえに、〜</span>后面接一整句结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>人気があるがゆえに、予約がなかなか取れない。</span>（由于太受欢迎，一直订不到位）</div><div class='gd-ex-line'>・<span class='gd-jp'>責任ある立場ゆえに、軽率な発言は許されない。</span>（因为身居要职，不能随便发言）</div><div class='gd-sec'><span class='gd-tag'>ゆえの＋名词</span>直接修饰后面的名词，「因～而来的…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>経験不足ゆえの失敗だった。</span>（那是经验不足造成的失败）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しさゆえの嘘もある。</span>（也有出于温柔而说的谎）</div><div class='gd-sec'><span class='gd-tag'>句首的ゆえに</span>单独放在句子开头，就是「所以、因此」，数学证明、哲学论述很常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>我思う、ゆえに我あり。</span>（我思，故我在）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・名词和な形容词<b>不能接「だ」</b>：不是「学生だがゆえに」，要说<span class='gd-jp'>学生であるがゆえに</span>。<br>・日常对话用它会很像在演古装剧或念台词。跟朋友讲「因为很忙」，说<span class='gd-jp'>忙しいから</span>就好，说「忙しいがゆえに」会让人笑出来。<br>・汉字写成「故」，看到<span class='gd-jp'>若さ故に</span>不要以为是别的文法，一样念ゆえに。<br>・后面常接比较负面、或「反而～」的结果，带点「就是因为这个特点才会这样」的感慨，例如<span class='gd-jp'>真面目であるがゆえに、かえって批判されることもある。</span>（正因为认真，有时反而被批评）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>から／ので</b>＝一般的「因为」，口语书面都能用：<span class='gd-jp'>子どもを愛しているから、厳しくする。</span>（因为爱孩子，所以严格）<br><b>がゆえに</b>＝同样的意思，换成文章腔，客观陈述原因：<span class='gd-jp'>子どもを愛するがゆえに、厳しくする。</span>（由于爱孩子，所以对他严格）<br><b>ばこそ</b>＝强烈强调「<b>正是</b>因为这个，不是别的」，常是说话者在替自己的作法辩护，句尾常接のだ：<span class='gd-jp'>子どもを愛すればこそ、厳しくするのだ。</span>（正是因为爱孩子，才会对他严格）</div><div class='gd-warn'>判断小诀窍：只是换个正式说法讲「因为」就用ゆえに；想强调「就是这个理由，你要懂我」就用ばこそ。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样讲原因的N1文法还有<span class='gd-jp'>〜とあって</span>（因为是～这种特殊情况），可以跟ゆえに一起比较着记。</div>","n1-27":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜たところで」就是中文的<b>「就算～也没用」「～了又怎样」</b>。像台湾人讲「现在哭有什么用」「你再怎么解释他也不会信」，语气有点看破、有点泼冷水：前面那件事做了也白做。</div><div class='gd-ex-line'>・<span class='gd-jp'>今さら謝ったところで、関係は戻らないだろう。</span>（事到如今就算道歉，关系也回不去了吧）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>先把动词变成た形（过去式那个形），后面直接加「ところで」。<br><b>第一类（五段动词）</b>：<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いだ</span> → <span class='gd-jp'>急いだところで</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったところで</span></span><br><b>第二类（一段动词）</b>：<br><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てた</span> → <span class='gd-jp'>慌てたところで</span></span><br><b>第三类（する・来る）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したところで</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たところで</span></span></div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>做了也白搭</span>最常见的用法。前面常配「<span class='gd-jp'>いくら</span>」「<span class='gd-jp'>どんなに</span>」「<span class='gd-jp'>今さら</span>」，后面接「～ない」「無駄だ」「仕方がない」这类没用的结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに急いだところで、最終便には間に合わない。</span>（再怎么赶也赶不上末班了）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら説明したところで、わかってもらえないだろう。</span>（再怎么解释，他大概也不会懂）</div><div class='gd-sec'><span class='gd-tag'>顶多也只是～</span>后面接「<span class='gd-jp'>せいぜい</span>」，意思是「就算做了，结果也大不到哪去」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今から急いだところで、せいぜい5分早く着くくらいだ。</span>（现在赶，顶多也只早到 5 分钟）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・虽然用た形，讲的是<b>假设</b>，不是已经发生的事。「謝ったところで」是「就算（去）道歉」，不是「道歉了」。<br>・后面要接没用、不怎么样的结果。想说「努力的话就考得上」这种好结果，不能说頑張ったところで合格できる，要用<span class='gd-jp'>頑張れば合格できる</span>。<br>・后面是你自己的判断或推测，常以「～だろう」「～わけではない」收尾，不会接「～てください」这种请别人做事的话。<br>・同样的「たところで」还有一个意思是「在～的时候、刚好告一段落时」，后面接下一个动作：<span class='gd-jp'>話が一段落したところで、休憩しましょう。</span>（话题告一段落，休息一下吧）。看后面：是「没用」就是本篇的意思，是「接着做某事」就是时间点。<br>・语气带点冷淡、放弃感，直接对人说「你做了也没用」会很泼冷水，要看场合。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ても</b>＝一般的「即使」，中性，后面好结果、坏结果都可以：<span class='gd-jp'>彼に説明しても、わかってもらえないだろう。</span>（跟他解释，他大概也不会懂）<br><b>たところで</b>＝特别强调「做了也白费」，比ても更死心：<span class='gd-jp'>彼に説明したところで、わかってもらえないだろう。</span>（就算跟他解释也没用，他不会懂的）<br><b>ようと</b>＝「不管～，我照样～」，重点在后面不受影响，可以接自己的决心：<span class='gd-jp'>みんなが反対しようと、私はこの計画を進める。</span>（不管大家怎么反对，我都要推动这个计划）<br>同样讲反对，用たところで就变成：<span class='gd-jp'>みんなが反対したところで、社長の考えは変わらない。</span>（大家就算反对也没用，社长的想法不会变）</div><div class='gd-warn'>判断小诀窍：想说「做了也白搭」用たところで；想说「不管怎样我都要做」用ようと；只是一般的「即使」就用ても。</div>","n1-28":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ようが／〜ようと」就是<b>「管他～，我照样…」</b>。前面不管发生什么、别人怎么样，后面的结论都不会变。语气比一般的「〜ても」<b>硬、强烈</b>，有一种「我说了算、没在怕」的态度。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>配疑问词</span>前面放「何・どこ・誰・どんなに・いくら」，意思是「不管什么／哪里／谁／多么～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何を言われようが、気にしない。</span>（不管被说什么，我都不在意）</div><div class='gd-ex-line'>・<span class='gd-jp'>どこへ行こうと、あなたの自由です。</span>（你要去哪里，都是你的自由）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が反対しようと、私はやる。</span>（不管谁反对，我都要做）</div><div class='gd-sec'><span class='gd-tag'>单独用</span>没有疑问词时，就是「就算～也照样…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが行く。</span>（就算下雨，我也照样要去）</div><div class='gd-sec'><span class='gd-tag'>两个并排</span>「AようがBようが」＝不管A还是B；「Aようが Aまいが」＝不管做不做。这里的「まい」是「不～」的意思，第一类（五段动词）接辞书形：<span class='gd-jp'>行くまい</span>；<span class='gd-jp'>する</span>常说成<span class='gd-jp'>しまい</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが風が吹こうが、試合は行われる。</span>（不管刮风下雨，比赛都照常举行）</div><div class='gd-ex-line'>・<span class='gd-jp'>参加しようがしまいが、あなたの自由だ。</span>（要不要参加，随你）</div><div class='gd-sec'>后面很常接「<span class='gd-jp'>自由だ</span>」「<span class='gd-jp'>関係ない</span>」「<span class='gd-jp'>構わない</span>」「<span class='gd-jp'>気にしない</span>」，或是「我就是要做」的决心。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>动词</b>：先变成意向形（就是「行こう」「食べよう」那个形），再加が或と。<br>第一类（五段动词）：<span class='gd-pair'><span class='gd-jp'>行く</span> → く换成こ → <span class='gd-jp'>行こうが</span></span><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうが</span></span><br>第二类（一段动词）：把る拿掉加よう　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べようが</span></span>，被动的<span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われようが</span></span>也是这样变<br>第三类（する・来る）：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようが</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようが</span></span></div><div class='gd-sec'><b>い形容词</b>：把最后的「い」拿掉，加「かろう」。<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かろうが</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろうと</span></span><br>「いい」要用「よい」来变化：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろうが</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに暑かろうと、毎朝のランニングは欠かさない。</span>（不管多热，每天早上的慢跑都不会停）</div><div class='gd-sec'><b>な形容词・名词</b>：加「だろう」或比较正式的「であろう」。<br><span class='gd-pair'><span class='gd-jp'>不便だ</span> → <span class='gd-jp'>不便だろうが</span></span><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもであろうと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>相手が子どもだろうが、ルールはルールだ。</span>（就算对方是小孩，规则就是规则）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的意向形<b>没有</b>「～吧」「揪人」的意思，只是借它的样子来表示「不管」。<br>・第一类不能直接接：是<span class='gd-jp'>行こうが</span>，不是「行くようが」。<br>・<span class='gd-jp'>来ようが</span>要念「こようが」，不是「きようが」。<br>・<span class='gd-jp'>降ろうが</span>只是「就算下雨」；要讲「下不下雨都…」得说<span class='gd-jp'>降ろうが降るまいが</span>。<br>・「ようが」和「ようと」意思基本上一样，可以互换。<br>・语气很硬、很强势，平常聊天说「<span class='gd-jp'>暑くても</span>」比较自然；「<span class='gd-jp'>暑かろうが</span>」这种かろう形偏书面或强调时用。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境：再怎么赶。<br><b>ても</b>＝一般的「就算～也」，最中性：<span class='gd-jp'>いくら急いでも、間に合わない。</span>（再怎么赶也来不及）<br><b>ようが</b>＝后面是「我照样／都没差」，带强烈态度：<span class='gd-jp'>いくら急がされようが、手は抜かない。</span>（不管怎么被催，我都不会偷工减料）<br><b>たところで</b>＝后面是「也没用、结果不会好」：<span class='gd-jp'>いくら急いだところで、もう間に合わない。</span>（就算再怎么赶，也已经来不及了）</div><div class='gd-sec'>另外，名词也可以用「<b>であれ</b>」表达一样的「不管是～」：<span class='gd-jp'>理由が何であれ、遅刻はだめだ。</span>和<span class='gd-jp'>理由が何であろうと、遅刻はだめだ。</span>意思几乎一样（不管理由是什么，迟到就是不行）。</div><div class='gd-warn'>判断小诀窍：后面是「我照样做／随便你／没关系」就用ようが；后面是「做了也没用」就用たところで；日常口语、不想讲得那么冲，就用ても。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样是「不管A还是B」，可以接着看「<span class='gd-jp'>〜にせよ〜にせよ</span>」：<span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>（不管去不去，都请联络我）</div>","n1-29":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AにせよBにせよ」就是中文的<b>「不管是A还是B，都～」</b>。先丢出两种可能，再告诉你：哪一种都一样，结论不会变。语气比较正式，常出现在文章、新闻、开会发言里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>动词、い形容词</b>：直接接普通形（就是不加ます、です的说法）。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにせよ行かないにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ安いにせよ</span></span></div><div class='gd-sec'><b>名词、な形容词</b>：直接接，现在式<b>不要加だ</b>。正式一点可以加「である」。<br><span class='gd-pair'><span class='gd-jp'>大人</span> → <span class='gd-jp'>大人にせよ子どもにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きにせよ嫌いにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにせよ</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>一组相反的</span>去／不去、赞成／反对，哪边都一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してください。</span>（不管去不去，都请早点联络）</div><div class='gd-ex-line'>・<span class='gd-jp'>好きにせよ嫌いにせよ、この仕事は誰かがやらなければならない。</span>（不管喜不喜欢，这份工作总得有人做）</div><div class='gd-sec'><span class='gd-tag'>两个同类的</span>举两个例子，代表「这一类都一样」。</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にせよ子どもにせよ、ルールは守らなければならない。</span>（不管大人还是小孩，都得遵守规则）</div><div class='gd-sec'>后半句通常是「应该～」「都得～」「没有差别」这种<b>两边都成立</b>的判断。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>固定说法</span>不举例，直接用一个词包山包海，口语、书面都超常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、結果が出たら連絡します。</span>（不管怎样，结果出来我再通知你）</div><div class='gd-ex-line'>・<span class='gd-jp'>何にせよ、無事でよかった。</span>（总之，平安就好）</div><div class='gd-sec'><span class='gd-tag'>只用一次</span>单独一个「にせよ」＝「就算～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にせよ、そんなことを言ってはいけない。</span>（就算是开玩笑，也不能说那种话）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・名词、な形容词现在式不加だ：不是学生だにせよ，是<span class='gd-jp'>学生にせよ</span>或<span class='gd-jp'>学生であるにせよ</span>。<br>・「せよ」长得像命令（「去做！」），但在这里只是固定说法，<b>没有命令的意思</b>。<br>・后半句一定要对两种情况都成立。如果结论只适用其中一边，就不能用。<br>・很书面。跟朋友聊天说<span class='gd-jp'>行っても行かなくても</span>比较自然，讲にせよ会有点像在念公文。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>にしろ…にしろ</b>：意思完全一样，语气稍微软一点，口语也还能用。<br><span class='gd-jp'>行くにしろ行かないにしろ、連絡してください。</span>（不管去不去，都请联络）<br><b>であれ…であれ</b>：主要接名词，比にせよ更硬、更正式。<br><span class='gd-jp'>大人であれ子どもであれ、ルールは守るべきだ。</span>（不管大人小孩，都应该守规则）<br><b>ようが…まいが</b>：带着「随便你、反正都一样」的强烈情绪。<br><span class='gd-jp'>行こうが行くまいが、私には関係ない。</span>（你去不去都跟我无关）</div><div class='gd-warn'>判断小诀窍：平静地说「不管A还是B」用にせよ／にしろ；只接名词、要更正式用であれ；带着「随便啦、反正不会变」的情绪用ようが。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>「不管内容如何都～」可以学<span class='gd-jp'>いかんにかかわらず</span>：<span class='gd-jp'>理由のいかんにかかわらず、遅刻は認めません。</span>（不管理由是什么，迟到一律不接受）</div>","n1-30":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜と思いきや」就是中文的<b>「本来以为～，结果竟然…」</b>。前面写你原本的预期，后面写实际发生的事，而且结果跟预期<b>完全相反</b>，有一种「被打脸」的意外感。</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れると思いきや、午後から急に雨が降り出した。</span>（本来以为会放晴，结果下午突然下起雨来）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放<b>普通形</b>（就是没有ます、です的说法），后面直接加「と思いきや」。<br><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したと思いきや</span></span><br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単だと思いきや</span></span></div><div class='gd-sec'><span class='gd-tag'>かと思いきや</span>中间常常多一个「か」，口气像「我还以为是不是～」，非常常见。加「か」的时候要注意：<br><b>动词、い形容词</b>：直接加か。<br><span class='gd-pair'><span class='gd-jp'>終わった</span> → <span class='gd-jp'>終わったかと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかと思いきや</span></span><br><b>名词、な形容词</b>：先把「だ」拿掉，再加か。<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → だ拿掉 → <span class='gd-jp'>簡単かと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → だ拿掉 → <span class='gd-jp'>雨かと思いきや</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もう帰ったかと思いきや、まだ会社にいた。</span>（还以为他已经回去了，结果还在公司）</div><div class='gd-ex-line'>・<span class='gd-jp'>高いかと思いきや、意外と安かった。</span>（还以为很贵，没想到挺便宜的）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は怒るかと思いきや、笑って許してくれた。</span>（本来以为他会生气，结果他笑着原谅我了）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'>多半出现在文章、新闻、电视旁白、社群贴文这种「讲故事」的场合，带一点惊讶或好笑的感觉。网路上甚至会只写「〜と思いきや…」就停住，故意吊胃口，等下一句揭晓。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・名词、な形容词加か时，<b>不能留着だ</b>：是<span class='gd-jp'>簡単かと思いきや</span>，不是「簡単だかと思いきや」。<br>・「思いきや」是固定的一整块，<b>不能变形</b>，不会有「思いましたきや」这种说法。<br>・念<b>おもいきや</b>，别跟<span class='gd-jp'>思い切り</span>（用力地、尽情地）、<span class='gd-jp'>思い切って</span>（下定决心）搞混，长得像但意思完全无关。<br>・后半句是<b>已经发生的事实</b>，通常用过去式。不能接「要做什么」或命令、邀约：「雨だと思いきや、傘を持っていこう」是错的。<br>・结果一定要跟预期<b>相反</b>。如果结果跟你想的一样，就不能用。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>日常聊天比较常讲的是<b>と思ったら</b>。它也能表示「本来以为～，结果…」，这时候跟と思いきや可以互换，只是口气比较口语：<br><span class='gd-jp'>簡単かと思ったら、意外と難しかった。</span>（还以为很简单，结果意外地难）<br>但と思ったら还有另一个意思：<b>「才刚～，马上就…」</b>，讲事情接得很快。这个意思と思いきや没有：<br><span class='gd-jp'>子どもは泣いたと思ったら、もう笑っている。</span>（小孩才刚哭，马上又在笑了）<br>这句换成と思いきや就不对，因为重点是「变化很快」，不是「预期落空」。</div><div class='gd-warn'>判断小诀窍：只要是「预期被打脸」，两个都能用，写文章用と思いきや，聊天用と思ったら；如果是「才刚～就…」，只能用と思ったら。</div>","n1-31":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ものを」就是中文的<b>「你早说不就好了嘛！」</b>那种口气。本来只要那样做就没事，偏偏没做，结果变糟了。话里带着<b>可惜、埋怨、怪人</b>的情绪，有时是怪别人，有时是怪自己。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放一般的普通形（就是字典上那种不加ます的说法），最常见的是接在「〜ばいい」「〜ばよかった」后面：<br><span class='gd-pair'><span class='gd-jp'>言えばいい</span> → <span class='gd-jp'>言えばいいものを</span></span><br><span class='gd-pair'><span class='gd-jp'>聞けばよかった</span> → <span class='gd-jp'>聞けばよかったものを</span></span><br>な形容词要用「な」来接：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なものを</span></span>，不会说「便利だものを」。</div><div class='gd-h'>最常听到的三种样子</div><div class='gd-sec'><span class='gd-tag'>〜ばいいものを</span>明明那样做就好了，偏偏不做。最常拿来念别人。</div><div class='gd-ex-line'>・<span class='gd-jp'>謝ればすむものを、意地を張るから話がややこしくなる。</span>（明明道个歉就没事了，偏要逞强，事情才搞得这么麻烦）</div><div class='gd-ex-line'>・<span class='gd-jp'>黙っていればいいものを、余計な一言で彼を怒らせてしまった。</span>（明明闭嘴就没事，偏偏多讲一句惹他生气）</div><div class='gd-sec'><span class='gd-tag'>〜ば〜たものを</span>「要是～的话，本来就会～了」，但实际上没有发生，很可惜。</div><div class='gd-ex-line'>・<span class='gd-jp'>言ってくれれば手伝ったものを。</span>（你早点说的话，我就会帮你了啊）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し早く家を出ていれば間に合ったものを。</span>（要是再早一点出门就赶上了）</div><div class='gd-sec'><span class='gd-tag'>停在句尾</span>后面那句「你却没做」直接吞回去不讲，只留下叹气的感觉。上面第三句就是这种，日剧、小说很常见。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・别跟「东西＋を」搞混：<span class='gd-jp'>おいしいものを食べた</span>的もの是「东西」，后面直接接动词；「〜ものを」的后面通常有逗号，接的是「结果却…」，或干脆不讲。<br>・它是在讲<b>已经发生、改不了</b>的事，后面不能接请求或命令：不会说「早く言えばいいものを、言ってください」。<br>・语气偏书面、有点文学味，带着责怪。日常聊天多半说「〜ばよかったのに」，对上司、客人用「ものを」去念，会显得很不客气。<br>・后半句是在叹气、抱怨，不是单纯陈述事实，所以前面几乎都是「本来那样就好」这种假设的说法。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>のに</b>：意思最接近，日常口语最常用。<br><span class='gd-jp'>早く言えばよかったのに。</span>（早说就好了嘛）<br><b>ものを</b>：同样是抱怨，但比较书面，情绪也更重。<br><span class='gd-jp'>早く言えばよかったものを。</span>（早说不就好了，唉）<br>另外，のに也能单纯讲「明明～却～」的事实（<span class='gd-jp'>雨なのに出かけた。</span>下雨还是出门了），ものを很少这样用。</div><div class='gd-sec'><b>ものの</b>（N2）：只差一个字，意思是「虽然～但是～」，冷静交代事实，没有怪谁的意思。<br><span class='gd-jp'>先生に相談しようと思ったものの、言い出せなかった。</span>（虽然想找老师商量，却开不了口）<br><span class='gd-jp'>先生に相談すればよかったものを、一人で悩んでいた。</span>（明明找老师商量就好了，却一个人烦恼）</div><div class='gd-warn'>判断小诀窍：前面有「〜ばいい／〜ばよかった」，又带着「早知道就…」的叹气，就是ものを；只是平平地说「虽然…但是…」，就是ものの。</div>","n1-43":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とは」就是中文的<b>「竟然～」「没想到～」</b>。遇到一件完全没料到的事，你吓一跳、很感慨，甚至有点傻眼或失望，就把那件事放在とは前面。很像台湾人说「蛤？他竟然是犯人喔！」的那种反应。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>惊讶・意外</span>事情的发展跟你想的完全不一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな所で君に会うとは。</span>（竟然会在这种地方碰到你）</div><div class='gd-ex-line'>・<span class='gd-jp'>まさか一回で合格するとは思わなかった。</span>（没想到竟然一次就考过）</div><div class='gd-sec'><span class='gd-tag'>傻眼・失望</span>不只惊讶，还带着「怎么会这样」的不满。</div><div class='gd-ex-line'>・<span class='gd-jp'>大人がこんな簡単なルールも守れないとは、情けない。</span>（大人竟然连这么简单的规定都做不到，真丢脸）</div><div class='gd-sec'><span class='gd-tag'>话说一半</span>后面的「驚いた」「思わなかった」常常直接省掉，只留下「竟然……」的余韵。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が犯人だったとは……。</span>（他竟然是犯人……）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面用<b>普通形</b>，也就是不加です・ます的说法，然后加とは。<br>动词：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うとは</span></span><span class='gd-pair'><span class='gd-jp'>負けた</span> → <span class='gd-jp'>負けたとは</span></span><br>い形容词：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>こんなに高いとは</span></span><br>な形容词：<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>こんなに簡単だとは</span></span><br>名词：<span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人だとは</span></span>，这个だ有时会省略，说成<span class='gd-jp'>犯人とは</span>。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>前面常搭配<span class='gd-jp'>まさか</span>（万万没想到），后面常接<span class='gd-jp'>思わなかった</span>、<span class='gd-jp'>思いもよらなかった</span>、<span class='gd-jp'>夢にも思わなかった</span>、<span class='gd-jp'>信じられない</span>、<span class='gd-jp'>驚きだ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>自分が日本で働くことになるとは、夢にも思わなかった。</span>（做梦也没想到，自己竟然会在日本工作）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・とは的は念「わ」，整个念とわ。<br>・前面要用普通形，不能接ます形，<span class='gd-jp'>会いますとは</span>是错的。<br>・只是假设、还不确定的事，不能用とは（例如「もし合格するとは」是错的）。不过还没发生、但已经确定的消息可以用：<span class='gd-jp'>彼女が来月結婚するとは、驚いた。</span>（她下个月竟然要结婚了，好惊讶）<br>・とは听起来比较正式、偏书面。跟朋友聊天时，日本人比较常说なんて。用とは也可以，只是听起来会比较夸张、有点戏剧感。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>なんて</b>：意思一样是「竟然」，只是比较口语。<br><span class='gd-jp'>こんな所で会うなんて！</span>（竟然在这里碰到！朋友间）<br><span class='gd-jp'>こんな所でお会いするとは。</span>（竟然在此相遇，较正式）</div><div class='gd-sec'><b>表示「所谓～」的とは</b>：同样写作とは，但这是在替一个词下定义，后面接说明或问句，完全没有惊讶的意思。<br><span class='gd-jp'>幸せとは何だろう。</span>（所谓幸福是什么呢）<br><span class='gd-jp'>彼が幸せだったとは。</span>（他竟然是幸福的）</div><div class='gd-sec'><b>と思いきや</b>：「本来以为～，结果却……」，后面要把<b>真正的结果</b>说出来。<br><span class='gd-jp'>晴れると思いきや、雨が降ってきた。</span>（本来以为会放晴，结果下起雨来）<br><span class='gd-jp'>こんなに雨が降るとは。</span>（竟然下这么大的雨）</div><div class='gd-warn'>判断小诀窍：とは前面是一整件让你惊讶的事、后面接感想就是「竟然」；前面只有一个名词、后面在解释它，就是「所谓」；先写原本的预想、再写真正结果的，是と思いきや。</div>","n1-47":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ともなると」就是中文的<b>「都到了～这个份上，当然就～」</b>。身分升上去了、年纪到了、某个特别的时期到了，情况自然跟平常不一样。台湾人说「都当到部长了，责任当然重」，日文就是<span class='gd-jp'>部長ともなると、責任も重くなる。</span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>身分・地位</span>当上某个比较高的位子，就会碰到相应的状况。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長ともなると、毎日会議ばかりだ。</span>（都当到部长了，每天都在开会）</div><div class='gd-sec'><span class='gd-tag'>年纪・阶段</span>人长到某个阶段，自然会变得不一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>高校生ともなると、親とあまり話さなくなる。</span>（上了高中，就不太跟爸妈讲话了）</div><div class='gd-sec'><span class='gd-tag'>时期</span>一到某个特别的时期，每次都会这样。</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、どこの店も人でいっぱいだ。</span>（一到年底，每家店都挤满了人）</div><div class='gd-sec'><span class='gd-tag'>事情的规模</span>要做一件有份量的大事，接下来的状况也跟着变大。</div><div class='gd-ex-line'>・<span class='gd-jp'>家を建てるともなると、決めることが山ほどある。</span>（真要盖房子的话，要决定的事多到不行）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋ともなると：<span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長ともなると</span></span><br>动词辞书形（字典上查到的原形）＋ともなると：<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するともなると</span></span><br>前面放的通常是<b>比一般高一级、有份量</b>的身分、年纪、时期或事情；后面接到了那个阶段<b>理所当然</b>会出现的状况或判断。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它带着「都到这种程度了」的语感。如果只是单纯讲一般的变化，像「一到春天就开花」，用<span class='gd-jp'>春になると</span>比较自然。<br>・后面通常接一般情况或判断，例如责任重、很挤、要准备很多。很少接「我要～」「请～」这种自己的打算或对别人的要求。<br>・这里的「とも」不是「都」的意思，跟<span class='gd-jp'>ともなく</span>（不经意地～）也完全是两回事，不要看到とも就混在一起。<br>・它偏正式、偏书面。跟朋友聊天时，讲<span class='gd-jp'>部長になると</span>或<span class='gd-jp'>部長にもなると</span>比较轻松。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ともなれば</b>：意思几乎一样，大部分情况可以直接互换。<br><span class='gd-jp'>部長ともなれば、責任も重くなる。</span>（都当上部长了，责任当然变重）</div><div class='gd-sec'><b>とあって</b>：讲「因为碰上这次特别的情况，所以眼前就发生了～」，说的是一件已经看到、实际发生的事。<b>ともなると</b>讲的是「一到这个份上，向来都会～」的一般倾向。</div><div class='gd-ex-line'>・<span class='gd-jp'>連休とあって、高速道路はどこも渋滞している。</span>（因为是连假，高速公路现在到处都在塞）</div><div class='gd-ex-line'>・<span class='gd-jp'>連休ともなると、高速道路はどこも渋滞する。</span>（每次一到连假，高速公路就到处塞）</div><div class='gd-warn'>判断小诀窍：讲「这次因为～，所以～」用とあって；讲「一到～这个份上，自然都会～」用ともなると。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'><span class='gd-jp'>〜たる</span>也常跟身分一起出现，但它讲的是「既然是这个身分，就应该要有的样子」：<span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（身为老师，就必须当学生的榜样）。ともなると讲身分带来的<b>自然结果</b>，たる讲身分该有的<b>应有表现</b>，可以对照着记。</div>","n1-67":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜をよそに」就是中文的<b>「不顾～」「把～当耳边风」</b>。<span class='gd-jp'>よそ</span>是「别人家、别的地方」，<span class='gd-jp'>〜をよそに</span>就是把旁人的担心、反对，或周围的状况，当成<b>别人家的事</b>，自己照样我行我素。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>不管别人的心情</span>最常见的用法。前面放别人的担心、反对、期待、批评，后面讲主角照样做自己的事。很多时候带一点「怎么这样」的感觉，但不一定是骂人，也可以只是客观描述。</div><div class='gd-ex-line'>・<span class='gd-jp'>親の心配をよそに、息子は毎晩遅くまで遊んでいる。</span>（爸妈那么担心，儿子还是每天晚上玩到很晚）</div><div class='gd-ex-line'>・<span class='gd-jp'>周囲の反対をよそに、彼女は会社を辞めて留学した。</span>（不顾身边的人反对，她辞掉工作去留学了）</div><div class='gd-sec'><span class='gd-tag'>不受周围状况影响</span>前面放景气、社会上的骚动这类「照理说应该会受影响」的状况，后面讲主角却完全没被影响。</div><div class='gd-ex-line'>・<span class='gd-jp'>不景気をよそに、この店はいつも行列ができている。</span>（景气这么差，这家店却照样大排长龙）</div><div class='gd-ex-line'>・<span class='gd-jp'>世間の騒ぎをよそに、本人はのんびり旅行を楽しんでいた。</span>（外面吵翻天，当事人却悠哉地在旅行）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>直接接在<b>名词</b>后面：名词＋をよそに<br><span class='gd-pair'><span class='gd-jp'>家族の心配</span> → <span class='gd-jp'>家族の心配をよそに</span></span><span class='gd-pair'><span class='gd-jp'>ファンの期待</span> → <span class='gd-jp'>ファンの期待をよそに</span></span><br>最常搭配的名词：<span class='gd-jp'>心配</span>、<span class='gd-jp'>反対</span>、<span class='gd-jp'>期待</span>、<span class='gd-jp'>批判</span>、<span class='gd-jp'>不安</span>、<span class='gd-jp'>騒ぎ</span>。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放名词。不要写成「心配するをよそに」，要先换成名词<span class='gd-jp'>心配</span>。<br>・前面放的是<b>旁人的反应或周围的状况</b>，不是自己该做的事。「不写功课跑去玩」不要说「宿題をよそに」，用<span class='gd-jp'>宿題そっちのけで遊ぶ</span>比较自然。<br>・多半用来描述<b>别人</b>的行为，是新闻、文章常见的书面说法，跟朋友聊天很少这样讲。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>をものともせず</b>＝不把<b>困难、危险</b>放在眼里，带有称赞的意思：<br><span class='gd-jp'>けがをものともせず、彼は最後まで走った。</span>（他不顾受伤，跑完了全程：佩服他）<br><b>をよそに</b>＝不管<b>旁人的心情或周围状况</b>，照自己的意思做：<br><span class='gd-jp'>家族の心配をよそに、彼は最後まで走った。</span>（家人那么担心，他还是跑完了全程：重点在他没理家人）</div><div class='gd-sec'><b>にもかかわらず</b>＝单纯的「虽然～，但是～」：<br><span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（虽然下雨，还是来了很多人）<br>这句只是单纯陈述「虽然下雨，还是来了很多人」，用にもかかわらず最自然。をよそに的重点是「主角对本来该在意、该受影响的事不当一回事，照样我行我素」，所以多用在别人的担心、反对，或景气这类理应造成影响的周围状况。</div><div class='gd-warn'>判断小诀窍：克服困难、值得佩服，用をものともせず；不管别人怎么想、不受周围影响，用をよそに；只是单纯的「虽然～但是」，用にもかかわらず。</div>","n1-70":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ずにはおかない」就是中文的<b>「一定会让人～」「不～绝不罢休」</b>。它有两种用法：一种是某个东西力量太强，<b>一定会</b>让人产生某种感觉；另一种是人下定决心，<b>不做到不罢休</b>。这是 N1 的硬派说法，多半出现在影评、书评、新闻、小说里。</div><div class='gd-sec'>拆开来看比较好记：<span class='gd-jp'>おく</span>有「搁着不管」的意思。「不做～就不会搁着不管」，也就是「一定会做～」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>事物必然引发反应</span>最常见的用法。主语是电影、作品、一句话、一件事，说它<b>一定会</b>让人感动、惊讶、思考。<br>被影响的人用<b>を</b>或<b>に</b>标示（<span class='gd-jp'>人を～させる</span>／<span class='gd-jp'>人に～させる</span>），所以动词多半是<b>使役形</b>，也就是「让某人～」的形：<span class='gd-pair'><span class='gd-jp'>感動する</span> → <span class='gd-jp'>感動させる</span></span>（让人感动）。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、観客を感動させずにはおかない。</span>（这部电影一定会让观众感动）</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説の結末は、読者を驚かせずにはおかないだろう。</span>（这本小说的结局一定会让读者大吃一惊）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の言葉は、聞く人の心を動かさずにはおかない。</span>（他的话一定会打动听的人）</div><div class='gd-sec'><span class='gd-tag'>不做到不罢休</span>主语是人，表示很强的决心，带有「我一定要让它发生」的狠劲。</div><div class='gd-ex-line'>・<span class='gd-jp'>今度こそ、真相を明らかにせずにはおかない。</span>（这次不查清真相，我绝不罢休）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな失礼なことを言われたんだ。必ず謝らせずにはおかない。</span>（被讲了那么没礼貌的话，我一定要让他道歉）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>先把动词变成ない形，再<b>把ない拿掉</b>，加上<b>ずにはおかない</b>。<br><span class='gd-pair'><span class='gd-jp'>感動させる</span> → <span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させずにはおかない</span></span><br><span class='gd-pair'><span class='gd-jp'>動かす</span> → <span class='gd-jp'>動かさない</span> → <span class='gd-jp'>動かさずにはおかない</span></span><br>第三类要特别记：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはおかない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはおかない</span>（こず）</span></div><div class='gd-sec'>另一个写法是ない形<b>直接</b>加<b>ではおかない</b>，ない不用拿掉，意思一样：<br><span class='gd-pair'><span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させないではおかない</span></span><br>「ずには」比较常见，也比较书面。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・する要变<b>せず</b>，不是しず：<span class='gd-jp'>明らかにせずにはおかない</span>。<br>・第一种用法里，被影响的人是用を／に标示的对象，不是主语。<span class='gd-jp'>観客は感動せずにはおかない</span>是错的；要说「电影让观众感动」：<span class='gd-jp'>映画は観客を感動させずにはおかない</span>。<br>・语气很重、很书面，日常聊天说「一定会让人哭」讲<span class='gd-jp'>絶対泣けるよ</span>就好，用ずにはおかない会像在念评论稿。<br>・第二种用法是「拚了命也要做到」的决心，像「吃完这碗拉面」这种小事不要用。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ずにはいられない</b>（N2）＝<b>人自己忍不住</b>：<span class='gd-jp'>この映画を見て、泣かずにはいられなかった。</span>（看了这部电影，我忍不住哭了）<br><b>ずにはおかない</b>＝<b>事物一定会让人</b>那样：<span class='gd-jp'>この映画は、見る人を泣かせずにはおかない。</span>（这部电影一定会让看的人掉泪）</div><div class='gd-sec'><b>ずにはすまない</b>（n1-71）＝照道理、照情况，<b>不做说不过去</b>：<span class='gd-jp'>失礼なことを言ってしまったから、謝らずにはすまない。</span>（我说了失礼的话，不道歉说不过去）<br><b>ずにはおかない</b>＝我<b>非要让它发生</b>：<span class='gd-jp'>失礼なことを言われたから、謝らせずにはおかない。</span>（被说了失礼的话，我一定要让他道歉）</div><div class='gd-warn'>判断小诀窍：「自己忍不住」是ずにはいられない；「东西一定会让人～」或「我非做到不可」是ずにはおかない；「不做说不过去」是ずにはすまない。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着看<span class='gd-jp'>〜ずにはすまない・ないではすまない</span>（n1-71），两个常被一起考，对照着学最清楚。</div>","n1-72":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜を余儀なくされる」就是新闻常讲的<b>「被迫～」</b>。像「受台风影响，活动被迫取消」这种，不是自己想这样做，是<b>情势、大环境逼得你没别的路可走</b>。<span class='gd-jp'>余儀</span>是「别的办法」，<span class='gd-jp'>余儀ない</span>就是「没有别的办法」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>新闻・报导</span>天灾、疫情、经济这类大事件，造成某个人或某个单位只好怎样。</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨で、試合は中止を余儀なくされた。</span>（因为大雨，比赛被迫取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>地震で、多くの住民が避難生活を余儀なくされている。</span>（因为地震，很多居民被迫过着避难生活）</div><div class='gd-sec'><span class='gd-tag'>正式场合讲自己的遭遇</span>写报告、面试说明经历时也会用。</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の倒産で、退職を余儀なくされました。</span>（因为公司倒闭，我不得不离职）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放<b>名词</b>，而且是表示「一个动作」的名词，最常见的是<span class='gd-jp'>中止</span>、<span class='gd-jp'>延期</span>、<span class='gd-jp'>変更</span>、<span class='gd-jp'>撤退</span>、<span class='gd-jp'>入院</span>、<span class='gd-jp'>移転</span>这种后面可以加する的词。<br>手上是动词的话，把する拿掉，留下名词：<span class='gd-pair'><span class='gd-jp'>延期する</span> → <span class='gd-jp'>延期を余儀なくされた</span></span><br>句子的主角（は／が前面那个）是<b>受影响、被逼的那一方</b>：比赛、老店、居民、我。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>余儀なくされた</span>已经发生的事，最常见。<br><span class='gd-tag'>余儀なくされている</span>现在还持续被迫这样，像上面的避难生活。<br><span class='gd-tag'>余儀なくさせる</span>反过来站在「造成原因」那边说，主角常是事件本身：</div><div class='gd-ex-line'>・<span class='gd-jp'>円安が、計画の見直しを余儀なくさせた。</span>（日圆贬值迫使计划重新检讨）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・念<b>よぎなく</b>，不是よぎむなく。<br>・前面不能直接放动词：说<span class='gd-jp'>中止を余儀なくされた</span>，不说「中止するを余儀なくされた」。<br>・自己选的、自己想做的事不能用。换工作是因为想挑战新东西，就不是「被迫」。<br>・口气很重、很正式，鸡毛蒜皮的小事用了会很夸张。「宿題を余儀なくされた」听起来像在开玩笑。<br>・中文说「被迫」，很多人直觉写成させられる，但两个意思不一样，看下面。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「离职」：<br><b>を余儀なくされる</b>＝<b>情势</b>逼的，没人指名道姓逼你，正式、偏书面：<br><span class='gd-jp'>会社の倒産で、退職を余儀なくされた。</span>（因为公司倒闭，被迫离职）<br><b>させられる</b>＝<b>某个人</b>逼你做，常带点不甘愿，口语也常用：<br><span class='gd-jp'>上司に無理やり退職させられた。</span>（被主管硬逼着离职）<br><b>ざるを得ない</b>＝<b>自己</b>衡量过后只好这样，重点在自己的判断：<br><span class='gd-jp'>体調が悪くて、退職せざるを得なかった。</span>（身体不好，我只好离职）</div><div class='gd-warn'>判断小诀窍：有一个「人」在逼你，用させられる；自己想过之后只好做，用ざるを得ない；天灾、景气、时局这种大环境逼得没路走，又是正式场合，用を余儀なくされる。</div>","n1-77":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜んばかりに」就是中文的<b>「简直就要～了」「一副要～的样子」</b>。用夸张的方式形容某个样子到了什么程度：<b>差一点就</b>做出那个动作，但通常<b>还没真的做</b>。像中文说「她急得快哭出来了」，重点是在形容她有多急，不是说她真的哭了。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>先把动词变成ない形，把「ない」拿掉，再加「んばかり」。<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span> → <span class='gd-jp'>泣かんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>あふれる</span> → <span class='gd-jp'>あふれない</span> → <span class='gd-jp'>あふれんばかり</span></span><br><b>する是例外</b>：不是しんばかり，要用古文的说法 <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかり</span></span></div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>んばかりに＋动作</span>形容「怎么做」某个动作。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は泣かんばかりに頼んできた。</span>（她几乎要哭出来似地拜托我）</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が飛びつかんばかりに喜んで走ってきた。</span>（狗高兴得简直要扑上来，冲了过来）</div><div class='gd-sec'><span class='gd-tag'>んばかりの＋名词</span>直接修饰后面的东西。</div><div class='gd-ex-line'>・<span class='gd-jp'>会場は割れんばかりの拍手に包まれた。</span>（全场响起震耳欲聋的掌声）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「お前のせいだ」と言わんばかりの顔で私を見た。</span>（他一副「都是你害的」的表情看着我）</div><div class='gd-sec'><span class='gd-tag'>んばかりだ</span>放在句尾。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の喜びようは、今にも踊り出さんばかりだった。</span>（他高兴得简直要跳起舞来了）</div><div class='gd-sec'>其中<span class='gd-jp'>言わんばかり</span>、<span class='gd-jp'>割れんばかり</span>、<span class='gd-jp'>あふれんばかり</span>、<span class='gd-jp'>泣かんばかり</span>出现得特别多，可以整组记。整体偏书面、小说的语感，不过「<span class='gd-jp'>〜と言わんばかりの顔</span>」在平常讲话也常听到。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的「ん」<b>不是「不」</b>。<span class='gd-jp'>泣かん</span>看起来很像关西腔的「不哭」，但在这个文法里，它是古文里表示「就要～」的ん。<span class='gd-jp'>泣かんばかり</span>是「快哭了」，不是「不哭」。<br>・する要变<b>せんばかり</b>，写成しんばかり是错的。<br>・它是夸张的形容，用来描写<b>样子、程度</b>。如果只是单纯说「看起来快哭了」，日常会话用<span class='gd-jp'>泣きそうな顔</span>就好，用<span class='gd-jp'>泣かんばかり</span>会显得很戏剧化。<br>・通常指「差一点就」，不是真的发生了。<span class='gd-jp'>あふれんばかり</span>是「满到快溢出来」，水还没有真的溢出来。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>とばかりに</b>前面接的是一句「台词」，意思是「一副在说～的样子」。它跟<span class='gd-jp'>と言わんばかりに</span>意思几乎一样：</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」と言わんばかりに時計を見た。</span>（店长一副「快回去」的样子看了看时钟）</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」とばかりに時計を見た。</span>（同上）</div><div class='gd-sec'>差别在前面能放什么。<b>んばかりに</b>前面放的是<b>差点做出来的动作</b>，像是哭、溢出来、跳起来；<b>とばかりに</b>前面放的是<b>心里的话</b>。所以「快哭出来似地」只能说<span class='gd-jp'>泣かんばかりに</span>，不能说泣くとばかりに。</div><div class='gd-warn'>判断小诀窍：前面是「一句话」，用とばかりに或と言わんばかりに都可以；前面是「快做出来的动作」，只能用ない形加んばかりに。</div>","n1-89":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>这组文法就是中文的<b>「没～就～」</b>，分成两种讲法：<br><span class='gd-jp'>なしに</span>：「没打招呼<b>就</b>拿走了」，描述某人<b>没做该做的事就直接做了</b>。<br><span class='gd-jp'>なしには</span>：「没有你，<b>就不可能</b>成功」，说的是<b>少了A，B根本办不到</b>。<br>两个只差一个「は」，用法差很多。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>なしに</span>本来应该有的东西没有，就直接做了。常带一点「这样不对吧」的不满。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は連絡なしに会社を休んだ。</span>（他没说一声就没来上班）</div><div class='gd-ex-line'>・<span class='gd-jp'>断りなしに、人の物を使ってはいけない。</span>（没经过同意，不可以用别人的东西）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一言の断りもなしに帰ってしまった。</span>（他连一声招呼都没打就回去了）</div><div class='gd-sec'>中间加「も」变成<span class='gd-jp'>もなしに</span>，语气更强，有「连～都没有」的感觉。</div><div class='gd-sec'><span class='gd-tag'>なしには</span>A是不可少的条件，没有A，B就办不到。</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、涙なしには見られない。</span>（这部电影看了一定会哭）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功できなかった。</span>（没有大家帮忙，我不可能成功）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功しなかったでしょう。</span>（要是没有大家帮忙，应该不会成功吧）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>直接接：<span class='gd-pair'><span class='gd-jp'>許可</span> → <span class='gd-jp'>許可なしに</span></span><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なしには</span></span><br><b>动词</b>要先加「こと」，变成「辞书形＋ことなしに（は）」，这是比较书面的说法：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は休むことなしに働き続けた。</span>（他一刻也没休息，一直工作）</div><div class='gd-ex-line'>・<span class='gd-jp'>努力することなしには、夢はかなわない。</span>（不努力的话，梦想不会实现）</div><div class='gd-sec'><b>なしには的后半句一定是否定</b>。常见<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>〜られない</span>、<span class='gd-jp'>〜ありえない</span>，也可以用<span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜なかった（でしょう）</span>。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>なしに后面不一定是否定</b>：<span class='gd-jp'>連絡なしに休んだ</span>就是肯定句。后面一定要否定的是<b>なしには</b>。<br>・なしには后面不能接肯定句：×<span class='gd-jp'>協力なしには成功した</span>，这样意思兜不起来。<br>・动词不能直接接：×<span class='gd-jp'>連絡しなしに</span>。要写<span class='gd-jp'>連絡なしに</span>（用名词），或是<span class='gd-jp'>連絡することなしに</span>。<br>・这是偏正式、书面的说法。平常讲话多半说<b>なしで</b>：<span class='gd-jp'>予約なしで入れますか。</span>（没预约可以进去吗）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「没预约」：<br><span class='gd-jp'>予約なしに店に入った。</span>（没预约就进店了：交代他是<b>怎么做的</b>）<br><span class='gd-jp'>予約なしには入れない。</span>（没预约就进不去：讲<b>必要条件</b>）</div><div class='gd-sec'><b>なくして（は）</b>：意思跟なしには几乎一样，但更硬，多用在演讲、文章。<br><span class='gd-jp'>皆さんの協力なくしては、成功はありえなかった。</span>（没有各位的协助，就不可能成功）</div><div class='gd-sec'><b>あっての</b>：同一件事从反方向讲，「有A才有B」。<br><span class='gd-jp'>お客様あっての店だ。</span>（有客人才有这家店）<br>＝<span class='gd-jp'>お客様なしには、店は成り立たない。</span>（没有客人，店就开不下去）</div><div class='gd-warn'>判断小诀窍：「没～就做了」用なしに；「没～就不可能」用なしには（后面一定否定）；想讲得更正式就换なくしては；想从「有A才有B」的角度讲就用あっての。</div>","n1-91":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に足る」就是中文的<b>「足以～」「值得～」</b>，意思是这个人或这件事<b>够格</b>让人去信赖、尊敬、满意。反过来的「〜に足りない」就像<b>「不足为惧」「不足挂齿」</b>，也就是不值得、没必要。「足る」念<b>たる</b>，是很硬的书面说法，常出现在新闻、评论、小说里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>动词辞书形＋に足る</b>：<span class='gd-pair'><span class='gd-jp'>信頼する</span> → <span class='gd-jp'>信頼するに足る</span></span><span class='gd-pair'><span class='gd-jp'>満足する</span> → <span class='gd-jp'>満足するに足る</span></span><br><b>「〜する」动词把する拿掉，用前面的名词直接接</b>：<span class='gd-pair'><span class='gd-jp'>信頼</span> → <span class='gd-jp'>信頼に足る</span></span><span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に足る</span></span><br>大多放在名词前面当形容，像「<span class='gd-jp'>信頼に足る人物</span>」，也可以放句尾当结论。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>に足る</span>正式地评价人、资料、理由、结果「够格、达到标准」。常搭配<span class='gd-jp'>信頼する・尊敬する・満足する・納得する・信じる</span>这类「评价」的动词。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は尊敬に足る先輩だ。</span>（她是值得尊敬的前辈）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、納得するに足るものだった。</span>（他的说明足以让人信服）</div><div class='gd-ex-line'>・<span class='gd-jp'>この報告書には、信頼に足るデータがない。</span>（这份报告里没有可以信赖的数据）</div><div class='gd-sec'><span class='gd-tag'>に足りない</span>说某件事根本不重要、不用怕。多半用在几个固定说法，<span class='gd-jp'>に足らない</span>也常见，意思一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなのは取るに足りない問題だ。</span>（那只是不足挂齿的小问题）</div><div class='gd-ex-line'>・<span class='gd-jp'>相手は新人ばかりだ。恐れるに足りない。</span>（对手都是新人，不足为惧）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<span class='gd-jp'>取るに足りない</span>不是「不够拿」，是一整组背起来的「微不足道」。跟<span class='gd-jp'>お金が足りない</span>（钱不够）的「不够」是两回事。<br>・前面只能接<b>辞书形</b>或「する动词的名词」，不能接た形、ます形：<span class='gd-jp'>信頼したに足る</span>是错的。也不能随便接一般名词，像<span class='gd-jp'>彼に足る</span>就不通。<br>・否定的<span class='gd-jp'>に足りない</span>主要用在<span class='gd-jp'>取るに足りない</span>、<span class='gd-jp'>恐れるに足りない</span>这类固定说法。一般想说「不值得信任」，用<span class='gd-jp'>信頼できない</span>或<span class='gd-jp'>信頼に値しない</span>比较自然。<br>・这是书面语，跟朋友聊天说「那个人很可靠」，讲<span class='gd-jp'>あの人は信頼できる</span>就好，讲に足る会很像在念公文。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是在评价一本书：<br><b>に足る</b>＝够格、达到标准：<span class='gd-jp'>これは読むに足る本だ。</span>（这是一本值得读的书）<br><b>に値する</b>＝有那个价值，意思很接近，很多时候可以互换。差别是它的否定<span class='gd-jp'>に値しない</span>可以自由使用：<span class='gd-jp'>この本は一読に値しない。</span>（这本书不值得一读）<br><b>に堪えない</b>（n1-36）＝烂到让人<b>受不了</b>，带有强烈的情绪：<span class='gd-jp'>読むに堪えない文章だ。</span>（是让人看不下去的文章）<br>所以「<span class='gd-jp'>取るに足りない</span>」是「不重要、不用在意」，「<span class='gd-jp'>見るに堪えない</span>」是「太糟了，看不下去」，两者方向完全不同。</div><div class='gd-warn'>判断小诀窍：「足以～／不足挂齿」用に足る・に足りない；想自由地说「不值得～」用に値しない；「糟到受不了」用に堪えない。</div>","n1-93":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜たが最後」就是中文的<b>「一旦～就完了」「一沾上就回不去」</b>。只要做了前面那件事，后面就一定会变成很糟、收不回来、停不下来的状况。像是「洋芋片一打开就完了，一定整包吃光」，就是这种感觉。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词先变成た形（就是「〜た」过去的样子），后面直接加「が最後」。<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝た</span> → <span class='gd-jp'>寝たが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>見つかる</span> → <span class='gd-jp'>見つかった</span> → <span class='gd-jp'>見つかったが最後</span></span><br>「最后」念<b>さいご</b>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>说某人的习性</span>某个人只要一做某件事，就一定会怎样。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一度寝たが最後、朝まで何をしても起きない。</span>（他一旦睡着就完了，到早上前怎么弄都叫不醒）</div><div class='gd-sec'><span class='gd-tag'>停不下来</span>开了头就收不了手。</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは見始めたが最後、止まらなくなる。</span>（这部剧一开始看就停不下来）</div><div class='gd-sec'><span class='gd-tag'>警告后果</span>提醒「千万别这样，不然下场很惨」。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長に見つかったが最後、一時間は説教される。</span>（被部长发现就完了，至少被念一个小时）</div><div class='gd-sec'>讲话时常换成<b>「〜たら最後」</b>，意思一样，口气比较口语：</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと言ったら最後、絶交されるよ。</span>（那种话一说出口就完了，会被绝交喔）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面<b>只能放坏结果</b>。「一中乐透就过上好日子」这种好事不能用が最後。<br>・前面一定是た形，就算讲的是还没发生的事也一样。不能说「食べるが最後」。<br>・这里的「最后」不是中文的「最后、终于」，而是「到此为止、完蛋了」的意思。不要翻成「吃了之后最后……」。<br>・后面通常是「一定会这样」的描述或判断，很少接「请～」「我要～」这种请求或决心。<br>・后面常搭配<span class='gd-jp'>二度と〜ない</span>、<span class='gd-jp'>止まらない</span>、<span class='gd-jp'>終わりだ</span>这类「回不去」的说法。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>〜が早いか</b>：也常翻成「一～就」，但它只是在说<b>时间很快</b>，不管好坏。<br>・<span class='gd-jp'>彼は布団に入るが早いか、眠ってしまった。</span>（他一钻进被窝，马上就睡着了）<br>・<span class='gd-jp'>彼は布団に入ったが最後、昼まで出てこない。</span>（他一钻进被窝就完了，不到中午不会出来）<br>前一句是「速度快」，后一句是「之后就收不回来」。</div><div class='gd-sec'><b>〜たところで</b>：一样接在た形后面，但意思是<b>「就算做了也没用」</b>。<br>・<span class='gd-jp'>彼に話したが最後、みんなに知られてしまう。</span>（一跟他说就完了，大家都会知道）<br>・<span class='gd-jp'>今さら彼に話したところで、何も変わらない。</span>（现在才跟他说，也改变不了什么）</div><div class='gd-warn'>判断小诀窍：「做了就回不去、后果很惨」是が最後；「一～马上就」是が早いか；「做了也没用」是たところで。</div>","n1-18":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に至る」就像新闻里常说的<b>「演变成～」「最后走到～这一步」</b>。事情经过一段时间、一连串的发展，最后到了某个结果。这个结果通常是有分量的事，例如打官司、倒闭、和解、做出结论。它很书面、很正式，新闻、报告、记者会、公司说明最常出现。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>：直接加に至る，中间不加の。<br><span class='gd-pair'><span class='gd-jp'>訴訟</span> → <span class='gd-jp'>訴訟に至る</span></span><span class='gd-pair'><span class='gd-jp'>和解</span> → <span class='gd-jp'>和解に至る</span></span><br><b>动词</b>：用辞书形（字典上那个原本的样子）加に至る。<br><span class='gd-pair'><span class='gd-jp'>中止する</span> → <span class='gd-jp'>中止するに至る</span></span><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えるに至る</span></span></div><div class='gd-sec'><span class='gd-jp'>至る</span>本身是<b>第一类（五段动词）</b>，变化跟<span class='gd-jp'>帰る</span>一样：<br><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至った</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至っていない</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至らなかった</span></span></div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>最后走到某个结果</span>最常用过去式「〜に至った」，前面常有<span class='gd-jp'>ついに</span>、<span class='gd-jp'>〜の末</span>、<span class='gd-jp'>〜結果</span>，交代「经过了一段过程」。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、両社は合併に至った。</span>（经过长时间协商，两家公司最后决定合并）</div><div class='gd-ex-line'>・<span class='gd-jp'>留学を通して、日本で働きたいと考えるに至った。</span>（透过留学，我渐渐有了想在日本工作的念头）</div><div class='gd-sec'><span class='gd-tag'>还没到那一步</span>否定常写成「〜には至っていない」，说事情还没发展到那个阶段。</div><div class='gd-ex-line'>・<span class='gd-jp'>この技術は、まだ実用化には至っていない。</span>（这项技术还没到能实际应用的阶段）</div><div class='gd-sec'><span class='gd-tag'>固定说法</span>下面三个很常见，可以整句记。</div><div class='gd-ex-line'>・<span class='gd-jp'>幸い、大事には至らなかった。</span>（还好没有酿成大祸）</div><div class='gd-ex-line'>・<span class='gd-jp'>中止に至った経緯をご説明します。</span>（向各位说明决定停办的来龙去脉）</div><div class='gd-ex-line'>・<span class='gd-jp'>1990年に創業し、現在に至る。</span>（1990年创立，一直经营到现在）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・动词要用辞书形，不要用た形：是<span class='gd-jp'>中止するに至った</span>，不是「中止したに至った」。过去的意思放在<span class='gd-jp'>至った</span>上就好。<br>・它很书面。跟朋友聊天说「我们最后分手了」，讲<span class='gd-jp'>結局別れることになった</span>就好。讲成「別れるに至った」，听起来像在念新闻稿。<br>・结果要有分量，前面通常是一段过程。肚子饿去买面包这种小事不能用「パンを買うに至った」。<br>・虽然字面是「到达」，日常的「到了某个地方」要用<span class='gd-jp'>着く</span>。<br>・<span class='gd-jp'>至らない</span>单独用的时候，常是另一个意思「不周到」：<span class='gd-jp'>至らない点もありますが、よろしくお願いします。</span>（可能有不周到的地方，还请多多指教）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>N1 有三个长得很像的「至る」家族，用同一个情境「公司状况很差」来比：<br><b>に至る</b>＝事情<b>最后演变成</b>某个结果：<br><span class='gd-jp'>赤字が続き、ついに倒産に至った。</span>（持续亏损，最后走到倒闭）<br><b>に至るまで</b>＝说范围<b>从A一直到B，连B都</b>：<br><span class='gd-jp'>社長から新入社員に至るまで、全員が毎日残業している。</span>（从社长到新进员工，全部的人每天都在加班）<br><b>に至っては</b>＝<b>至于B，更是夸张</b>，挑出最极端的例子：<br><span class='gd-jp'>どの部署も業績が悪いが、営業部に至っては目標の半分にも届いていない。</span>（每个部门业绩都很差，营业部更惨，连目标的一半都不到）</div><div class='gd-warn'>判断小诀窍：放在句尾讲「最后变成怎样」的是に至る；前面有「AからB」、在讲范围的是に至るまで；放在句子中间当话题、带出「更夸张的那个」的是に至っては。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着学<span class='gd-jp'>〜に至るまで</span>和<span class='gd-jp'>〜に至っては</span>，三个一起记最不会混。也可以学<span class='gd-jp'>〜を経て</span>（经过～），它常跟に至る一起出现：<span class='gd-jp'>何度もの議論を経て、合意に至った。</span>（经过好几次讨论，最后达成了共识）</div>","n1-19":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に至るまで」就是中文的<b>「上至～下至～」「大到～小到～，通通都～」</b>。说「从老板到工读生，全部都参加了」，重点不在「到哪里停」，而是在强调<b>连那么远、那么细的地方都包含在内</b>，范围很广。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋に至るまで，最常见的是跟「から」搭配：<br><b>Aから Bに至るまで</b>＝从 A 一直到（连）B（都）<br><span class='gd-pair'><span class='gd-jp'>子供から高齢者</span> → <span class='gd-jp'>子供から高齢者に至るまで</span></span>（从小孩到老人）<br>B 通常放范围的<b>另一端</b>，而且常常是「没想到连这个也算进去」的那一端。后面常接<span class='gd-jp'>全員</span>、<span class='gd-jp'>すべて</span>、<span class='gd-jp'>誰もが</span>、<span class='gd-jp'>細かく</span>这类「全部」的字。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>人的范围</span>从上到下、从老到小，所有人都包括。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長から新入社員に至るまで、全員が会議に参加した。</span>（从社长到新进员工，全员都参加了会议）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供から高齢者に至るまで、誰もが楽しめるイベントだ。</span>（从小孩到老人，每个人都能玩得开心的活动）</div><div class='gd-sec'><span class='gd-tag'>细节的范围</span>从大方向到小细节，全部顾到。</div><div class='gd-ex-line'>・<span class='gd-jp'>服装から髪型に至るまで、細かく決められている。</span>（从服装到发型，连细节都有规定）</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋の隅々に至るまで、きれいに掃除した。</span>（连房间的每个角落都打扫得干干净净）</div><div class='gd-sec'><span class='gd-tag'>时间的范围</span>从很久以前一路到现在，强调时间拉得很长。</div><div class='gd-ex-line'>・<span class='gd-jp'>創業から現在に至るまで、この味を守り続けている。</span>（从创业到现在，一直守着这个味道）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・中文的「直到～为止」很容易让人以为它是在<b>划界线、设上限</b>，其实刚好相反：它不是「只到这里」，而是「<b>连这里都包含了</b>」，重点是范围广。<br>・A 跟 B 要是<b>同一类东西</b>的两端：人对人、东西对东西、时间对时间。<br>・单纯讲「等到几点」「走到车站」这种普通的终点，用<span class='gd-jp'>まで</span>就好，用に至るまで会很怪。<br>・这是<b>正式、书面</b>的说法，常出现在新闻、公告、公司介绍。跟朋友聊天说<span class='gd-jp'>おじいちゃんまでみんなスマホ持ってるよ</span>（连阿公都有手机耶）这样就够了。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「至る」，N1 有三个很容易混。用同一个情境「家人跟智慧型手机」来比：<br><b>に至るまで</b>＝范围很广，<b>全部都包括</b>：<br><span class='gd-jp'>祖父母から孫に至るまで、家族全員がスマホを持っている。</span>（从爷爷奶奶到孙子，全家人都有智慧型手机）<br><b>に至っては</b>＝从一群里<b>挑出最夸张的那一个</b>来讲，多半带点批评：<br><span class='gd-jp'>うちの家族は機械に弱い。祖母に至っては、電話のかけ方も知らない。</span>（我家人都不太会用机器，至于奶奶，她连电话都不会打）<br><b>に至る</b>＝事情一路发展，<b>终于走到某个结果</b>：<br><span class='gd-jp'>何度も話し合って、ようやく祖母もスマホを買うに至った。</span>（讨论了好几次，奶奶终于买了智慧型手机）</div><div class='gd-warn'>判断小诀窍：讲「从～到～，全部都」用に至るまで；讲「其中最夸张的是～」用に至っては；讲「最后演变成～」用に至る。</div>","n1-20":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜を経て」就是中文的<b>「历经～」「经过～」「经由～」</b>。重点是中间<b>走过一段过程、一个阶段，或路过某个地方</b>，然后才到后面的结果。语气正式，新闻、报告、人物简介、演讲里很常见，跟朋友聊天比较少用。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋を経て　<span class='gd-pair'><span class='gd-jp'>長い議論</span> → <span class='gd-jp'>長い議論を経て</span>（经过漫长的讨论）</span><br>前面只接<b>名词</b>，不能直接接动词。要讲「准备」这件事，就写<span class='gd-jp'>準備を経て</span>，不能写成「準備するを経て」。<br>「経て」念<b>へて</b>，原形是<span class='gd-jp'>経る</span>（へる），意思就是「经过」。</div><div class='gd-sec'>后面要接名词时，改成<b>を経た＋名词</b>：<br><span class='gd-pair'><span class='gd-jp'>厳しい訓練</span> → <span class='gd-jp'>厳しい訓練を経た選手</span>（经过严格训练的选手）</span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>经过一段过程</span>讨论、审查、谈判、准备这类要花时间、花力气的事，做完之后才有结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>長い議論を経て、ようやく結論が出た。</span>（经过漫长的讨论，终于有了结论）</div><div class='gd-ex-line'>・<span class='gd-jp'>厳しい審査を経て、新しい薬が発売された。</span>（经过严格审查，新药上市了）</div><div class='gd-sec'><span class='gd-tag'>经过一段时间</span>常跟「歳月」「年月」一起用，有「历经多少年」的感觉。</div><div class='gd-ex-line'>・<span class='gd-jp'>10年の歳月を経て、橋が完成した。</span>（历经十年岁月，桥终于完成了）</div><div class='gd-sec'><span class='gd-tag'>经历某个身分</span>人物简介超常见，讲一个人走过哪些阶段。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社員を経て、作家になった。</span>（他当过上班族之后，成为作家）</div><div class='gd-sec'><span class='gd-tag'>经由某个地方</span>移动路线中间路过的地点。</div><div class='gd-ex-line'>・<span class='gd-jp'>香港を経て、日本に着いた。</span>（经由香港，抵达日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>台北から台中を経て、高雄へ向かう。</span>（从台北经台中，前往高雄）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・「経て」念<b>へて</b>，不是けいて，也不是たって。<br>・同一个「経」还有<span class='gd-jp'>経つ</span>（たつ），意思是「时间过去」：<span class='gd-jp'>3年経って</span>念さんねんたって，是一般口语的「过了三年」。两个长得很像，念法和语气都不一样。<br>・这是正式的说法。跟朋友说「转机经过香港」，讲<span class='gd-jp'>香港経由で</span>或<span class='gd-jp'>香港で乗り換えて</span>比较自然；日常小事用「を経て」会很像在念新闻稿。<br>・前面要放<b>值得一提的过程</b>。吃个饭、洗个澡这种小事，用「〜てから」就好，不会用「を経て」。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>を経て vs 経って</b>：都能讲「过了一段时间」。<br><span class='gd-jp'>3年経って、やっと仕事に慣れた。</span>（过了三年，终于习惯工作了）：口语，时间后面直接接「経って」，不加を。<br><span class='gd-jp'>3年の歳月を経て、作品が完成した。</span>（历经三年岁月，作品完成了）：正式，多半带出「花了很多工夫才有成果」的感觉。</div><div class='gd-sec'><b>を経て vs に至る</b>：常常一起出现，但位置不一样。<br><span class='gd-jp'>何度もの交渉を経て、合意に至った。</span>（经过多次谈判，最后达成协议）<br>「を経て」讲<b>中间走过的路</b>，「に至る」讲<b>最后抵达的终点</b>。</div><div class='gd-warn'>判断小诀窍：讲中间经过了什么，用「を経て」；讲最后走到哪里，用「に至る」；只是随口说「过了几年」，用「経って」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同一级的<span class='gd-jp'>〜に至る</span>、<span class='gd-jp'>〜に至るまで</span>，可以跟「を経て」一起记，写「过程到结果」的文章时很好用。</div>","n1-38":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に難くない」就是中文的<b>「不难想像」「不难理解」「可想而知」</b>。用法是用一点点线索，就能推想出背后的情况或心情。读音是<b>かたくない</b>，偏书面、正式，新闻、评论、文章里很常见。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面几乎都是「在脑中推想」的词，固定那几个，直接整组背最快：<br><span class='gd-jp'>想像に難くない</span>（不难想像）<br><span class='gd-jp'>理解に難くない</span>（不难理解）<br><span class='gd-jp'>予想に難くない</span>（不难预料）<br><span class='gd-jp'>推測に難くない</span>（不难推测）<br><span class='gd-jp'>察するに難くない</span>（不难察觉、猜到）<br>想像、理解这类词通常直接用名词接「に」。<span class='gd-jp'>察する</span>本身是动词，就用原形（辞书形）接。</div><div class='gd-sec'>你推想出来的内容放前面，常见三种样子：「〜は」「〜ことは」「〜のは」。</div><div class='gd-ex-line'>・<span class='gd-jp'>親を亡くした彼の悲しみは想像に難くない。</span>（失去父母的他有多悲伤，不难想像）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画に反対の声が上がることは予想に難くない。</span>（不难预料这个计划会引来反对声浪）</div><div class='gd-ex-line'>・<span class='gd-jp'>物価がこれだけ上がれば、生活が苦しくなるのは想像に難くない。</span>（物价涨成这样，生活会变辛苦是可想而知的）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の表情から、何があったかは察するに難くない。</span>（从她的表情，不难猜到发生了什么事）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・「難くない」念<b>かたくない</b>，不要念成むずかしくない。<br>・它讲的是「脑中<b>推想</b>起来不难」，不是「<b>做</b>起来简单」。想说「这题很好解」，要说<span class='gd-jp'>この問題は簡単だ</span>，不能用に難くない。<br>・前面别乱套动词，用想像、理解、予想、推测、察する这几个就好。<br>・它很硬，日常聊天不会这样讲。跟朋友说「可想而知」，用<span class='gd-jp'>想像できる</span>或<span class='gd-jp'>想像がつく</span>就自然了。<br>・看到「ない」不要以为是否定的意思。「難くない」＝不难＝<b>很容易</b>，整句是肯定的语气。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>N1 有好几个「〜に＋否定」的句型，长得很像，意思却差很多。用同一个情境比比看：朋友被公司裁员了。<br><b>に難くない</b>＝不难推想：<span class='gd-jp'>彼のショックは想像に難くない。</span>（不难想像他受到多大的打击）<br><b>には当たらない</b>＝没必要那样反应：<span class='gd-jp'>この不景気だから、リストラされても驚くには当たらない。</span>（景气这么差，被裁员也不必惊讶）<br><b>に堪えない</b>＝糟到看不下去、听不下去：<span class='gd-jp'>会社の説明は聞くに堪えない言い訳ばかりだった。</span>（公司的说明全是让人听不下去的借口）</div><div class='gd-warn'>判断小诀窍：「可想而知」是に難くない；「犯不着～」是には当たらない；「惨到受不了」是に堪えない。</div>","n1-37":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜を禁じ得ない」就是中文的<b>「不禁～」「忍不住感到～」</b>。看到、听到某件事，同情、惊讶、愤怒这类情绪自己涌上来，想压也压不住。它很正式，多半出现在新闻评论、文章、演讲里，平常聊天几乎不会讲。</div><div class='gd-h'>拆开来看就懂了</div><div class='gd-sec'><span class='gd-jp'>禁じる</span>是「禁止」，<span class='gd-jp'>得ない</span>是「无法～」。合起来就是「想禁止也禁止不了」，也就是那个情绪挡不住、自己冒出来了。<br>念法是<b>きんじえない</b>，「得」在这里念「え」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放<b>表示情绪的名词</b>，加「を禁じ得ない」。讲过去的事就变成「を禁じ得なかった」。<br><span class='gd-pair'><span class='gd-jp'>同情</span> → <span class='gd-jp'>同情を禁じ得ない</span></span>（不禁同情）<br><span class='gd-pair'><span class='gd-jp'>驚き</span> → <span class='gd-jp'>驚きを禁じ得なかった</span></span>（当时不禁大吃一惊）<br>常搭配的名词：<span class='gd-jp'>同情</span>、<span class='gd-jp'>驚き</span>、<span class='gd-jp'>怒り</span>、<span class='gd-jp'>憤り</span>、<span class='gd-jp'>涙</span>、<span class='gd-jp'>戸惑い</span>、<span class='gd-jp'>疑問</span>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>被事情触动</span>前面通常会先交代「看到什么、听到什么、想到什么」，后面再说情绪压不住。</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞いて、驚きを禁じ得なかった。</span>（听到那个消息，我不禁大吃一惊）</div><div class='gd-ex-line'>・<span class='gd-jp'>被害者の話を聞き、涙を禁じ得なかった。</span>（听了受害者的叙述，我忍不住流下眼泪）</div><div class='gd-sec'><span class='gd-tag'>正式表态</span>评论、社论里用来表达强烈的看法，很常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>政府の対応には、怒りを禁じ得ない。</span>（对政府的处理方式，我不禁感到愤怒）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には疑問を禁じ得ない。</span>（对这个计划，我不禁抱持疑问）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放<b>名词</b>，不能直接放动词：要说<span class='gd-jp'>涙を禁じ得ない</span>、<span class='gd-jp'>驚きを禁じ得ない</span>，不能说「泣くを禁じ得ない」「驚くを禁じ得ない」。<br>・它讲的是<b>自己</b>涌上来的情绪，不是用来描述别人的心情。<br>・语气非常硬。跟朋友聊天说「感動を禁じ得なかった」会像在念稿，口语讲<span class='gd-jp'>思わず泣いちゃった</span>（我忍不住哭了）就好。<br>・「得ない」念<b>えない</b>，不要念成うない。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境：听了他的遭遇，觉得很同情。<br><b>を禁じ得ない</b>＝情绪<b>涌上来、压不住</b>，很正式，前面接名词：<br><span class='gd-jp'>彼の話を聞いて、同情を禁じ得なかった。</span>（听了他的话，我不禁同情起他）<br><b>ずにはいられない</b>（N2）＝「忍不住会～」，前面接动词，也可以讲动作，比较常用、没那么硬：<br><span class='gd-jp'>彼の話を聞いて、同情せずにはいられなかった。</span>（听了他的话，我忍不住同情他）<br><span class='gd-jp'>あまりにおかしくて、笑わずにはいられなかった。</span>（实在太好笑，我忍不住笑出来）<br><b>に堪えない</b>放情绪名词时是「～到了极点、非常～」，常见的有<span class='gd-jp'>感謝に堪えない</span>（感激不尽）、<span class='gd-jp'>遺憾に堪えない</span>、<span class='gd-jp'>同情に堪えない</span>、<span class='gd-jp'>憤慨に堪えない</span>，多用在正式致词或文章。语感偏向「情绪强烈到承受不住」：<br><span class='gd-jp'>被災された方々のことを思うと、同情に堪えない。</span>（想到受灾的各位，实在令人同情不已）<br>另外，に堪えない接动词时是另一种意思：<span class='gd-jp'>見るに堪えない</span>是「惨到看不下去」，跟を禁じ得ない无关，别混在一起。</div><div class='gd-warn'>判断小诀窍：情绪「冒出来压不住」用を禁じ得ない；情绪「强烈到承受不住、～到极点」用に堪えない；一般讲「忍不住去做」用ずにはいられない。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同一组讲强烈情绪的N1文法还有<span class='gd-jp'>〜て止まない</span>（打从心底一直～），例如<span class='gd-jp'>皆様のご健康を願って止みません。</span>（衷心祝福各位身体健康），常出现在致词和信件结尾。</div>","n1-36":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に堪えない」有两个方向刚好相反的意思，中文都能找到对应：<br>①<b>「不堪入目、不堪入耳」</b>：东西糟到、惨到让人看不下去、听不下去。<br>②<b>「不胜感激、不胜感慨」</b>：心里的情绪满到装不下，也就是「非常～」。<br>两种都很书面、很正式，日常聊天几乎不会讲。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>①<b>动词辞书形＋に堪えない</b>：前面几乎只放「看、听、读」这三个动作。<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに堪えない</span></span><br>②<b>感情名词＋に堪えない</b>：最常见的是<span class='gd-jp'>感謝</span>、<span class='gd-jp'>感激</span>、<span class='gd-jp'>感慨</span>、<span class='gd-jp'>遺憾</span>、<span class='gd-jp'>痛恨</span>这几个词。<br><span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝に堪えません</span></span><span class='gd-pair'><span class='gd-jp'>遺憾</span> → <span class='gd-jp'>遺憾に堪えない</span></span><br>「堪えない」念<b>たえない</b>，也常直接写成平假名「たえない」。</div><div class='gd-h'>用法①：糟到看不下去</div><div class='gd-sec'><span class='gd-tag'>批评、嫌弃</span>说的是内容太差、太难听、太惨，不值得看、听、读。后面常直接接名词，例如「聞くに堪えない悪口」。</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くに堪えない悪口だった。</span>（那些坏话难听到不堪入耳）</div><div class='gd-ex-line'>・<span class='gd-jp'>この翻訳はひどくて、読むに堪えない。</span>（这份翻译烂到读不下去）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の現場は見るに堪えない状態だった。</span>（事故现场惨不忍睹）</div><div class='gd-h'>用法②：情绪满到装不下</div><div class='gd-sec'><span class='gd-tag'>正式致词</span>常出现在致词、感谢信、道歉声明、悼词，讲的是<b>自己</b>的强烈感受。当面对人讲通常说「〜に堪えません」。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様の温かいご支援に、感謝の念に堪えません。</span>（对各位温暖的支持，不胜感激）</div><div class='gd-ex-line'>・<span class='gd-jp'>このような事態となり、誠に遺憾に堪えません。</span>（演变成这样的局面，我们深感遗憾）</div><div class='gd-ex-line'>・<span class='gd-jp'>二十年ぶりに母校を訪れ、感慨に堪えない。</span>（睽违二十年回到母校，不胜感慨）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・②<b>不是负面意思</b>。「<span class='gd-jp'>感謝に堪えない</span>」不是「感谢到受不了、很烦」，而是「感谢到心里装不下」，等于「非常感谢」。<br>・不能拿来讲身体上的忍耐。热到受不了要说<span class='gd-jp'>暑くてたまらない</span>或<span class='gd-jp'>暑さに耐えられない</span>，不能说暑さに堪えない。<br>・①是在批评东西本身太糟或太惨，不是「我没空看」「我不想看」。<br>・②非常正式，跟朋友讲「感謝に堪えない」会像在发表演讲，平常说<span class='gd-jp'>本当にありがとう</span>就好。<br>・②前面要放「感谢、遗憾」这类汉字感情名词，不能直接接形容词，例如不能说悲しいに堪えない。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「一场事故」，三种说法的感觉不一样：<br><b>に堪えない</b>＝正式场合表达自己<b>极深的感受</b>，像官方声明：<br><span class='gd-jp'>このような事故が起きたことは、誠に遺憾に堪えません。</span>（发生这样的事故，我们深感遗憾）<br><b>を禁じ得ない</b>＝某件事让人<b>忍不住涌出</b>某种情绪，重点在「控制不住」：<br><span class='gd-jp'>遺族の話を聞いて、涙を禁じ得なかった。</span>（听了遗族的话，我忍不住落泪）<br><b>てたまらない</b>＝口语的「～得不得了」，讲个人的感觉或生理感受：<br><span class='gd-jp'>あの映像を思い出すと、つらくてたまらない。</span>（一想到那个画面就难过得不得了）</div><div class='gd-warn'>判断小诀窍：发表声明、致词说「不胜～」用に堪えない；「忍不住～」用を禁じ得ない；跟朋友讲「～得要命」用てたまらない。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>改成肯定形「〜に堪える」，意思会变成「经得起～、值得～」：<span class='gd-jp'>大人の鑑賞に堪える作品だ。</span>（这是值得大人欣赏的作品）。意思接近的还有「〜に足る」，可以一起学。</div>","n1-39":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜てやまない」就是中文的<b>「衷心～」「～不已」</b>。<span class='gd-jp'>やむ</span>是「停止」，像<span class='gd-jp'>雨がやむ</span>（雨停了）。所以<span class='gd-jp'>願ってやまない</span>直翻是「愿望停不下来」，也就是一直放在心里、很深很强烈的感情。这是正式的书面说法，常出现在致词、贺词、文章里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词て形＋やまない。一般写平假名<span class='gd-jp'>やまない</span>，比较少写汉字。<br><span class='gd-pair'><span class='gd-jp'>願う</span> → <span class='gd-jp'>願って</span> → <span class='gd-jp'>願ってやまない</span></span><br><span class='gd-pair'><span class='gd-jp'>期待する</span> → <span class='gd-jp'>期待して</span> → <span class='gd-jp'>期待してやまない</span></span><br>正式场合讲给人听，用礼貌形<span class='gd-jp'>やみません</span>；讲过去的事用<span class='gd-jp'>やまなかった</span>。<br>前面几乎都是表达心情的动词：<span class='gd-jp'>願う</span>、<span class='gd-jp'>祈る</span>、<span class='gd-jp'>望む</span>、<span class='gd-jp'>期待する</span>、<span class='gd-jp'>愛する</span>、<span class='gd-jp'>尊敬する</span>、<span class='gd-jp'>信じる</span>、<span class='gd-jp'>憧れる</span>。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>致词・贺词</span>祝福对方，最典型的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご健康を祈ってやみません。</span>（衷心祝福各位身体健康）</div><div class='gd-sec'><span class='gd-tag'>自己的信念</span>写文章表达自己长久以来的想法。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は彼の才能を信じてやまない。</span>（我始终深信他的才华）</div><div class='gd-sec'><span class='gd-tag'>让人着迷</span>主词是东西，表示它一直深深吸引人。</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の景色は、今も多くの人を魅了してやまない。</span>（这座城镇的景色，至今仍让许多人着迷不已）</div><div class='gd-sec'><span class='gd-tag'>修饰名词</span>讲别人的感情时，常放在名词前面当形容。</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父が愛してやまなかった海</span>（爷爷一生深爱的那片海）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・摘要写「不停地」，但它<b>不是</b>拿来说动作一直持续。<span class='gd-jp'>雨が降ってやまない</span>、<span class='gd-jp'>走ってやまない</span>都不对，雨一直下就直接说<span class='gd-jp'>雨がやまない</span>。它只用在<b>心情、愿望</b>。<br>・只接动词，不接形容词。「开心得不得了」不能说嬉しくてやまない，要说<span class='gd-jp'>嬉しくてたまらない</span>。<br>・这是很正式的说法，跟朋友聊天讲<span class='gd-jp'>君を愛してやまない</span>，听起来会像在念稿。<br>・正式场合讲给人听，用<span class='gd-jp'>願ってやみません</span>，不要说成願ってやまないです。<br>・放在句尾时，主词通常是「我」。讲别人的感情，多半出现在写文章，或像上面那样放在名词前面。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「故乡」，三种感情不一样：<br><b>てやまない</b>＝长久放在心里的深厚感情，书面：<span class='gd-jp'>故郷を愛してやまない。</span>（深爱着故乡）<br><b>てたまらない</b>（N2）＝现在的感觉强烈到受不了，口语也能用：<span class='gd-jp'>故郷に帰りたくてたまらない。</span>（好想回故乡，想得受不了）<br><b>を禁じ得ない</b>＝看到某件事，忍不住涌上的感情：<span class='gd-jp'>故郷の変わりように驚きを禁じ得ない。</span>（看到故乡的改变，不禁感到惊讶）</div><div class='gd-warn'>判断小诀窍：长年的心愿、爱、信念用<span class='gd-jp'>てやまない</span>；当下难受、好想要用<span class='gd-jp'>てたまらない</span>；被某件事触动、忍不住产生的反应用<span class='gd-jp'>を禁じ得ない</span>。</div>","n1-34":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜極まりない」就是中文的<b>「～至极」「～到了极点」</b>，像「无礼至极」「危险至极」。它专门用来<b>很重地批评</b>一件事，口气跟新闻、评论、正式抗议信一样硬。「〜極まる」意思一样，只是更文言一点。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>严厉批评</span>对别人的态度、行为下很重的评语。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店員の対応は失礼極まりない。</span>（那个店员的应对无礼至极）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に大声で騒ぐなんて、迷惑極まりない。</span>（半夜大声吵闹，真是扰人到了极点）</div><div class='gd-sec'><span class='gd-tag'>描述很糟的状况</span>新闻、报告讲危险、麻烦的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の夜に無灯火で走るのは危険極まりない。</span>（下雨的晚上不开灯骑车，危险到了极点）</div><div class='gd-sec'><span class='gd-tag'>放在名词前面</span>直接拿来形容后面的东西。</div><div class='gd-ex-line'>・<span class='gd-jp'>退屈極まりない会議が三時間も続いた。</span>（无聊透顶的会议整整开了三个小时）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>な形容词把「な」拿掉，直接接上去：<br><span class='gd-pair'><span class='gd-jp'>失礼な</span> → <span class='gd-jp'>失礼極まりない</span></span><span class='gd-pair'><span class='gd-jp'>危険な</span> → <span class='gd-jp'>危険極まる</span></span><br>最常搭的字：<span class='gd-jp'>失礼、無礼、危険、迷惑、不快、不愉快、退屈、非常識、無責任</span>，几乎都是两个汉字以上、本身就带负面的词。<br><br>「極まりない」的尾巴是「ない」，所以可以像い形容词那样变过去式：<span class='gd-pair'><span class='gd-jp'>失礼極まりない</span> → <span class='gd-jp'>失礼極まりなかった</span></span><br>い形容词不能直接接，要先加「こと」：<span class='gd-pair'><span class='gd-jp'>情けない</span> → <span class='gd-jp'>情けないこと極まりない</span></span>（窝囊到了极点）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・「極まりない」的「ない」<b>不是否定</b>。「極まり」是「尽头」，「極まりない」等于「没有尽头」，也就是「极度～」。<span class='gd-jp'>失礼極まりない</span>是「无礼至极」，不是「不失礼」。<br>・中间不要加な：是<span class='gd-jp'>失礼極まりない</span>，不是「失礼な極まりない」。<br>・几乎都用在坏事上。想称赞东西好吃、好用，请换别的说法，不要硬套它。<br>・口气很重又很硬。跟朋友抱怨用<span class='gd-jp'>本当に失礼だよね</span>就好；当面对人说「失礼極まりない」，等于正式翻脸。<br>・念法：極まりない念きわまりない，極まる念きわまる。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是被店员无礼对待：<br><b>極まりない</b>＝冷静地下一个很重的<b>评语</b>：<span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（那个店员的态度无礼至极）<br><b>といったらない</b>＝整个人<b>情绪满出来</b>的感叹，比较口语，い形容词可以直接接：<span class='gd-jp'>あの店員の態度、腹が立つといったらない。</span>（那个店员的态度真是气死人了）</div><div class='gd-sec'><b>の至り</b>也翻成「～之至」，但方向相反：讲的是<b>自己</b>的感受，多半是光荣、感激这类好事，用在致词、客气场合。<br><span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（能得到这样的奖，光荣之至）</div><div class='gd-warn'>判断小诀窍：批评一件坏事用「極まりない」；客气地说自己很光荣、很感激用「の至り」；气到、羞到、开心到情绪爆表的感叹用「といったらない」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同一个汉字还有两个常见说法：<br>名词＋の極み：<span class='gd-jp'>こんな料理を毎日食べるなんて、贅沢の極みだ。</span>（每天吃这种料理，真是奢侈到了极点）<br>固定说法「感極まる」：<span class='gd-jp'>優勝が決まった瞬間、感極まって泣き出した。</span>（确定夺冠的那一刻，激动到哭了出来）</div>","n1-52":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜まじき」就是中文的<b>「身为～，怎么可以这样！」</b>。用来骂一个人做了<b>跟他身分不相配</b>的事，像新闻说的「有失身分」「失格」。语气很重、很正式，多半出现在新闻、社论、正式发言里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形（字典上查到的原形）＋まじき＋名词<br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまじき行為</span></span>（不该有的行为）<br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許すまじき犯罪</span></span>（不可饶恕的犯罪）<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うまじきこと</span></span>（不该说的话）<br>「する」除了<span class='gd-jp'>するまじき</span>，也会看到古一点的<span class='gd-jp'>すまじき</span>。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>身分＋にあるまじき</span>九成以上都是这个固定组合：「人或身分＋に（或として）＋あるまじき＋名词」，意思是「以这个身分来说，不应该出现的～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にあるまじき行為だ。</span>（那是身为医生不该有的行为）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロにあるまじきミスだ。</span>（这是职业选手不该犯的失误）</div><div class='gd-ex-line'>・<span class='gd-jp'>社会人としてあるまじき態度だと叱られた。</span>（被骂说那是社会人士不该有的态度）</div><div class='gd-sec'><span class='gd-tag'>許すまじき</span>不提身分，直接说「这件事绝不能原谅」。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもを狙った許すまじき犯罪だ。</span>（这是针对小孩、不可饶恕的犯罪）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・まじき<b>后面一定要接名词</b>，不能直接结束句子：<br>　×<span class='gd-jp'>教師にあるまじきだ。</span><br>　○<span class='gd-jp'>教師にあるまじき発言だ。</span><br>・意思是「<b>不应该</b>」，不是「<b>不能、做不到</b>」。它是在做道德批判，跟能力无关。<br>・「許すまじき」的「許す」是<b>旁人</b>原谅不原谅，所以「政治家として許すまじき発言」容易读成「我们身为政治家不能原谅」。要讲「那个政治家不该说这种话」，用<span class='gd-jp'>政治家としてあるまじき発言</span>最清楚。<br>・非常生硬，平常聊天讲出来会很怪。口语说<span class='gd-jp'>先生なのに、ありえない。</span>（明明是老师，太夸张了）就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样骂一位老师体罚学生：<br><b>べきではない</b>＝一般的「不应该」，什么场合都能用，也能放句尾：<span class='gd-jp'>教師は体罰をするべきではない。</span>（老师不应该体罚）<br><b>まじき</b>＝一样是「不应该」，但更重、更书面，而且只能放名词前面：<span class='gd-jp'>体罰は教師にあるまじき行為だ。</span>（体罚是老师不该有的行为）<br><b>べからざる</b>＝重点在「不可以、不能缺」，常讲规则或必要性，不一定扯到身分：<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（水是生活不可或缺的东西）</div><div class='gd-warn'>判断小诀窍：前面有「身分＋に／として」，在骂人失格，就是まじき；讲规则或「不可或缺」，就是べからざる。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>「〜たる」＝身为～这样的人，常跟まじき的意思搭在一起出现：<span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（身为老师，就必须当学生的榜样）</div>","n1-53":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜べからず」就是告示牌上的<b>「禁止～」「不得～」「请勿～」</b>。它是古文说法，感觉很像中文的「闲人勿进」「禁止喧哗」，又硬又正式。平常讲话几乎不会用，在<b>告示、标语、格言</b>里最常看到。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>告示牌</span>写给所有人看的禁止规定，放在句尾。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに入るべからず。</span>（此处禁止进入）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここにごみを捨てるべからず。</span>（此处禁止丢垃圾）</div><div class='gd-sec'><span class='gd-tag'>格言・标语</span>很多老话、名言都是这个形，直接整句记起来。</div><div class='gd-ex-line'>・<span class='gd-jp'>働かざる者食うべからず。</span>（不工作的人就不该吃饭）</div><div class='gd-ex-line'>・<span class='gd-jp'>初心忘るべからず。</span>（不可忘记初衷）</div><div class='gd-sec'><span class='gd-tag'>べからざる＋名词</span>后面要接名词的时候，换成<b>べからざる</b>，意思是「不可～的（东西）」，常出现在文章、新闻。</div><div class='gd-ex-line'>・<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（水是生活中不可或缺的东西）</div><div class='gd-ex-line'>・<span class='gd-jp'>それは許すべからざる行為だ。</span>（那是不可原谅的行为）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词用<b>辞书形</b>（字典上查到的原形），直接加：<br><span class='gd-pair'><span class='gd-jp'>入る</span> → <span class='gd-jp'>入るべからず</span></span><span class='gd-pair'><span class='gd-jp'>捨てる</span> → <span class='gd-jp'>捨てるべからず</span></span><br><b>する</b>通常变成<b>す</b>再接：<span class='gd-pair'><span class='gd-jp'>駐車する</span> → <span class='gd-jp'>駐車すべからず</span></span>（写成するべからず也看得到，但すべからず比较道地）<br>要修饰名词，就把ず换成ざる：<span class='gd-pair'><span class='gd-jp'>欠くべからず</span> → <span class='gd-jp'>欠くべからざるもの</span></span></div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・句尾用<b>べからず</b>，名词前用<b>べからざる</b>，不要写成「べからずもの」。<br>・它是写在牌子上、文章里的，<b>不能拿来当面叫人别做</b>。对朋友说「吸うべからず」会很怪，口语请用<span class='gd-jp'>吸わないで</span>或<span class='gd-jp'>吸っちゃだめ</span>。<br>・前面不能接ない形，「行かないべからず」是错的。它本身就已经是「不可」了。<br>・<span class='gd-jp'>初心忘るべからず</span>的「忘る」是古文里<span class='gd-jp'>忘れる</span>的原形，属于固定说法，照原样背就好，不要自己改。<br>・<span class='gd-jp'>すべからく</span>长得很像，但它是另一个词，意思是「理应、务必」，不是否定。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「抽烟」的情境：<br><b>べからず</b>＝告示上的<b>禁止规定</b>：<span class='gd-jp'>ここでたばこを吸うべからず。</span>（此处禁止吸烟）<br><b>べきではない</b>＝<b>劝人</b>「不应该」，一般讲话、写文章都能用：<span class='gd-jp'>ここでたばこを吸うべきではない。</span>（这里不应该抽烟）<br><b>まじき</b>＝以那个<b>身分</b>来说不该有的：<span class='gd-jp'>患者の前でたばこを吸うなんて、医者にあるまじき行為だ。</span>（在病人面前抽烟，是身为医生不该有的行为）</div><div class='gd-sec'>另外<b>べく</b>只是长得像，意思完全不同，是「为了～」：<span class='gd-jp'>合格すべく、毎日勉強している。</span>（为了考上，每天都在念书）</div><div class='gd-warn'>判断小诀窍：看到告示、格言里的「禁止」用べからず，劝人「不应该」用べきではない，扯到「身为～」用まじき，「为了～」是べく。</div>","n1-55":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜たる」就是中文的<b>「身为～」</b>，跟「身为人师」「为人父母者」那种口气很像。先把一个有份量的身份擡出来，后面再说「这个身份<b>就该</b>怎样」。<br><span class='gd-jp'>たる</span>是很老的说法，意思等于<span class='gd-jp'>である</span>，专门放在名词前面，所以听起来很正式、很有架子，多半出现在文章、演讲、训话里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋たる＋名词。最常见的是后面接<span class='gd-jp'>者</span>（也常写成<span class='gd-jp'>もの</span>，一样是「人」的意思）：<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者たる者</span></span>（身为医生的人）<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親たるもの</span></span>（身为父母的人）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>讲应该怎样</span>最大宗。后面常接<span class='gd-jp'>べきだ</span>、<span class='gd-jp'>なければならない</span>、<span class='gd-jp'>てはならない</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者たる者、患者の話をよく聞くべきだ。</span>（身为医生，就该好好听病人说话）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロたる者、言い訳はしない。</span>（身为职业选手，不找借口）</div><div class='gd-sec'><span class='gd-tag'>批评没做到</span>先擡出身份，再说他竟然做出不像样的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>教師たる者が生徒にうそをつくなんて、許されることではない。</span>（身为老师竟然对学生说谎，这是不可原谅的）</div><div class='gd-sec'><span class='gd-tag'>接其他名词</span>后面不一定是者，也可以接「资格」这类名词。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に代表たる資格はない。</span>（他没有当代表的资格）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面只接<b>名词</b>，而且通常是身份、职位、立场这种「有该尽责任」的词。不能接动词或形容词。<br>・它不是过去式的「た」再加「る」，整个<span class='gd-jp'>たる</span>是一个词，不要拆开想。<br>・很生硬，日常聊天这样讲会像在训话。口语要讲「身为～就该～」，用<span class='gd-jp'>〜なんだから</span>就好：<span class='gd-jp'>先生なんだから、ちゃんとしてよ。</span>（你是老师耶，认真一点啦）<br>・别跟同音的<span class='gd-jp'>足る</span>（够格、值得）混在一起，下面会比较。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲老师：<br><b>たる者</b>＝先擡出身份，再讲应该怎样（或批评竟然没做到）：<span class='gd-jp'>教師たる者、生徒の手本であるべきだ。</span>（身为老师，就该当学生的榜样）<br><b>にあるまじき</b>＝直接评断某个<b>行为、发言</b>「是这个身份不该有的」，后面接<span class='gd-jp'>行為</span>、<span class='gd-jp'>発言</span>这类名词：<span class='gd-jp'>教師にあるまじき発言だ。</span>（这是身为老师不该有的发言）<br><b>ともなれば</b>＝到了那个等级，<b>自然就会</b>～，讲的是理所当然的结果，不是义务：<span class='gd-jp'>ベテラン教師ともなれば、生徒の顔を見ただけで悩みに気づく。</span>（到了资深老师的程度，看学生的脸就知道他有烦恼）<br><b>に足る</b>＝<b>值得</b>～，前面接<span class='gd-jp'>信頼</span>、<span class='gd-jp'>尊敬</span>这类词，而且多了一个<span class='gd-jp'>に</span>：<span class='gd-jp'>彼は信頼に足る教師だ。</span>（他是值得信赖的老师）</div><div class='gd-warn'>判断小诀窍：要说「身为～就该怎样」或「身为～竟然…」，先把身份擡出来时用たる（者）；要直接评断某个行为「是身为～不该有的」，用「～にあるまじき＋行為／発言」；说「到了那个等级自然就～」用ともなれば；说「值得～」用に足る。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样用来评断身份的<span class='gd-jp'>〜まじき</span>（不该有的～），还有讲「到了那种程度」的<span class='gd-jp'>〜ともなれば</span>，可以一起记。</div>","n1-56":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜なくして（は）」就是中文的<b>「没有～，就不可能…」</b>。前面放一个很重要的东西，后面说「少了它，事情根本办不到」，用来强调<b>这东西绝对少不了</b>。语气很正式，多半出现在文章、演讲、得奖感言这种场合。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接加なくして，<b>中间不加「が」或「を」</b>：<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なくして</span></span><span class='gd-pair'><span class='gd-jp'>協力</span> → <span class='gd-jp'>協力なくしては</span></span><br>后面一定接「不可能、办不到」的说法，最常见的是<span class='gd-jp'>あり得ない</span>（不可能有）、<span class='gd-jp'>できない</span>、<span class='gd-jp'>語れない</span>（没办法谈）。<br>前面要放动作时，用「辞书形＋ことなくして」：<span class='gd-pair'><span class='gd-jp'>苦労する</span> → <span class='gd-jp'>苦労することなくして</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>讲道理</span>说明成功、成果背后少不了的条件。</div><div class='gd-ex-line'>・<span class='gd-jp'>日々の努力なくして成功はあり得ない。</span>（没有每天的努力，就不可能成功）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼関係なくして、いいチームは作れない。</span>（没有互相信任，就打造不出好团队）</div><div class='gd-ex-line'>・<span class='gd-jp'>苦労することなくして、本当の喜びは味わえない。</span>（不吃苦，就尝不到真正的喜悦）</div><div class='gd-sec'><span class='gd-tag'>感谢致词</span>回头说「当初要不是有你们就办不到」，后面常用过去式。</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご協力なくしては、このプロジェクトは成功しませんでした。</span>（没有各位的协助，这个计划不可能成功）</div><div class='gd-sec'><span class='gd-tag'>评价</span>说某人或某事物的地位重要到不能不提。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の存在なくして、日本のサッカーの歴史は語れない。</span>（谈日本足球史，不能不提到他）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面一定是「不可能、办不到」。<b>不能</b>说「努力なくして成功した」，那是自相矛盾。<br>・不要加「を」：<span class='gd-jp'>財布をなくして困った</span>是「钱包弄丢了很困扰」，那是动词<span class='gd-jp'>なくす</span>（弄丢），跟这个文法无关。<br>・前面要放<b>真的很重要</b>的东西，像努力、爱、协助、信任。拿雨伞这种小事来说，听起来会很夸张，日常讲<span class='gd-jp'>傘がないと出かけられない</span>就好。<br>・它很硬，朋友聊天不会用。口语说「〜がなかったら、〜できない」就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是在感谢大家帮忙：<br><b>なくしては</b>＝没有～就办不到（最正式）：<span class='gd-jp'>皆様の協力なくしては、成功できませんでした。</span><br><b>なしには</b>＝意思几乎一样，稍微没那么硬：<span class='gd-jp'>皆様の協力なしには、成功できませんでした。</span><br><b>あっての</b>＝反过来讲，「有A才有B」：<span class='gd-jp'>皆様の協力あっての成功でした。</span>（多亏大家协助才有这次成功）</div><div class='gd-sec'>要注意，「なしに」不加は的时候还可以单纯表示「没做～就直接做了」：<span class='gd-jp'>連絡なしに休んだ。</span>（没先说一声就缺勤了）<br>なくして没有这种用法，它只用在「少了它就不可能」。</div><div class='gd-warn'>判断小诀窍：句子后面是「不可能、办不到」，なくして和なしには都可以，なくして比较正式；后面是「就直接做了」，只能用なしに；想从「有」的角度讲，用あっての。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>「〜あっての」（有A才有B）刚好是なくして的反面，两个一起记最好用：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）</div>","n1-57":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「にして」是很硬的<b>书面语</b>，有点像中文的「年过半百才…」「一夕之间」「身兼…」这类文言味道的说法。常见的意思有三种：<b>「到了～才」</b>（也包含「只有～才」）、<b>「一下子就」</b>、<b>「既是～也是」</b>。前两种常带「真不简单／真没想到」的感叹；「既是～也是」只是把两种身分或性质并列，语气正式、端正，不一定有惊讶的意思。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>基本上接名词：<span class='gd-pair'><span class='gd-jp'>50歳</span> → <span class='gd-jp'>50歳にして</span></span><br>「既是～也是」的用法也常接な形容词（像<span class='gd-jp'>簡潔な</span>这种后面带な的形容词），把な拿掉再接：<span class='gd-pair'><span class='gd-jp'>簡潔な</span> → <span class='gd-jp'>簡潔にして</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>到了～才</span>前面放年纪、第几次、第几年这种「阶段」，后面常接<span class='gd-jp'>初めて</span>、<span class='gd-jp'>ようやく</span>，表示「熬到这一步才终于…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>三度目の挑戦にして、ようやく合格した。</span>（挑战到第三次，才终于考上）</div><div class='gd-ex-line'>・<span class='gd-jp'>50歳にして初めて海外に行った。</span>（到了 50 岁才第一次出国）</div><div class='gd-sec'>后面接<span class='gd-jp'>なお</span>，就变成「都到这个阶段了，还…」：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は90歳にしてなお現役の医者だ。</span>（他都 90 岁了，还在第一线看诊）</div><div class='gd-sec'><span class='gd-tag'>只有～才</span>前面放人，表示「要这种人才办得到」，常写成「〜にして初めて」。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは彼にして初めてできる仕事だ。</span>（这是只有他才做得到的工作）</div><div class='gd-ex-line'>・<span class='gd-jp'>この親にしてこの子あり。</span>（有其父必有其子）</div><div class='gd-sec'><span class='gd-tag'>一下子</span>接在<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一夜</span>这种很短的时间后面，表示「转眼间就…」。口语会直接说<span class='gd-jp'>一瞬で</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>町は一瞬にして炎に包まれた。</span>（整个城镇一瞬间就陷入火海）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は一夜にしてスターになった。</span>（她一夜之间成了明星）</div><div class='gd-sec'><span class='gd-tag'>既是～也是</span>「AにしてB」＝同时具备 A 和 B。意思跟「で」一样，<span class='gd-jp'>医者で作家</span>是平常讲法，<span class='gd-jp'>医者にして作家</span>是正式的写法。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者にして作家でもある。</span>（他既是医生，也是作家）</div><div class='gd-ex-line'>・<span class='gd-jp'>説明は簡潔にして明快だった。</span>（说明简洁又清楚）</div><div class='gd-sec'>另外，<span class='gd-jp'>幸いにして</span>（所幸）、<span class='gd-jp'>不幸にして</span>（不幸的是）是固定说法，当一个词背起来就好：<br><span class='gd-jp'>幸いにして、けが人はいなかった。</span>（所幸没有人受伤）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・「到了～才」前面要放<b>人生阶段或次数</b>（年纪、第几次、第几年），不能随便放时刻，像「3時にして」就不对。<br>・这是写文章、演讲、新闻的用语，跟朋友聊天用会很做作，口语用「で」「〜歳で初めて」就好。<br>・接な形容词时要把な拿掉：是<span class='gd-jp'>簡潔にして</span>，不是「簡潔なにして」。<br>・别跟「〜にする」的て形搞混：<span class='gd-jp'>ジュースにして飲む</span>是「做成果汁来喝」，跟这个文法无关，要看前后文判断。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>にして</b>＝到了这个阶段<b>才</b>发生某件事：<br><span class='gd-jp'>50歳にして初めてパソコンを買った。</span>（到了 50 岁才第一次买电脑）<br><b>にしては</b>＝「以～来说，算是很…」，在评论跟一般印象不一样：<br><span class='gd-jp'>50歳にしては体力がある。</span>（以 50 岁来说，体力算很好）</div><div class='gd-warn'>判断小诀窍：后面接「初めて／ようやく／なお」讲一件事终于发生或依然如此，是にして；后面在评价「跟一般比起来怎样」，是にしては。多了一个「は」，意思就差很多。</div>","n1-59":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜には当たらない」就是<b>「用不着～」「犯不着～」</b>。用来冷静地评论：这件事没那么严重，<b>那种反应太过头了</b>，例如用不着惊讶、用不着难过、用不着骂人。很像中文说「这有什么好大惊小怪的」，只是语气比较正式，比较常出现在文章、评论或正式发言里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形（字典上查到的原形）＋には当たらない<br><span class='gd-pair'><span class='gd-jp'>驚く</span> → <span class='gd-jp'>驚くには当たらない</span></span>（用不着惊讶）<br><span class='gd-pair'><span class='gd-jp'>悲観する</span> → <span class='gd-jp'>悲観するには当たらない</span></span>（用不着悲观）<br>讲话客气一点就说<span class='gd-jp'>〜には当たりません</span>。「は」有时候会省略，写成<span class='gd-jp'>驚くに当たらない</span>，意思一样。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>评论反应太过头</span>前面通常会先交代理由：「因为本来就是这样」或「才这点程度」，后面再下结论：「所以用不着～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はずっと努力してきたのだから、合格したのも驚くには当たらない。</span>（他一直很努力，考上了也用不着惊讶）</div><div class='gd-ex-line'>・<span class='gd-jp'>一度失敗したくらいで、悲観するには当たらない。</span>（才失败一次，用不着悲观）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが言ったことだから、そんなに責めるには当たらない。</span>（小孩子讲的话，用不着那样责怪）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>前面常放「反应」类的动词：<span class='gd-jp'>驚く</span>、<span class='gd-jp'>嘆く</span>、<span class='gd-jp'>悲観する</span>、<span class='gd-jp'>責める</span>、<span class='gd-jp'>非難する</span>、<span class='gd-jp'>褒める</span>、<span class='gd-jp'>感心する</span>。<br>理由的部分常搭配<span class='gd-jp'>〜くらいで</span>（才这点程度就～）、<span class='gd-jp'>〜からといって</span>（就算因为～）、<span class='gd-jp'>〜のだから</span>（既然～）。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的<span class='gd-jp'>当たる</span>跟「中奖」「打中」无关，整句要当成一个固定说法来记。<br>・前面接的是<b>对某件事的反应或评价</b>。像「用不着特地跑一趟」这种「不必麻烦去做某个动作」，日文通常用<span class='gd-jp'>〜には及ばない</span>，不用这个（下面会比较）。<br>・名词接<span class='gd-jp'>に当たらない</span>常常是另一个意思：「不算是～、不构成～」。例如<span class='gd-jp'>これは違反には当たらない。</span>（这不算违规）。初学时先记<b>动词辞书形＋には当たらない＝用不着～</b>就好。<br>・翻成「不值得～」容易让人误会成「这东西没价值」。它真正的意思是「那种反应不必要、不合理」，翻成「用不着～」比较准确。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>には及ばない</b>＝不用麻烦去做（常带体贴，对对方说）<br>情境：部下犯了一个小错。<br>主管对部下说：<span class='gd-jp'>わざわざ謝りに来るには及ばないよ。</span>（不用特地跑来道歉啦）<br>同事评论这件事：<span class='gd-jp'>一度のミスで、そこまで彼を責めるには当たらない。</span>（才一次失误，用不着把他骂成那样）</div><div class='gd-sec'><b>に足りない</b>＝对象本身份量不够，不足以～<br>情境：明天要比赛。<br><span class='gd-jp'>あんな相手は恐れるに足りない。</span>（那种对手不足为惧：重点是对手太弱）<br><span class='gd-jp'>初めての試合だからといって、恐れるには当たらない。</span>（虽然是第一次比赛，也用不着害怕：重点是这种害怕没必要）</div><div class='gd-warn'>判断小诀窍：说「那种反应没必要」用には当たらない；说「不必麻烦去做」用には及ばない；说「对象本身没什么份量」用に足りない。</div>","n1-62":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜がてら」就是中文的<b>「顺便～」「兼～」</b>。出一趟门，一次搞定两件事：散步兼买面包、送朋友去车站兼聊天。重点是<b>一个行动同时有两个目的</b>，有一石二鸟的感觉。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><span class='gd-tag'>名词＋がてら</span>最常见。前面放的是「动作」的名词，像<span class='gd-jp'>散歩</span>、<span class='gd-jp'>買い物</span>、<span class='gd-jp'>見物</span>（观光）、<span class='gd-jp'>運動</span>、<span class='gd-jp'>ドライブ</span>。<br><span class='gd-pair'><span class='gd-jp'>散歩</span> → <span class='gd-jp'>散歩がてら</span></span>（散步顺便）</div><div class='gd-ex-line'>・<span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（散步顺便买了面包回来）</div><div class='gd-ex-line'>・<span class='gd-jp'>花見がてら、久しぶりに実家に帰った。</span>（回了一趟好久没回的老家，顺便赏花）</div><div class='gd-sec'><span class='gd-tag'>ます形＋がてら</span>动词把「ます」拿掉，直接加がてら。<br><span class='gd-pair'><span class='gd-jp'>送ります</span> → ます拿掉 → <span class='gd-jp'>送りがてら</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで送りがてら、ちょっと話そうか。</span>（我送你到车站，顺便聊一下吧）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'>后面那句通常是<b>要移动、要出门</b>的动作，像<span class='gd-jp'>行く</span>、<span class='gd-jp'>来る</span>、<span class='gd-jp'>寄る</span>（绕过去）、<span class='gd-jp'>歩く</span>、<span class='gd-jp'>出かける</span>。因为「顺便」本来就是「反正都要出门了，就一起做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>運動がてら、一駅歩いて帰った。</span>（当作运动，多走一站回家）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放<b>动作</b>。<span class='gd-jp'>散歩がてら</span>可以，「雨がてら」「休みがてら」这种不是动作的词不能用。<br>・前后两件事要是<b>同一个人</b>做的。<br>・它不算书面语，日常聊天也很常听到，比<span class='gd-jp'>ついでに</span>稍微成熟一点而已。<br>・讲的是<b>这一次</b>顺便做，不是长期同时做两件事。长期的要用<span class='gd-jp'>かたわら</span>。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「去买东西，顺便去邮局」：<br><b>ついでに</b>＝最口语、最好用，主要是去买东西，邮局是附带的：<span class='gd-jp'>買い物のついでに、郵便局に寄った。</span><br><b>がてら</b>＝一趟出门兼两个目的：<span class='gd-jp'>買い物がてら、郵便局に寄った。</span></div><div class='gd-sec'><b>かたがた</b>＝很正式，多用在拜访、问候，常见于商务场合或书信：<span class='gd-jp'>お礼かたがた、ご挨拶に伺いました。</span>（来向您道谢，顺便打声招呼）<br><b>かたわら</b>＝长期一边做本业、一边做别的：<span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span>（一边上班，一边写小说）<br><b>ながら</b>＝同一时间手上做两个动作：<span class='gd-jp'>歩きながら電話する。</span>（边走边讲电话）</div><div class='gd-warn'>判断小诀窍：平常讲「顺便」用ついでに或がてら；跟客户、长辈拜访问候用かたがた；长期两边都在做用かたわら；身体同时做两个动作用ながら。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着看<span class='gd-jp'>〜かたがた</span>和<span class='gd-jp'>〜かたわら</span>，三个一起记，考试的选择题就很好分。</div>","n1-64":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ずくめ」就像中文的<b>「一身黑」「满满都是～」「清一色～」</b>。从头到尾、整体看过去全是同一类东西，比如全身都穿黑的、一整年好事接连不断、规定多到处处被管。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接加ずくめ，就这么简单。<br><span class='gd-pair'><span class='gd-jp'>黒</span> → <span class='gd-jp'>黒ずくめ</span></span><span class='gd-pair'><span class='gd-jp'>いいこと</span> → <span class='gd-jp'>いいことずくめ</span></span><span class='gd-pair'><span class='gd-jp'>規則</span> → <span class='gd-jp'>規則ずくめ</span></span><br>接好之后，用法跟一般名词一样：<br>后面接名词要加「の」：<span class='gd-jp'>黒ずくめの男</span>（全身黑衣的男人）<br>放句尾加「だ」：<span class='gd-jp'>いいことずくめだ</span><br>句子还没说完用「で」：<span class='gd-jp'>規則ずくめで、疲れる</span></div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>ずくめ<b>不是什么名词都能接</b>，日本人常用的就那几个固定搭配，先把下面这些记熟最实在。</div><div class='gd-sec'><span class='gd-tag'>颜色、穿着</span>全身都是同一个颜色。</div><div class='gd-ex-line'>・<span class='gd-jp'>黒ずくめの男が店に入ってきた。</span>（一个全身黑衣的男人走进店里）</div><div class='gd-sec'><span class='gd-tag'>好事</span>好事一件接一件。</div><div class='gd-ex-line'>・<span class='gd-jp'>今年は結婚に昇進に、いいことずくめだった。</span>（今年又结婚又升官，全是好事）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行中はごちそうずくめで、3キロも太った。</span>（旅行期间餐餐大餐，胖了足足 3 公斤）</div><div class='gd-sec'><span class='gd-tag'>规定、限制</span>到处都被管，通常带着「被绑得很紧」的不满。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの会社は規則ずくめで、息が詰まる。</span>（我们公司规定一大堆，闷到喘不过气）</div><div class='gd-sec'><span class='gd-tag'>新闻常见</span>形容一件事有很多跟平常不一样的地方。</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の大会は異例ずくめだった。</span>（这次大会处处都是破例）</div><div class='gd-sec'>从上面可以看出来：ずくめ<b>本身不分好坏</b>，重点只在「整体清一色」。<span class='gd-jp'>黒ずくめ</span>是中性，<span class='gd-jp'>いいことずくめ</span>是正面，<span class='gd-jp'>規則ずくめ</span>就偏负面。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・只能接<b>名词</b>。想说「全是好吃的」，要讲<span class='gd-jp'>美味しいものずくめ</span>或<span class='gd-jp'>ごちそうずくめ</span>，不能把形容词直接接上去说成美味しいずくめ。<br>・<b>沾在身上的脏东西</b>不用ずくめ：「满身泥巴」是<span class='gd-jp'>泥まみれ</span>，不能说泥ずくめ；「满身大汗」是<span class='gd-jp'>汗まみれ</span>。<br>・<span class='gd-jp'>結構ずくめ</span>（条件好到挑不出毛病）常带一点怀疑的口气：<span class='gd-jp'>結構ずくめの話には気をつけたほうがいい。</span>（条件全是好处的事最好小心一点）<br>・偶尔会看到写成「づくめ」，是同一个东西，现在一般写ずくめ。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲一件衣服，看看三种说法差在哪：<br><b>ずくめ</b>＝整体清一色：<span class='gd-jp'>黒ずくめの服</span>（全身上下一身黑）<br><b>まみれ</b>＝表面沾满液体或粉状的东西，几乎都是负面：<span class='gd-jp'>泥まみれの服</span>（衣服沾满泥巴）<br><b>だらけ</b>＝某样东西多到到处都是，大多是不好的东西：<span class='gd-jp'>しわだらけの服</span>（衣服到处都是皱折）</div><div class='gd-warn'>判断小诀窍：整体清一色（穿着、好事、规定等固定搭配）用ずくめ；黏在表面、沾得一身都是用まみれ；数量多到满地都是用だらけ。</div>","n1-63":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜まみれ」就是中文的<b>「一身泥」「满身是汗」「沾满了血」</b>。重点是泥、汗、血、灰尘这类东西<b>黏在表面、整片都沾到了</b>，而且通常是脏的、让人不舒服的东西。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>身上、东西上沾满脏东西</span>最基本的用法。常跟它一起出现的字：<span class='gd-jp'>泥</span>、<span class='gd-jp'>汗</span>、<span class='gd-jp'>血</span>、<span class='gd-jp'>ほこり</span>（灰尘）、<span class='gd-jp'>油</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>泥まみれになって、子供と遊んだ。</span>（和孩子玩得一身泥）</div><div class='gd-ex-line'>・<span class='gd-jp'>汗まみれで家に帰ってきた。</span>（满身大汗地回到家）</div><div class='gd-ex-line'>・<span class='gd-jp'>倉庫からほこりまみれのアルバムが出てきた。</span>（从仓库翻出一本积满灰尘的相簿）</div><div class='gd-sec'><span class='gd-tag'>比喻：被坏事缠住</span>也可以拿来说抽象的东西，像被债务、谎言整个包住、甩不掉。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は借金まみれだ。</span>（他负债累累）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人の話は嘘まみれだ。</span>（那个人讲的话全是谎言）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>很简单，<b>名词直接加まみれ</b>：<span class='gd-pair'><span class='gd-jp'>泥</span> → <span class='gd-jp'>泥まみれ</span></span><br>接好之后就把它当成一个名词来用，最常见的样子有这几种：<br>・<span class='gd-jp'>〜まみれになる</span>：变得一身都是～<br>・<span class='gd-jp'>〜まみれだ</span>：（现在）满身都是～<br>・<span class='gd-jp'>〜まみれで</span>：在满身～的状态下（去做某事）<br>・<span class='gd-jp'>〜まみれの＋名詞</span>：沾满～的（东西）　例：<span class='gd-jp'>血まみれのシャツ</span>（沾满血的衬衫）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・まみれ是「<b>沾上去、黏在表面</b>」的感觉，所以只是「数量很多」的东西不要用。人很多要说<span class='gd-jp'>人でいっぱい</span>或<span class='gd-jp'>人だらけ</span>，不说人まみれ。<br>・伤口、错字这种不是「沾上去」的东西，一般用<span class='gd-jp'>だらけ</span>：<span class='gd-jp'>傷だらけ</span>、<span class='gd-jp'>間違いだらけ</span>。<br>・它是负面的。好事、漂亮的东西一般不用まみれ，「全身都是花」「满满的幸福」这种正面的意思要换别的说法。<br>・后面接名词要加「の」：是<span class='gd-jp'>血まみれのシャツ</span>，不是血まみれシャツ。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>だらけ</b>＝<b>很多、到处都是</b>（重点在数量多、散得到处都是）：<span class='gd-jp'>この作文は間違いだらけだ。</span>（这篇作文错误百出）<br><b>まみれ</b>＝<b>沾满、整片黏在表面</b>（重点在被液体、粉状的东西盖住）：<span class='gd-jp'>顔が汗まみれだ。</span>（脸上全是汗）<br>泥、汗、血这类两个都能说：<span class='gd-jp'>泥だらけ</span>、<span class='gd-jp'>泥まみれ</span>都可以，只是まみれ「黏得满满的」画面感更强。</div><div class='gd-sec'><b>ずくめ</b>＝<b>从头到尾清一色</b>（不一定负面，也可以是好事）：<span class='gd-jp'>黒ずくめの服</span>（一身全黑的打扮）、<span class='gd-jp'>いいことずくめ</span>（全是好事）<br><b>まみれ</b>则是被脏东西沾满：<span class='gd-jp'>泥まみれの服</span>（沾满泥巴的衣服）</div><div class='gd-warn'>判断小诀窍：黏在身上、沾满了→まみれ；数量多、到处都是→だらけ；清一色、全都是→ずくめ。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同一组常被拿来比较的<span class='gd-jp'>〜ずくめ</span>（清一色、全是～），可以接着看，两个一起记最不容易混。</div>","n1-69":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜を皮切りに」就是中文的<b>「以～为首站」「从～打头阵」</b>。像演唱会说「从台北场开始，接着跑全台巡回」，台北场就是那个「皮切り」，也就是第一棒。重点是<b>后面还有一连串的事接着来</b>。</div><div class='gd-sec'>「皮切り」本来是指第一下艾灸，最烫、最痛的那一下，后来引申成「一连串事情的第一个」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>活动、巡回</span>第一站开始，后面一站一站接下去。</div><div class='gd-ex-line'>・<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まった。</span>（以东京场为首站，全国巡回开跑了）</div><div class='gd-sec'><span class='gd-tag'>事业扩大</span>从第一间店、第一个商品开始，越做越多。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は渋谷店を皮切りに、各地に店舗を増やしている。</span>（这家店从涩谷店起家，在各地陆续增加店面）</div><div class='gd-sec'><span class='gd-tag'>一个带头，其他跟上</span>某人先开口，大家就接连跟进。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言を皮切りに、次々と意見が出た。</span>（他一开口，大家的意见就接连冒出来）</div><div class='gd-sec'>后半句常会搭<span class='gd-jp'>次々と</span>（接二连三）、<span class='gd-jp'>相次いで</span>（相继）、<span class='gd-jp'>各地で</span>（在各地）这类词，用来表示「接下来还有很多」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接接：<span class='gd-pair'><span class='gd-jp'>東京公演</span> → <span class='gd-jp'>東京公演を皮切りに</span></span><br>如果是一个动作，通常用「名词的说法」：<span class='gd-jp'>発売</span>（开卖）、<span class='gd-jp'>開店</span>（开幕）、<span class='gd-jp'>発言</span>（发言）。<br>后面加「して」意思一样，两种都可以用；不加「して」的「を皮切りに」比较简洁，书面上更常见：<span class='gd-jp'>東京公演を皮切りにして</span>。<br>另外也会看到<span class='gd-jp'>を皮切りとして</span>，意思相同。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>后面一定要有「一连串」</b>。只发生一件事就不能用：<span class='gd-jp'>入学を皮切りに、一人暮らしを始めた</span>是错的，因为后面只有一件事，要改成<span class='gd-jp'>入学をきっかけに</span>。<br>・它不是单纯的「从～开始」。讲时间起点用「から」就好：<span class='gd-jp'>月曜日から仕事が始まる</span>，不要说成月曜日を皮切りに。<br>・<b>坏事的连锁比较少用</b>。地震、事故这类事情接连发生，日本人一般不会用皮切り，大多用在活动、事业、比赛这种「一路展开」的事。<br>・语感偏正式，新闻、报导、介绍文很常见；跟朋友聊天比较少讲。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样都是一场演唱会，用不同文法，意思就差很多：<br><b>を皮切りに</b>＝这场是<b>第一站</b>，后面还有很多场：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブを皮切りに、彼らは全国を回った。</span>（以那场演唱会为首站，他们跑遍了全国）</div><div class='gd-sec'><b>をきっかけに</b>＝因为这件事，<b>带来某个改变</b>（不一定有一连串）：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブをきっかけに、彼らは有名になった。</span>（因为那场演唱会，他们出名了）</div><div class='gd-sec'><b>を限りに</b>＝刚好相反，是<b>最后一次</b>，到此为止：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日のライブを限りに、活動を休止する。</span>（今天的演唱会是最后一场，之后暂停活动）</div><div class='gd-warn'>判断小诀窍：「第一站，后面一串接着来」用を皮切りに；「因为那件事而改变」用をきっかけに；「最后一次，到此结束」用を限りに。</div>","n1-75":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜きらいがある」就是中文的<b>「有～的毛病」「有～的倾向」</b>，而且一定是<b>不好的</b>倾向。口气很像老师在联络簿写「该生做事有急躁之倾向」：明明在讲缺点，但说得很客气、很含蓄。多半出现在文章、评论，或比较正式的谈话里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形＋きらいがある　<span class='gd-pair'><span class='gd-jp'>抱え込む</span> → <span class='gd-jp'>抱え込むきらいがある</span></span><br>动词ない形＋きらいがある　<span class='gd-pair'><span class='gd-jp'>聞かない</span> → <span class='gd-jp'>聞かないきらいがある</span></span><br>名词＋の＋きらいがある　<span class='gd-pair'><span class='gd-jp'>独断</span> → <span class='gd-jp'>独断のきらいがある</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何でも一人で抱え込むきらいがある。</span>（他有什么事都自己一个人扛的毛病）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は人の話を最後まで聞かないきらいがある。</span>（她有不把别人的话听完的毛病）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のやり方は独断のきらいがある。</span>（他的做法有点独断）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>〜すぎるきらいがある</span>批评「做过头」时特别常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長は細かいことを気にしすぎるきらいがある。</span>（我们部长有太在意小细节的毛病）</div><div class='gd-sec'><span class='gd-tag'>讲一群人</span>评论某个族群、组织、社会的整体作风。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近のニュースは話題性を重視しすぎるきらいがある。</span>（最近的新闻有太过重视话题性的倾向）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・汉字写成「嫌い」，但这里<b>跟「讨厌」没关系</b>，意思是「倾向、毛病」。现在多半直接写平假名<span class='gd-jp'>きらい</span>。<br>・只能讲<b>不好的</b>倾向。说人「很体贴」不能用它，要说<span class='gd-jp'>優しいところがある</span>。<br>・讲的是一个人（或团体）<b>平常的作风、个性</b>，不是某一次发生的事。「他昨天迟到了」不能用きらいがある。<br>・接名词一定要加「の」：是<span class='gd-jp'>独断のきらいがある</span>，不是「独断きらいがある」。<br>・语感偏硬。跟朋友聊天讲「他很容易想太多」，用<span class='gd-jp'>考えすぎるところがある</span>或<span class='gd-jp'>考えすぎがちだ</span>比较自然。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样在讲一个人容易往坏处想：<br><b>がち</b>＝「常常～、容易～」，重点在<b>次数多</b>，日常会话就能用：<span class='gd-jp'>彼は物事を悲観的に考えがちだ。</span>（他常常把事情往悲观想）<br><b>きらいがある</b>＝「有～的毛病」，带有<b>委婉评论</b>对方性格的味道，偏文章：<span class='gd-jp'>彼は物事を悲観的に考えるきらいがある。</span>（他有把事情往悲观想的倾向）<br><b>気味</b>＝「有点～的感觉」，讲<b>眼前的轻微状态</b>，不是性格：<span class='gd-jp'>最近、ちょっと疲れ気味だ。</span>（最近有点累累的）<br>另外，がち也能讲天气、自然现象（<span class='gd-jp'>冬は空気が乾燥しがちだ</span>，冬天空气容易干燥），きらいがある基本上只拿来评论人或团体的作风。</div><div class='gd-warn'>判断小诀窍：聊天说「常常～」用がち；说「有点～的感觉」用気味；写评论、客气地点出一个人或团体的「坏习惯」，用きらいがある。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>常跟「ともすると・ともすれば」（一不小心就～）一起出现：<span class='gd-jp'>人はともすると、楽な方を選ぶきらいがある。</span>（人一不小心就容易选轻松的那条路）</div>","n1-80":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜にとどまらず」就是中文新闻常讲的<b>「不仅限于～，还扩及到～」</b>。<span class='gd-jp'>とどまる</span>是「停在原地」，<span class='gd-jp'>とどまらず</span>就是「没有停在那里」。前面先讲一个比较小的范围，后面接更大的范围，像水波一圈一圈往外扩散。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>范围扩大</span>最常用在影响、灾情、人气、活动这类会「扩散」的东西。新闻、报告、演讲很常见，属于书面又正式的说法。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の人気は日本にとどまらず、アジア全体に広がっている。</span>（她的人气不只在日本，还扩及整个亚洲）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は一つの会社にとどまらず、業界全体に関わる。</span>（这个问题不只牵涉一家公司，还关系到整个业界）</div><div class='gd-sec'><span class='gd-tag'>做的事更进一步</span>前面也可以放一个动作，意思是「不只做到～，还更进一步～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ボランティアたちは物資を届けるにとどまらず、被災者の話にも耳を傾けた。</span>（志工们不只送物资，还倾听受灾者的心声）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>国内</span> → <span class='gd-jp'>国内にとどまらず</span></span><br>动词辞书形（字典里查得到的原形）＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>届ける</span> → <span class='gd-jp'>届けるにとどまらず</span></span><br>也常看到加了「だけ」的<span class='gd-jp'>国内だけにとどまらず</span>，意思一样，语气更强调一点。</div><div class='gd-sec'>放在句尾或修饰名词时，改成<b>にとどまらない</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は音楽にとどまらない。</span>（他的才华不仅限于音乐）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・是<span class='gd-jp'>とどまる</span>，不是<span class='gd-jp'>とまる</span>。<span class='gd-jp'>涙が止まらない</span>是「眼泪停不下来」，跟这个文法完全无关，别把「とど」漏掉。<br>・后面一定要接<b>更大的范围</b>，常搭配「も」「まで」「へと」：<span class='gd-jp'>海外にも</span>、<span class='gd-jp'>全国へと</span>。只写前半句，话会讲不完。<br>・它很正式，日常小事不要用。「我不只吃拉面，还吃了寿司」讲<span class='gd-jp'>ラーメンだけじゃなくて、寿司も食べた</span>就好，用にとどまらず会像在念新闻稿。<br>・没有否定的<span class='gd-jp'>にとどまる</span>本身也很常见，意思反过来，是「只停留在～」：<span class='gd-jp'>今回の値上げは一部の商品にとどまる。</span>（这次涨价只限于部分商品）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲一部动画很红：<br><b>だけでなく</b>＝最普通的「不只～也～」，什么场合都能用：<span class='gd-jp'>このアニメは子どもだけでなく、大人にも人気だ。</span>（这部动画不只小孩，大人也喜欢）<br><b>に限らず</b>＝不限于某一类，<b>换成别的也一样</b>：<span class='gd-jp'>このアニメは子どもに限らず、大人にも人気だ。</span>（不限小孩，大人也喜欢＝谁都喜欢）<br><b>にとどまらず</b>＝范围<b>往外扩散</b>出去：<span class='gd-jp'>このアニメの人気は日本にとどまらず、世界中に広がっている。</span>（人气不只在日本，还扩散到全世界）<br><b>はおろか</b>＝前面的不用说，<b>连最夸张的</b>都～：<span class='gd-jp'>このアニメは、子どもはおろか、お年寄りまで知っている。</span>（小孩就不用说了，连老人家都知道）</div><div class='gd-warn'>判断小诀窍：影响、范围「越扩越大」用にとどまらず；「不限哪一类」用に限らず；「连最极端的都」用はおろか；拿不准就用だけでなく，最安全。</div>","n1-81":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜すら」就是中文的<b>「连～都…」</b>。先举一个最基本、最不可能出问题的例子，用它来凸显情况有多夸张：<span class='gd-jp'>名前すら知らない</span>，连名字都不知道，那其他的就更不用说了。意思跟「さえ」差不多，但<b>口气比较硬、比较书面</b>，常出现在文章、新闻、评论里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><span class='gd-tag'>名词＋すら</span>最基本的接法。原本的「が」「を」直接被すら取代。<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間すらない</span></span>（连时间都没有）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、食事する時間すらない。</span>（忙到连吃饭的时间都没有）</div><div class='gd-sec'><span class='gd-tag'>名词＋ですら</span>前面是「人」、而且这个人是做动作的一方时很常用。这里的「で」不是「在」的意思，把「ですら」整组记起来就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>専門家ですら答えられない問題だ。</span>（这是连专家都答不出来的问题）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもですら知っていることだ。</span>（这是连小孩都知道的事）</div><div class='gd-sec'><span class='gd-tag'>名词＋に・と等＋すら</span>「に」「と」这类助词要留着，すら加在后面。</div><div class='gd-ex-line'>・<span class='gd-jp'>このことは親にすら話していない。</span>（这件事我连父母都没说）</div><div class='gd-sec'><span class='gd-tag'>て形＋すらいない</span>强调的是<b>动作本身</b>：连「做」这一步都还没做。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はメールを読んですらいない。</span>（那封信他连读都没读）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・すら<b>不是只能配否定</b>。大多数时候后面接「ない」，但像<span class='gd-jp'>子どもですら知っている</span>这种肯定句也很自然。<br>・「に」「と」不能省：要说<span class='gd-jp'>親にすら</span>，不能说親すら話していない。<br>・<span class='gd-jp'>メールすら読んでいない</span>是「连信都没读」（重点在信），<span class='gd-jp'>メールを読んですらいない</span>是「连读都没读」（重点在读这个动作），すら放的位置不同，强调的东西就不同。<br>・すら口气偏硬，平常跟朋友聊天讲<span class='gd-jp'>名前も知らない</span>或<span class='gd-jp'>名前さえ知らない</span>比较自然。<br>・すら常带着「惊讶、傻眼、批评」的感觉，拿来称赞人的时候不多。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>すら</b>和<b>さえ</b>在「连～都」的意思上几乎可以互换：<br><span class='gd-jp'>名前すら知らない。</span>／<span class='gd-jp'>名前さえ知らない。</span>（连名字都不知道）<br>差别在于すら比较书面，而且さえ还有一个すら<b>没有</b>的用法：「〜さえ〜ば」＝只要～就好。<br><span class='gd-jp'>時間さえあれば行ける。</span>（只要有时间就能去）<br>这句<b>不能</b>换成すら。</div><div class='gd-warn'>判断小诀窍：「连～都」两个都行，写文章时用すら更有力道；「只要～就」只能用さえ。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>すら很常跟「<span class='gd-jp'>〜はおろか</span>」（别说～了）搭在一起，前面讲难的、后面讲简单的：<br><span class='gd-jp'>漢字はおろか、ひらがなすら書けない。</span>（别说汉字了，连平假名都不会写）</div>","n1-1":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜に至っては」就是中文的<b>「至于～，更是…」「～更夸张，竟然…」</b>。先讲大家或整体都怎么样，再从里面挑出<b>最夸张的那一个</b>拿出来说。<br>就像你抱怨：「我们家每个人都很会赖床，<b>至于我爸，更夸张</b>，睡到中午都不起来。」</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋に至っては。<br><span class='gd-pair'><span class='gd-jp'>父</span> → <span class='gd-jp'>父に至っては</span></span><span class='gd-pair'><span class='gd-jp'>数学</span> → <span class='gd-jp'>数学に至っては</span></span><br>整句的样子通常是：<b>先讲整体情况 → 〇〇に至っては → 最极端的事</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの家族はみんな朝が弱い。父に至っては、昼まで起きてこない。</span>（我们家每个人早上都爬不起来，我爸更夸张，睡到中午都不起床。）</div><div class='gd-ex-line'>・<span class='gd-jp'>成績が悪く、数学に至っては赤点だ。</span>（成绩很差，数学甚至不及格。）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議では誰も意見を言わなかった。部長に至っては、最初から最後まで寝ていた。</span>（会议上没人发表意见，部长更夸张，从头睡到尾。）</div><div class='gd-sec'>后半句常会搭「<span class='gd-jp'>さえ</span>」「<span class='gd-jp'>まで</span>」「<span class='gd-jp'>一度も〜ない</span>」这种加强语气的说法，让「夸张感」更明显。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面一定要先有一个<b>整体</b>（一群人、几个科目、整件事），才能「挑出最夸张的」。突然冒一句「父に至っては…」，前面什么都没讲，日本人会听不懂你在比什么。<br>・几乎都用在<b>不好的、让人傻眼的事</b>。拿来夸人「他更厉害，考了满分」听起来会很怪。<br>・后面讲的要真的是<b>最极端</b>的程度，只是普通程度的话，用这个句型会显得小题大作。<br>・这是偏书面、正式的说法。跟朋友聊天比较常说「<span class='gd-jp'>父なんか、昼まで寝てるよ</span>」。<br>・念法是<b>いたっては</b>，「至」念いた。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>に至っては</b>＝在整体里<b>挑出最夸张的一个</b>（多为负面）：<br>・<span class='gd-jp'>部屋はどこも汚かった。台所に至っては、足の踏み場もなかった。</span>（每个房间都很脏，厨房更夸张，连站的地方都没有。）<br><b>に至るまで</b>＝从A到B<b>全部都包含</b>，强调范围很广，好坏都能用：<br>・<span class='gd-jp'>リビングから台所に至るまで、全部きれいに掃除した。</span>（从客厅到厨房，全部都打扫干净了。）</div><div class='gd-sec'><b>ときたら</b>＝单纯把某个人拿出来<b>抱怨</b>，前面不需要先讲一群人，口气比较口语、带不满：<br>・<span class='gd-jp'>うちの父ときたら、毎晩飲んで帰ってくる。</span>（说到我爸，每天晚上都喝完酒才回家。）<br>・<span class='gd-jp'>家族はみんなお酒好きだが、父に至っては毎晩飲んで帰ってくる。</span>（家里每个人都爱喝酒，我爸更夸张，每天晚上都喝完才回家。）</div><div class='gd-warn'>判断小诀窍：先讲「大家都～」再说「其中某某更夸张」→ に至っては；「从A到B全部」→ に至るまで；单纯「说到某某真是受不了」→ ときたら。</div>","n1-4":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜たりとも…ない」就是中文的<b>「连一～都不…」</b>，而且是加重语气的版本。像有人拍桌说「一毛钱都不给！」「一分钟都不准浪费！」，那种<b>斩钉截铁、绝不让步</b>的口气，日文就用たりとも。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>公式很固定：<b>「一」＋量词＋たりとも＋否定</b>。<br><span class='gd-pair'><span class='gd-jp'>一日</span> → <span class='gd-jp'>一日たりとも</span></span>（连一天）<br><span class='gd-pair'><span class='gd-jp'>一円</span> → <span class='gd-jp'>一円たりとも</span></span>（连一块钱）<br><span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>一人たりとも</span></span>（连一个人）<br>后面<b>一定要接否定</b>：<span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜ません</span>、<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>許されない</span>、<span class='gd-jp'>〜するな</span>这类。<br>最常见的组合：<span class='gd-jp'>一秒</span>、<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一日</span>、<span class='gd-jp'>一円</span>、<span class='gd-jp'>一人</span>、<span class='gd-jp'>一歩</span>、<span class='gd-jp'>一滴</span>、<span class='gd-jp'>一度</span>，都是「最小单位」，强调连这么一点点都不行。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>强烈的决心</span>自己绝对不要、不想做某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>残り時間、一秒たりとも無駄にしたくない。</span>（剩下的时间，我连一秒都不想浪费）</div><div class='gd-sec'><span class='gd-tag'>规定、命令</span>不准、不容许，主管、教练、告示很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合が終わるまで、一瞬たりとも気を抜くな。</span>（比赛结束前，一刻都不准松懈）</div><div class='gd-ex-line'>・<span class='gd-jp'>医療ミスは一件たりとも許されない。</span>（医疗疏失，一件都不容许发生）</div><div class='gd-sec'><span class='gd-tag'>强烈的感情</span>常跟「〜たことはない」一起，表达「从来没有过」。</div><div class='gd-ex-line'>・<span class='gd-jp'>君のことを一日たりとも忘れたことはない。</span>（我没有一天忘记过你）</div><div class='gd-h'>一个特别的固定说法</div><div class='gd-sec'><span class='gd-jp'>何人たりとも</span>＝「不管是谁都不准～」。这里的何人要念<b>なんぴと</b>，是很硬的书面语，常出现在告示、小说、动漫台词里。</div><div class='gd-ex-line'>・<span class='gd-jp'>何人たりとも、ここに立ち入ることは許さない。</span>（不管是谁，都不准踏进这里）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面只能是<b>「一」</b>：<span class='gd-jp'>二日たりとも</span>、<span class='gd-jp'>三人たりとも</span>都不对。要强调的就是「最小量」。<br>・后面<b>一定是否定</b>，不能说「一日たりとも休む」这种肯定句。<br>・量词后面直接接たりとも，不要多加「も」或「の」：说成「一日もたりとも」是错的。<br>・语气很重、偏书面。日常聊天说<span class='gd-jp'>一円も払わない</span>就够了，换成たりとも会像在发誓或宣言。<br>・单纯描述事实（例如「教室里一个学生都没有」）用<span class='gd-jp'>一人もいなかった</span>比较自然；たりとも适合讲决心、规定、强烈情绪。<br>・何人たりとも的何人念なんぴと，不是なんにん。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「钱」，看三种说法：<br><b>一〜も…ない</b>＝单纯说「连一个都没有」，中性，生活用：<span class='gd-jp'>財布には一円もない。</span>（钱包里一块钱都没有）<br><b>一〜たりとも…ない</b>＝带着强烈主张、绝不让步：<span class='gd-jp'>税金は一円たりとも無駄にできない。</span>（税金连一块钱都不能浪费）<br><b>すら</b>＝举一个「最基本的东西」来强调，前面不必是「一＋量词」：<span class='gd-jp'>今月は電車代すらない。</span>（这个月连搭电车的钱都没有）</div><div class='gd-warn'>判断小诀窍：只是陈述「一个都没有」用も；「一＋量词」再加上决心、禁止、绝不允许的口气，用たりとも；举出「连这么基本的东西都～」用すら。</div>","n1-5":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜であれ」就是中文的<b>「不管是～都…」「就算是～也…」</b>。像「不管是谁都要排队」「就算是社长也要守规矩」：前面换成什么都一样，后面的结论不会变。它很正式，多半出现在新闻、演讲、文章里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放<b>名词</b>，直接加であれ：<span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長であれ</span></span><br>な形容词去掉「な」，直接加であれ：<span class='gd-pair'><span class='gd-jp'>有名な</span> → <span class='gd-jp'>有名であれ</span></span><br>也可以放「誰、何、どんな～」这类问句用的词：<span class='gd-pair'><span class='gd-jp'>誰</span> → <span class='gd-jp'>誰であれ</span></span><span class='gd-pair'><span class='gd-jp'>どう</span> → <span class='gd-jp'>どうであれ</span></span><br>「であれ」其实就是「である」（＝「だ」的书面说法，常用于文章）的命令形，但在这里<b>不是要人去做什么</b>，而是「随便是什么都一样」的让步用法，意思是「就算是～」。</div><div class='gd-h'>最常听到的三种样子</div><div class='gd-sec'><span class='gd-tag'>たとえ＋名词＋であれ</span>就算是某个特别的身分或情况，也一样。前面常加「たとえ」（就算）来加强。</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ子供であれ、自分のしたことには責任がある。</span>（就算是小孩，也要为自己做的事负责）</div><div class='gd-sec'><span class='gd-tag'>谁／何／どんな～＋であれ</span>不管是谁、不管是什么，全部都一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>誰であれ、許可なく入ることはできない。</span>（不管是谁，没有许可都不能进入）</div><div class='gd-ex-line'>・<span class='gd-jp'>理由はどうであれ、約束を破ったのは事実だ。</span>（不管理由是什么，违背约定是事实）</div><div class='gd-sec'><span class='gd-tag'>AであれBであれ</span>不管是A还是B，结果都一样。</div><div class='gd-ex-line'>・<span class='gd-jp'>男であれ女であれ、能力があれば評価される。</span>（不论男女，有能力就会被肯定）</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れであれ雨であれ、試合は予定どおり行う。</span>（不管晴天还是下雨，比赛都照原定计划举行）</div><div class='gd-sec'>后半句通常是<b>不会因此改变的结论</b>，常见「〜できない」「許されない」「〜べきだ」「変わりはない」。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放名词或な形容词语干，动词不能直接接：<b>不能说</b>「行くであれ」。前面想放动词，要改用「〜ようが」或「〜にせよ」。<br>・它很硬，平常聊天讲会很怪。口语改用「でも」，例如：<span class='gd-jp'>誰でも許可が必要だよ。</span>（不管是谁都需要许可喔）<br>・想说「谁都不能进」要用<span class='gd-jp'>誰も入れない</span>，不要说<span class='gd-jp'>誰でも入れない</span>（听起来很不自然）。如果想说「不是谁都能进」，要讲<span class='gd-jp'>誰でも入れるわけではない</span>。<br>・<span class='gd-jp'>であれ</span>跟<span class='gd-jp'>であれば</span>只差一个字，意思却完全不同。であれば是「如果是～」：<span class='gd-jp'>社長であれば決められる。</span>（如果是社长就能决定）；であれ是「就算是～也」：<span class='gd-jp'>社長であれ、勝手には決められない。</span>（就算是社长也不能擅自决定）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「不管理由是什么，迟到就是不行」：<br><b>であれ</b>：前面放名词或な形容词语干，最正式。<br><span class='gd-jp'>どんな理由であれ、遅刻は許されない。</span><br><b>にせよ</b>：前面可以放名词也可以放动词，稍微没那么硬。<br><span class='gd-jp'>どんな理由にせよ、遅刻はよくない。</span><br><span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>（不管去不去，都请联络我）<br><b>ようが／ようと</b>：前面放动词的意向形（〜う／〜よう的形），语气是「再怎么～都不管」。<br><span class='gd-jp'>どんな理由があろうと、遅刻は許されない。</span></div><div class='gd-warn'>判断小诀窍：前面是名词、场合很正式，用であれ；前面想放动词，用にせよ或ようが。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样是「A也好B也好」的句型还有「〜にせよ…にせよ」，以及固定说法「〜かれ〜かれ」：<span class='gd-jp'>多かれ少なかれ</span>（或多或少）、<span class='gd-jp'>遅かれ早かれ</span>（迟早）。</div>","n1-6":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とあれば」就是<b>「如果是～的话，那（我）就…」</b>。前面放的是一个<b>特别的、分量很重的理由</b>，像「为了孩子」「老板的命令」「好朋友拜托」；后面接「那我愿意做」或「那也只好做」。中文说「既然是为了孩子，再苦也甘愿」，就是这种感觉。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接接：<span class='gd-pair'><span class='gd-jp'>子供のため</span> → <span class='gd-jp'>子供のためとあれば</span></span><br>な形容词也是直接接：<span class='gd-pair'><span class='gd-jp'>必要</span> → <span class='gd-jp'>必要とあれば</span></span><br>动词用普通形（字典上那个样子，或ない形、た形）：<span class='gd-pair'><span class='gd-jp'>社長が来る</span> → <span class='gd-jp'>社長が来るとあれば</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>甘愿付出</span>为了重要的人或事，什么都愿意做。最常跟「のため」一起出现。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のためとあれば、親はどんな苦労も厭わない。</span>（只要是为了孩子，父母再辛苦都甘愿）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のためとあれば、どんな仕事でもする。</span>（只要是为了家人，什么工作我都做）</div><div class='gd-sec'><span class='gd-tag'>只好接受</span>对方的身分或情况特别，不做说不过去。</div><div class='gd-ex-line'>・<span class='gd-jp'>親友の頼みとあれば、断るわけにはいかない。</span>（既然是好朋友拜托，总不能拒绝）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（既然是社长的命令，也只能照做）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>商务场合很常听到这两句固定说法：</div><div class='gd-ex-line'>・<span class='gd-jp'>必要とあれば、いつでもご連絡ください。</span>（如果有需要，请随时跟我联络）</div><div class='gd-ex-line'>・<span class='gd-jp'>お客様のご希望とあれば、できる限り対応いたします。</span>（只要是客人希望的，我们会尽量配合）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要是<b>有分量的理由</b>。普通的日常条件不用它：「下雨的话就带伞」说<span class='gd-jp'>雨なら傘を持っていく</span>，说成「雨とあれば」很怪。<br>・后面通常接<b>决心或判断</b>，像<span class='gd-jp'>何でもする</span>、<span class='gd-jp'>喜んで</span>、<span class='gd-jp'>しかない</span>、<span class='gd-jp'>わけにはいかない</span>，不是单纯描述发生了什么事。<br>・名词后面直接接とあれば，不用另外加だ。<br>・语气正式、偏书面。跟朋友聊天说<span class='gd-jp'>子供のためなら</span>就好，意思差不多，比较轻松。<br>・「为了」是从前面的<span class='gd-jp'>のため</span>来的，とあれば本身只是「如果是～」，不是每句都有「为了」的意思。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>「とあれば」「とあって」都是「と＋あ…」开头，只差后面一点点；「ともなれば」也是と开头，看起来也很像。用同一个「社长」情境来比：<br><b>とあれば</b>＝<b>如果是</b>～，那就…（假设，后面接决心）：<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（如果是社长的命令，也只能照做）<br><b>とあって</b>＝<b>因为是</b>～，所以…（已经发生的事实，后面描述状况）：<span class='gd-jp'>社長の命令とあって、みんな必死に働いている。</span>（因为是社长下的命令，大家都拚命在做）<br><b>ともなれば</b>＝<b>一旦到了</b>～这个身分或程度，自然就…：<span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（一旦当上社长，责任自然就重了）</div><div class='gd-warn'>判断小诀窍：「如果是～我就愿意／只好」用とあれば；「因为是～所以现在这样」用とあって；「到了～这个地步就自然会」用ともなれば。</div>","n1-7":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜をおいて」就是中文的<b>「非～莫属」「除了～还有谁」</b>。说话的人先把一堆可能的人、事物想过一轮，最后认定：<b>真的只有这一个最适合</b>。它不只是在说「只有」，里面还带着很高的评价。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋<span class='gd-jp'>をおいて</span>＋<span class='gd-jp'>ほかに</span>〜<span class='gd-jp'>ない</span>／<span class='gd-jp'>いない</span><br>后面讲人就用<span class='gd-jp'>いない</span>，讲东西、时间、地方就用<span class='gd-jp'>ない</span>。<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼をおいてほかにいない</span></span>（除了他没有别人）<br><span class='gd-pair'><span class='gd-jp'>今</span> → <span class='gd-jp'>今をおいてほかにない</span></span>（除了现在没有别的时机）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>讲人</span>推荐人选、称赞某人是唯一人选时最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>次のリーダーにふさわしいのは、山田さんをおいてほかにいない。</span>（最适合当下一任队长的，非山田莫属）</div><div class='gd-sec'><span class='gd-tag'>讲时机</span><span class='gd-jp'>今をおいてほかにない</span>是固定说法，意思是「就是现在，错过就没了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>留学するなら、今をおいてほかにない。</span>（要去留学，就是现在了）</div><div class='gd-sec'><span class='gd-tag'>反问</span>后面不一定是「ない」，也可以用「还有谁呢？」的反问语气，意思一样是「只有他」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この役を演じられるのは、彼をおいて誰がいるだろうか。</span>（能演这个角色的，除了他还有谁呢）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>不能拿来讲单纯的事实</b>。「房间里除了他没别人」只是客观状况，要说<span class='gd-jp'>部屋には彼以外誰もいなかった</span>，不能用をおいて。<br>・它通常用在<b>好的评价</b>，像「最适合」「最厉害」「只有他做得到」。拿来讲坏事会很怪。<br>・<span class='gd-jp'>をおいて</span>跟<span class='gd-jp'>において</span>只差一个字，意思完全不同：<span class='gd-jp'>会議室において</span>是「在会议室」，表示场所或场合。<br>・这是比较正式、书面的讲法，常见于文章、演讲、新闻。跟朋友聊天直接说<span class='gd-jp'>彼しかいないよ</span>就好。<br>・<span class='gd-jp'>何をおいても</span>是另一个惯用说法，意思是「不管怎样都优先」：<span class='gd-jp'>何をおいても駆けつける</span>（不管怎样都会赶过去）。不要跟「除了～没有别的」搞混。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样在讲一家很厉害的老店：<br><b>をおいて</b>＝在一堆候选人里<b>挑出唯一一个</b>：<span class='gd-jp'>この味を出せるのは、あの店をおいてほかにない。</span>（做得出这个味道的，非那家店莫属）<br><b>ならでは</b>＝某种特色<b>只有它才有</b>：<span class='gd-jp'>これはあの店ならではの味だ。</span>（这是那家店才有的味道）<br><b>以外</b>＝单纯说<b>「除了～」</b>，不带评价：<span class='gd-jp'>あの店以外で食べたことがない。</span>（除了那家店，我没在别的地方吃过）</div><div class='gd-warn'>判断小诀窍：在讲「要选谁／选哪个，答案只有这个」，就用をおいて；在讲「这个特色是它专属的」，就用ならでは；只是客观说「除了～」，就用以外。</div>","n1-11":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ならまだしも」就是中文的<b>「～也就算了，可是…」</b>。先退一步说「如果只是这样，我还能接受」，再指出「但现在这个程度，真的不行」。整句的重点在后半：<b>你在抱怨、在表示无法接受</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>一度ならまだしも、三度も遅刻するなんて。</span>（一次也就算了，竟然迟到三次）</div><div class='gd-h'>拆开来看</div><div class='gd-sec'><span class='gd-jp'>まだしも</span>可以想成「<span class='gd-jp'>まだ</span>（还）＋<span class='gd-jp'>しも</span>（加强语气）」，意思是「还算说得过去」。所以句子的结构固定是：<br><b>比较轻、还能忍的情况</b>＋ならまだしも、<b>比较严重、不能接受的情况</b>。<br>前面那个轻的情况，常常是「实际上并不是这样」，只是拿来对比。像<span class='gd-jp'>冗談ならまだしも</span>，言下之意就是「你根本不是在开玩笑」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>：直接接。<span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談ならまだしも</span></span><br><b>な形容词</b>：不加だ，直接接。<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手ならまだしも</span></span><br><b>动词、い形容词</b>：用普通形（就是不加ます、です的普通说法）。<span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないならまだしも</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>对已经发生的事不满</span></div><div class='gd-ex-line'>・<span class='gd-jp'>知らないならまだしも、知っていて黙っていたのは許せない。</span>（不知道也就算了，明明知道还不说，我不能原谅）</div><div class='gd-sec'><span class='gd-tag'>判断还没发生的情况</span>后半不一定是过去的事，也可以是对假设、未来的判断。</div><div class='gd-ex-line'>・<span class='gd-jp'>夏はまだしも、冬はこの部屋じゃ無理だ。</span>（夏天还好，冬天住这个房间绝对不行）</div><div class='gd-sec'><span class='gd-tag'>拜托对方别再这样</span>后半也可以接请求或禁止。</div><div class='gd-ex-line'>・<span class='gd-jp'>一日ならまだしも、毎日来るのはやめてほしい。</span>（一天也就算了，每天都来真的拜托不要）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>名词后面也常直接用<span class='gd-jp'>はまだしも</span>，像上面的<span class='gd-jp'>夏はまだしも</span>，意思一样。<br>另外，意思很接近的还有<span class='gd-jp'>ならともかく</span>，很多时候可以互换。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>顺序不能颠倒</b>：前面放轻的、后面放严重的。说成<span class='gd-jp'>三度ならまだしも、一度遅刻するなんて</span>就不合逻辑了。<br>・名词和な形容词后面不要加だ：是<span class='gd-jp'>冗談ならまだしも</span>，不是冗談だならまだしも。<br>・后半要是负面的评价（<span class='gd-jp'>ありえない</span>、<span class='gd-jp'>許せない</span>、<span class='gd-jp'>無理だ</span>、<span class='gd-jp'>やめてほしい</span>这类），不能拿来称赞或讲好事。<br>・口气是在抱怨、念人，对长辈或客人直接这样讲会有指责的感觉，要小心场合。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是看到一个大人为了小事哭：<br><b>ならまだしも</b>：<span class='gd-jp'>子どもならまだしも、大人がこんなことで泣くなんて。</span>（小孩也就算了，大人竟然为这种事哭）<br><b>ではあるまいし</b>：<span class='gd-jp'>子どもではあるまいし、こんなことで泣かないで。</span>（又不是小孩子，别为这种事哭）<br><b>ならまだしも</b>的重点在「前面还能接受，后面这个程度就不行」的<b>落差</b>，常用来抱怨或表示无法接受。<b>ではあるまいし</b>的重点在「又不是～」，<b>否定前面的前提</b>，再要求对方该怎么做或下判断。</div><div class='gd-warn'>判断小诀窍：中文想讲「A也就算了，B就太过分了」用ならまだしも；想讲「又不是A，你应该…」用ではあるまいし。</div>","n1-12":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AこそあれB（ない）」就是中文的<b>「A是有，B可就没有了」</b>，白话一点就是<b>「只有A，没有B」</b>。像「对他只有感谢，没有怨恨」这种话。它是很硬的书面语，日常聊天说「<span class='gd-jp'>Aはあっても、Bはない</span>」就好。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>只有A没有B</span>前后放一组<b>相反或对比</b>的东西，例如感谢和怨恨、批评和赞美。先承认A确实存在，重点在强调后面的B「根本没有」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には感謝こそあれ、恨みは少しもない。</span>（对他只有感谢，一点怨恨也没有）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の行動には批判こそあれ、賞賛の声はほとんど聞かれない。</span>（对他的行为只有批评，几乎听不到赞美）</div><div class='gd-sec'><span class='gd-tag'>固定说法</span><span class='gd-jp'>程度の差こそあれ</span>、<span class='gd-jp'>多少の違いこそあれ</span>＝「虽然程度上有差别，但……」。这时后半<b>不一定是否定</b>，常用来说「大家其实都一样」。</div><div class='gd-ex-line'>・<span class='gd-jp'>程度の差こそあれ、誰にでも悩みはある。</span>（虽然程度不同，但每个人都有烦恼）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接加こそあれ：<span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝こそあれ</span></span><span class='gd-pair'><span class='gd-jp'>批判</span> → <span class='gd-jp'>批判こそあれ</span></span><br>后半常见的收尾是「<span class='gd-jp'>〜はない</span>」「<span class='gd-jp'>ほとんど〜ない</span>」「<span class='gd-jp'>〜ことはない</span>」。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放<b>名词</b>。动词的辞书形不能直接接，说成「批判するこそあれ」是错的。想用动词，请改用下面的「こそすれ」，而且要用<b>ます形把ます拿掉</b>的样子来接。<br>・它的意思<b>不是</b>「正因为有～」。这是旧式教材常见的误解，「正因为」是另一个文法。<br>・前后两边要是同一个话题里的对比组合。前后扯不上关系，例如「祭典有朴素感，但没有衰退迹象」，日本人听起来会觉得怪。<br>・语气很正式，常出现在文章、评论、演讲里。跟朋友讲会像在念公文。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>こそすれ</b>也是「只有A，没有B」，差在前面接的是<b>动作</b>。<br>接法：<b>动词ます形（把ます拿掉）＋こそすれ</b><br><span class='gd-pair'><span class='gd-jp'>上がります</span> → 把ます拿掉 → <span class='gd-jp'>上がりこそすれ</span></span><br><span class='gd-pair'><span class='gd-jp'>褒められます</span> → 把ます拿掉 → <span class='gd-jp'>褒められこそすれ</span></span><br>する动词可以用「名词＋こそすれ」，也可以用「し＋こそすれ」：<span class='gd-pair'><span class='gd-jp'>感謝します</span> → <span class='gd-jp'>感謝こそすれ</span>／<span class='gd-jp'>感謝しこそすれ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がりこそすれ、下がることはないだろう。</span>（物价只会涨，不会跌吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>褒められこそすれ、叱られる理由はない。</span>（该被称赞才对，没有理由挨骂）</div><div class='gd-sec'>同一个情境对照看：<br><span class='gd-jp'>彼女には感謝こそあれ、恨みはない。</span>（心里<b>有</b>的是感谢：讲「存在」）<br><span class='gd-jp'>彼女には感謝こそすれ、恨むことはない。</span>（我<b>会做</b>的是感谢：讲「动作」）<br>两句的中文意思几乎一样。</div><div class='gd-sec'>另外，「正因为～才～」是<span class='gd-jp'>〜ばこそ</span>；「只有～才～」是<span class='gd-jp'>〜てこそ</span>，例如<span class='gd-jp'>努力してこそ成功できる</span>（只有努力才能成功）。不要因为都有こそ，就跟こそあれ混在一起。</div><div class='gd-warn'>判断小诀窍：前面是<b>名词</b>（感谢、批判、差）就用こそあれ；前面是<b>动词</b>就用こそすれ，而且动词要先变成ます形再把ます拿掉，例如「上がり（こそすれ）」「褒められ（こそすれ）」「感謝し（こそすれ）」，千万不要写成「褒められるこそすれ」。</div>","n1-13":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜まで（のこと）だ」就像我们说的<b>「大不了就～嘛」</b>和<b>「我只是～而已啦」</b>。<span class='gd-jp'>まで</span>本来是「到」，这里可以想成<b>「事情顶多就到这一步，没什么大不了」</b>。前面接辞书形还是た形，意思不一样，下面分开讲。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>辞书形：大不了就～</span>计划行不通的时候，你已经想好退路，而且一副「没差，就这样做」的态度。前面很常有「〜なら」「〜ば」「〜ても」，先讲假如不顺利。</div><div class='gd-ex-line'>・<span class='gd-jp'>だめなら、また一からやり直すまでだ。</span>（不行的话，大不了从头再来）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も手伝ってくれないなら、一人でやるまでだ。</span>（没人要帮忙的话，我自己做就是了）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が動かなければ、歩いて帰るまでのことだ。</span>（电车停驶的话，大不了走路回去）</div><div class='gd-sec'><span class='gd-tag'>た形：只不过是～而已</span>解释自己做过的事，表示「没有别的意思」「没什么了不起」。被人道谢的时候很常用，听起来谦虚。</div><div class='gd-ex-line'>・<span class='gd-jp'>当然のことをしたまでです。</span>（我只是做了该做的事而已）</div><div class='gd-ex-line'>・<span class='gd-jp'>念のため、確認したまでです。</span>（我只是保险起见确认一下而已）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったことを言ったまでだ。</span>（我只是把心里想的说出来罢了）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>やり直す</span> → <span class='gd-jp'>やり直すまでだ</span></span><br>动词た形＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>した</span> → <span class='gd-jp'>したまでです</span></span><br>加不加「<span class='gd-jp'>のこと</span>」意思一样，加了更有「就这样而已」的感觉。要讲得客气，把<span class='gd-jp'>だ</span>换成<span class='gd-jp'>です</span>就好。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的<span class='gd-jp'>まで</span>不是「到～为止」。<span class='gd-jp'>帰るまで</span>单独出现是「到回家为止」，要看后面有没有接<span class='gd-jp'>だ</span>收尾。<br>・辞书形和た形不要接错：<span class='gd-jp'>やり直すまでだ</span>是「大不了重做」（还没做），<span class='gd-jp'>やり直したまでだ</span>是「我只是重做了而已」（已经做了）。<br>・辞书形的用法带有「豁出去」的语气，通常是讲<b>自己</b>这一方的决心，不是拿来叫别人去做。<br>・前面接的通常是「本来不是首选、但也没关系」的备案，不是什么值得高兴的好事。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>〜までだ</b>＝大不了就去做：<span class='gd-jp'>聞かれたら、説明するまでだ。</span>（被问到的话，解释就是了）<br><b>〜までもない</b>＝根本不必做：<span class='gd-jp'>簡単だから、説明するまでもない。</span>（很简单，不用特别解释）</div><div class='gd-sec'><b>〜までだ</b>＝还有退路，很乐观：<span class='gd-jp'>失敗したら、またやるまでだ。</span>（失败了大不了再来）<br><b>〜ばそれまでだ</b>＝一旦那样就全完了，很悲观：<span class='gd-jp'>一度失敗すれば、それまでだ。</span>（只要失败一次就完了）</div><div class='gd-warn'>判断小诀窍：「动词＋までだ」是还有路可走；「それまでだ」是路断了；「までもない」是不用走这条路。</div>","n1-17":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜そばから」就是中文的<b>「前脚才刚～，后脚就又～」</b>。你这边才在做，那边马上被打回原形，而且<b>每次都这样</b>，等于在做白工。想像你刚拖完地，小孩马上穿着拖鞋踩过去，拖一次踩一次，那种无力感就是そばから。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词的辞书形或た形，后面直接加そばから。<br><span class='gd-pair'><span class='gd-jp'>片付ける</span> → <span class='gd-jp'>片付けるそばから</span></span>（这边才在收拾）<br><span class='gd-pair'><span class='gd-jp'>覚えた</span> → <span class='gd-jp'>覚えたそばから</span></span>（才刚背完）<br>两种意思差不多。硬要分的话，辞书形比较像「一边做，一边就被破坏」，た形比较像「才刚做完就被破坏」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>努力被抵销</span>做了某件事，结果马上被打回原形。</div><div class='gd-ex-line'>・<span class='gd-jp'>覚えたそばから忘れてしまう。</span>（才刚背完就忘了）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪かきしたそばから、また積もっていく。</span>（才刚铲完雪，又积起来了）</div><div class='gd-sec'><span class='gd-tag'>前面进、后面出</span>东西才来就马上没了，留不住。</div><div class='gd-ex-line'>・<span class='gd-jp'>稼ぐそばから使ってしまうので、全然貯金できない。</span>（赚多少就花多少，完全存不了钱）</div><div class='gd-ex-line'>・<span class='gd-jp'>掃除するそばから、犬が毛を落としていく。</span>（我这边在打扫，狗就在那边一直掉毛）</div><div class='gd-sec'>后半句常常会搭配<span class='gd-jp'>〜てしまう</span>、<span class='gd-jp'>〜ていく</span>，或是用被动的<span class='gd-jp'>〜される</span>（例：<span class='gd-jp'>子供に散らかされる</span>），用来表现「事情不受控制、我拿它没办法」的感觉。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・そばから讲的是<b>反复发生</b>的事。只发生一次的事不能用，例如「我一到家就下雨了」不能说「家に着いたそばから雨が降り出した」。这种情况要用<span class='gd-jp'>とたん</span>或<span class='gd-jp'>や否や</span>。<br>・几乎都用在<b>抱怨、无奈、白费力气</b>的场面。好事一直来，一般不会用そばから。<br>・后半句是在描述「现实就是这样」，不能接「我要～」「请～」这类意志或命令的说法。<br>・这里的そば不是「荞麦（荞麦面）」，是「旁边」的意思。可以想成「才刚做，旁边就马上～」。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>〜が早いか</span>和<span class='gd-jp'>〜や否や</span>也是「一～就～」，但它们讲的是<b>某一次</b>的事，两件事紧接着发生，不带「白费」的意思。<br>同样讲领薪水：<br><b>そばから</b>：<span class='gd-jp'>給料が入るそばから使ってしまう。</span>（薪水一进来就被花掉，每个月都这样）<br><b>や否や</b>：<span class='gd-jp'>給料が入るや否や、新しいスマホを買った。</span>（那次薪水一入帐，我就马上买了新手机）</div><div class='gd-warn'>判断小诀窍：「每次都这样、做了等于白做」用そばから；「那一次，前一件事一发生，下一件马上跟着来」用が早いか或や否や。</div>","n1-21":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜んがため（に）」就是<b>「为了～，不惜一切」</b>。意思跟「ために」一样是「为了」，但口气强很多，有种「非达成不可」的拚劲。它很古风，平常聊天几乎不讲，比较常在小说、演讲、评论文章里看到。</div><div class='gd-h'>这个「ん」是什么</div><div class='gd-sec'>这里的「ん」<b>不是否定</b>，是古文里表示「想要～、打算～」的字，意思接近现代的「〜う／〜よう」。「が」相当于「の」。所以<span class='gd-jp'>勝たんがため</span>大约就是「想要赢的那个目的」，也就是「为了赢」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>先把动词变成ない形，<b>把ない拿掉</b>，再加「んがため（に）」。</div><div class='gd-sec'><b>第一类（五段动词）</b>：<br><span class='gd-pair'><span class='gd-jp'>勝つ</span> → <span class='gd-jp'>勝たない</span> → <span class='gd-jp'>勝たんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>売る</span> → <span class='gd-jp'>売らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わんがため</span></span>（う结尾的要变わ，跟ない形一样）</div><div class='gd-sec'><b>第二类（一段动词）</b>：<br><span class='gd-pair'><span class='gd-jp'>生きる</span> → <span class='gd-jp'>生きない</span> → <span class='gd-jp'>生きんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>逃れる</span> → <span class='gd-jp'>逃れんがため</span></span></div><div class='gd-sec'><b>第三类</b>：<span class='gd-jp'>する</span>要变成<b>せ</b>，不是し。<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>優勝する</span> → <span class='gd-jp'>優勝せんがため</span></span><br>「来る」在这个句型里几乎看不到，不用特别记。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>んがために</span>放在句子前半，后面接「为此做了什么」。</div><div class='gd-ex-line'>・<span class='gd-jp'>勝たんがために、彼は必死に練習した。</span>（为了赢，他拚了命地练习）</div><div class='gd-ex-line'>・<span class='gd-jp'>生きんがために、どんな仕事でもした。</span>（为了活下去，什么工作都做过）</div><div class='gd-sec'><span class='gd-tag'>んがための＋名词</span>修饰后面的名词。<span class='gd-jp'>売らんがため</span>常带负面意思，指「一心只想卖钱」。</div><div class='gd-ex-line'>・<span class='gd-jp'>売らんがための広告には、もううんざりだ。</span>（那种只想着卖东西的广告，我已经受够了）</div><div class='gd-sec'><span class='gd-tag'>んがためだ</span>放句尾，说明「那样做，是为了～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が嘘をついたのは、自分を守らんがためだった。</span>（他会说谎，是为了保护自己）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・する是<b>せんがため</b>，写成「しんがため」是错的。<br>・「ん」不是否定：<span class='gd-jp'>勝たんがため</span>是「为了赢」，不是「为了不赢」。<br>・后半要是<b>有人刻意去做的事</b>，而且通常是同一个人自己想达成的目标，不能拿来讲天气、自然现象。<br>・后半不接「请你～」「去做～」：<span class='gd-jp'>合格せんがため、勉強しなさい</span>不自然，要说<span class='gd-jp'>合格するために、勉強しなさい</span>。<br>・用在小事上会很夸张好笑：买面包去超商，讲<span class='gd-jp'>パンを買うために</span>就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境「为了考上，每天念书念到很晚」：<br><b>ために</b>＝一般的「为了」，什么场合都能用：<span class='gd-jp'>合格するために、毎晩遅くまで勉強した。</span><br><b>べく</b>＝书面的「为了」，辞书形直接接，する可以变<span class='gd-jp'>すべく</span>：<span class='gd-jp'>合格すべく、毎晩遅くまで勉強した。</span><br><b>んがため</b>＝更古风、更有「拚死也要」的感觉：<span class='gd-jp'>合格せんがため、毎晩遅くまで勉強した。</span></div><div class='gd-sec'>另一个要小心的是<b>んばかりに</b>，前面的变法一模一样，意思却完全不同，是「简直就要～的样子」：<br><span class='gd-jp'>泣かんばかりに頼んだ。</span>（几乎要哭出来似地拜托）</div><div class='gd-warn'>判断小诀窍：「ん」后面接<b>がため</b>是「为了」，接<b>ばかり</b>是「几乎要」。想表达「为了」：平常用ために，书面用べく，要写出「不惜一切」的气势才用んがため。</div>","n1-24":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とあって」就是新闻、报导很爱用的<b>「因为是～这么特别的状况，所以果然…」</b>。像台湾新闻常说「适逢连假首日，机场涌现大批旅客」，那个「适逢～」的感觉就是它。前面讲一个特别的日子或场合，后面讲因此看到的场面、大家的反应。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>特别的日子・场合</span>连假、特卖、烟火大会这种不是天天有的事，所以人特别多、特别热闹。</div><div class='gd-ex-line'>・<span class='gd-jp'>連休初日とあって、空港は大混雑だった。</span>（适逢连假第一天，机场挤得不得了）</div><div class='gd-ex-line'>・<span class='gd-jp'>年に一度のセールとあって、店の前には朝から長い列ができていた。</span>（因为是一年一次的特卖，店门口一大早就排了长长的人龙）</div><div class='gd-sec'><span class='gd-tag'>人的反应</span>因为状况难得，当事人紧张、兴奋、特别认真。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての海外旅行とあって、娘はずいぶん張り切っている。</span>（因为是第一次出国，女儿超级兴奋）</div><div class='gd-ex-line'>・<span class='gd-jp'>人気歌手が来るとあって、会場には若い人が大勢集まった。</span>（因为有人气歌手要来，会场聚集了一大堆年轻人）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>：直接接，一般不加「だ」。<br><span class='gd-pair'><span class='gd-jp'>連休</span> → <span class='gd-jp'>連休とあって</span></span><span class='gd-pair'><span class='gd-jp'>花火大会</span> → <span class='gd-jp'>花火大会とあって</span></span><br><b>动词、い形容词</b>：用普通形（就是不加ます、です的说法，过去式也可以）。<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るとあって</span></span><span class='gd-pair'><span class='gd-jp'>優勝した</span> → <span class='gd-jp'>優勝したとあって</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとあって</span></span></div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面只能写<b>实际看到的结果、状况</b>，不能放自己的打算、邀约、请求。<br>×<span class='gd-jp'>連休とあって、旅行に行こう。</span><br>○<span class='gd-jp'>連休だから、旅行に行こう。</span>（因为连假，去旅行吧）<br>・前面要是<b>特别、难得</b>的事。太日常的理由听起来很怪，像「肚子饿了所以买面包」直接用「から」「ので」就好。<br>・名词后面通常不加だ：要说<span class='gd-jp'>連休とあって</span>，不说連休だとあって。<br>・这是书面、新闻的口气，跟朋友聊天讲「〜から」「〜ので」比较自然。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是跟「社长」有关的情境：<br><b>とあって</b>＝因为是～，<b>所以看到这种结果</b>（已经发生的事）<br><span class='gd-jp'>社長が来るとあって、社員はみんな緊張している。</span>（因为社长要来，员工都很紧张）<br><b>とあれば</b>＝<b>如果是～的话</b>，就（愿意）…（假设、条件）<br><span class='gd-jp'>社長の頼みとあれば、断るわけにはいかない。</span>（如果是社长拜托的，总不能拒绝）<br><b>にあって</b>＝<b>身处～的立场、状况中</b><br><span class='gd-jp'>社長という立場にあって、そんな発言は許されない。</span>（身为社长，那种发言是不被允许的）</div><div class='gd-warn'>判断小诀窍：「因为是～，所以（大家）果然…」是とあって；「如果是～的话」是とあれば；「身在～之中」是にあって。</div>","n1-25":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ばこそ」就是<b>「正因为～，才…」</b>，跟「からこそ」意思差不多，只是更正式、更像文章或演讲里的说法。很常用在「看起来不好的事，背后其实有好的理由」，例如「正因为爱你，才骂你」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>说出真正的理由</span>别人可能误会你的行为，你想强调「我这么做，是因为～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたを思えばこそ、厳しく言うのです。</span>（正因为为你着想，我才对你说重话）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼していればこそ、この仕事を任せたのです。</span>（正因为信任你，才把这份工作交给你）</div><div class='gd-sec'><span class='gd-tag'>有这个条件才做得到</span>强调某个好条件是关键。</div><div class='gd-ex-line'>・<span class='gd-jp'>若ければこそ、失敗を恐れずに挑戦できる。</span>（正因为年轻，才能不怕失败去挑战）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康であればこそ、好きなことに挑戦できる。</span>（正因为身体健康，才能挑战自己喜欢的事）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>先把前面的词变成「〜ば」的样子，再加<b>こそ</b>。<br><b>第一类（五段动词）</b>：最后一个音换成同一行的「え」段音，加ば。<br><span class='gd-pair'><span class='gd-jp'>思う</span> → う换成え → <span class='gd-jp'>思えばこそ</span></span><br><b>第二类（一段动词）</b>：把る拿掉，加れば。<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じればこそ</span></span><br><b>第三类（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればこそ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ればこそ</span>（くればこそ）</span><br>「〜ている」的话，把いる变成いれば：<span class='gd-pair'><span class='gd-jp'>案じている</span> → <span class='gd-jp'>案じていればこそ</span></span></div><div class='gd-sec'><b>い形容词</b>：把い换成ければ。<span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若ければこそ</span></span><br><b>名词、な形容词</b>：后面加であれば。<span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親であればこそ</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康であればこそ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>親であればこそ、子どもの幸せを願うのだ。</span>（正因为是父母，才会希望孩子幸福）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的「ば」<b>不是「如果」</b>，是「因为」。<span class='gd-jp'>思えばこそ</span>不是「如果想的话」，而是「正因为想着（你）」。这是古文留下来的用法，所以看起来跟条件形一模一样。<br>・名词、な形容词不能直接接：要说<span class='gd-jp'>健康であればこそ</span>，不是「健康ばこそ」。<br>・语气很正式，聊天时很少用。跟朋友讲用<span class='gd-jp'>からこそ</span>就好，用ばこそ会像在念稿。<br>・前面的理由通常是正面、真心的（爱、信任、健康、努力），不太拿来讲倒楣或负面的原因。<br>・后半句常用<span class='gd-jp'>のだ／のです</span>收尾，有「其实是这样」的感觉，例句里可以多注意。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>からこそ</b>＝正因为～才…，口语、书面都能用：<span class='gd-jp'>好きだからこそ、厳しく言うんだよ。</span>（就是因为喜欢你，才讲得比较重）<br><b>ばこそ</b>＝意思一样，但更正式，多用在文章、演讲：<span class='gd-jp'>愛すればこそ、厳しく言うのである。</span>（正因为爱，才会严厉地说）<br><b>あっての</b>＝「有了～才有…」，前面接名词，重点是「没有它就不成立」：<span class='gd-jp'>健康あっての人生だ。</span>（有健康才有人生）</div><div class='gd-warn'>判断小诀窍：平常讲话用からこそ；写文章、致词想讲得庄重一点用ばこそ；要说「少了它就什么都没有」就用あっての。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样是 N1 讲原因的说法，还可以接着看<span class='gd-jp'>〜ゆえ（に）</span>（因为～，更书面）和<span class='gd-jp'>〜あっての</span>。</div>","n1-26":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜手前」就是中文的<b>「话都说出口了，总不能…」「人家都在看，拉不下脸…」</b>。因为自己已经说了、做了什么，或是有某些人在看，为了顾<b>自己的面子和立场</b>，只好这样做，或是不能那样做。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>话都说出口了</span>前面放动词，通常是自己已经说过、做过的事。因为说过了，现在不能打自己的脸。</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた手前、途中でやめるわけにはいかない。</span>（既然都接下来了，总不能做到一半就放弃）</div><div class='gd-ex-line'>・<span class='gd-jp'>「絶対合格する」と言った手前、遊んでいられない。</span>（都夸下海口说「一定会考上」了，哪还能玩）</div><div class='gd-sec'><span class='gd-tag'>有人在看</span>前面放人，意思是「当着～的面」「顾虑～怎么看我」。要顾的是<b>自己</b>在这些人眼中的形象。</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの手前、そんなことは言えない。</span>（当着大家的面，那种话说不出口）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの手前、夫婦げんかはしないようにしている。</span>（顾虑到孩子，我们尽量不在孩子面前吵架）</div><div class='gd-sec'><span class='gd-tag'>自己的身分</span>用「〜である手前」讲自己的身分，意思是「身为～，总不能…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である手前、生徒の前でたばこは吸えない。</span>（身为老师，总不能在学生面前抽烟）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词：直接接普通形（就是不加ます的说法）。最常见的是た形，辞书形、ている形也可以。<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した手前</span></span><span class='gd-pair'><span class='gd-jp'>言っている</span> → <span class='gd-jp'>言っている手前</span></span><br>名词：加「の」再接。<span class='gd-pair'><span class='gd-jp'>部下</span> → <span class='gd-jp'>部下の手前</span></span><br>后半句常常是「不得不」或「不能」的说法，例如<span class='gd-jp'>〜わけにはいかない</span>、<span class='gd-jp'>〜しかない</span>、<span class='gd-jp'>〜られない</span>、<span class='gd-jp'>〜ないといけない</span>。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它讲的是<b>自己（或句子主语）</b>的面子和立场，不是在顾对方的面子。<span class='gd-jp'>部長は部下の手前、ミスを認めにくかった。</span>是部长在部属面前拉不下脸，要顾的是部长自己的形象，不是部属的面子。<br>・后半句几乎都是「只好～」「不能～」这种被逼的感觉，不能接开心、期待的事。像「約束した手前、楽しみだ」就很怪。<br>・<span class='gd-jp'>手前</span>念<b>てまえ</b>。它本来是「这一侧、前面一点」的意思，例如<span class='gd-jp'>駅の手前で降りる</span>（在快到车站的地方下车）。看到「名词＋の手前」要看前后文：前面是人，后面是不能做、只好做的事，就是这个文法，不是在讲位置。<br>・这是偏正式、书面一点的说法，日常聊天比较常听到「言っちゃったし…」这种讲法。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>〜からには</span>、<span class='gd-jp'>〜以上</span>也翻成「既然～」，但重点不一样：<br><b>からには／以上</b>＝既然～了，就应该、就要负责到底。重点是<b>道理和决心</b>。<br><b>手前</b>＝既然～了，不这样做<b>会很没面子</b>。重点是<b>别人怎么看我</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず行く。</span>（既然答应了，我就一定会去：讲决心）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束した手前、行かないわけにはいかない。</span>（都答应人家了，不去实在说不过去：讲面子）</div><div class='gd-sec'>からには、以上后面可以接自己想做的事，手前就不行：<br><span class='gd-jp'>日本に来たからには、富士山に登りたい。</span>（既然来了日本，就想去爬富士山）<br>这句换成手前就不通，因为爬不爬富士山跟面子没有关系。</div><div class='gd-warn'>判断小诀窍：后面能补一句「不然很丢脸、说不过去」的，用手前；只是「既然～，就应该～」，用からには或以上。</div>","n1-32":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ところを」最常见的就是中文的<b>「百忙之中还麻烦您」「在您休息的时候打扰了」</b>。先点出「对方正处在某个状态（很忙、在休息、很累）」，后面接<b>感谢或道歉</b>，是很正式的客套说法。另外它也能表示<b>「本来应该～，却…」</b>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>客套：打扰到对方</span>前面放对方的状况，后面放「谢谢」「不好意思」，或是对方为你做了什么。商务电话、致词、email 超常出现。</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところをありがとうございます。</span>（百忙之中，谢谢您）</div><div class='gd-ex-line'>・<span class='gd-jp'>お休みのところ、申し訳ありません。</span>（您休息的时候打扰，真抱歉）</div><div class='gd-ex-line'>・<span class='gd-jp'>お疲れのところ、すみません。少しだけいいですか。</span>（您累了还打扰，不好意思。可以占用一点时间吗）</div><div class='gd-sec'><span class='gd-tag'>本来应该～却</span>前面说「照理来讲会怎样」，后面说实际上变成另一个样子，通常是对自己有利的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>本来ならこちらから伺うべきところを、わざわざお越しいただきました。</span>（本来应该由我们登门拜访，却劳您特地跑一趟）</div><div class='gd-ex-line'>・<span class='gd-jp'>普通なら罰金のところを、今回は注意だけで済んだ。</span>（一般来说要罚钱，这次只被警告就没事了）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>动词</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>休んでいる</span> → <span class='gd-jp'>休んでいるところを</span></span><br><span class='gd-pair'><span class='gd-jp'>伺うべき</span> → <span class='gd-jp'>伺うべきところを</span></span><br><b>い形容词</b>：直接接，客套时前面常加お。<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>お忙しいところを</span></span><br><b>な形容词</b>：加な再接。<br><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変なところを</span></span><br><b>名词</b>：加の再接。<br><span class='gd-pair'><span class='gd-jp'>お休み</span> → <span class='gd-jp'>お休みのところを</span></span><br><span class='gd-pair'><span class='gd-jp'>ご多忙</span> → <span class='gd-jp'>ご多忙のところを</span></span><br>讲话时「を」常常省略，说成<span class='gd-jp'>お忙しいところ</span>也完全可以。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・い形容词后面不能加の：是<span class='gd-jp'>お忙しいところ</span>，不是お忙しいのところ。名词才要加の。<br>・这是很正式的说法，对朋友讲「お忙しいところを」会变得很生疏。朋友之间说<span class='gd-jp'>忙しいのにごめんね</span>就好。<br>・客套用法前面放的是<b>对方</b>的状态，不是自己的。自己很忙还来帮忙，不会说「私の忙しいところを」。<br>・后面的事通常会<b>影响到对方</b>：打扰、麻烦、对方为你做了什么。不能接跟对方无关的事。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ところを＋見る／見つかる</b>＝<b>被撞见的那个场面</b>，这是 N3 的「ところ」加上受词的を，不是客套：<span class='gd-jp'>タバコを吸っているところを先生に見られた。</span>（抽烟的时候被老师看到了）<br><b>ところを（本来应该～却）</b>＝照理会那样，实际却有好结果：<span class='gd-jp'>普通なら怒られるところを、許してもらった。</span>（一般来说会被骂，却被原谅了）<br><b>ものを</b>＝「明明～就好了」，带抱怨、遗憾，常放在句尾：<span class='gd-jp'>一言言ってくれればよかったものを。</span>（说一声就好了嘛）</div><div class='gd-warn'>判断小诀窍：后面是「見られた、見つかった」→ 被撞见的场面；后面是谢谢、抱歉或得到好处 → 客套／本来应该却；整句在抱怨「早知道就～」→ ものを。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>意思很接近、也常用在客套的「中」：<span class='gd-jp'>お足元の悪い中、お越しいただきありがとうございます。</span>（天候不佳，感谢各位前来）</div>","n1-35":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜の至り」就是中文的<b>「〜之至」</b>，像「荣幸之至」「感激之至」。日文说<span class='gd-jp'>光栄の至りです</span>，意思是「我真的荣幸到了极点」。这是很正式的讲法，通常在典礼致词、得奖感言、商业书信里出现，平常跟朋友聊天不会这样讲。</div><div class='gd-h'>「至り」是什么</div><div class='gd-sec'><span class='gd-jp'>至り</span>是动词<span class='gd-jp'>至る</span>（到达）变成的名词，意思是「走到最顶点」。所以<span class='gd-jp'>光栄の至り</span>＝光荣走到最顶点＝光荣到不行。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋の至り，句尾通常接です或でございます。<br><span class='gd-pair'><span class='gd-jp'>光栄</span> → <span class='gd-jp'>光栄の至りです</span></span><br><span class='gd-pair'><span class='gd-jp'>感激</span> → <span class='gd-jp'>感激の至りでございます</span></span><br>要特别注意，前面放的名词<b>几乎就是固定那几个</b>，不是什么名词都能套进去。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>感谢・荣幸</span>最常见的是<span class='gd-jp'>光栄の至り</span>、<span class='gd-jp'>感激の至り</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（能得到这样的奖项，真是荣幸之至）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様から温かいお言葉をいただき、感激の至りです。</span>（收到各位温暖的话，真是感激之至）</div><div class='gd-sec'><span class='gd-tag'>过意不去・惭愧</span>常见的是<span class='gd-jp'>恐縮の至り</span>（非常过意不去）、<span class='gd-jp'>赤面の至り</span>（惭愧到脸红）。</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところお越しいただき、恐縮の至りでございます。</span>（百忙之中劳驾您前来，实在过意不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな初歩的なミスをしてしまい、赤面の至りです。</span>（犯了这么基本的错，真是惭愧至极）</div><div class='gd-sec'><span class='gd-tag'>特别的一个</span><span class='gd-jp'>若気の至り</span>的意思不太一样，指的是「年轻不懂事所犯下的错」。这里的至り比较接近「造成的结果」。这句话常拿来回想以前做过的荒唐事，带一点自嘲，不一定是正式场合。</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は若気の至りで、ずいぶん無茶をした。</span>（学生时代年少轻狂，做了不少鲁莽的事）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要放<b>名词＋の</b>，不能直接接形容词。<span class='gd-jp'>嬉しいの至り</span>、<span class='gd-jp'>ありがたいの至り</span>都是错的。想表达开心、感谢，就用<span class='gd-jp'>光栄</span>、<span class='gd-jp'>感激</span>这些固定搭配。<br>・不要自己随便换名词，背熟光栄・感激・恐缩・赤面・若気这几个最安全。<br>・这个说法主要是讲<b>自己</b>的心情，带有谦虚的味道。用它描述别人的心情，例如说「部长很荣幸之至」，听起来会很怪。<br>・它的语气非常正式。跟朋友说<span class='gd-jp'>ケーキありがとう、感激の至り！</span>，听起来会像在开玩笑、故意装模作样。<br>・<span class='gd-jp'>若気</span>念<span class='gd-jp'>わかげ</span>，不是わかき。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>の至り</b>＝自己的感谢或惭愧到了极点，语气谦虚：<span class='gd-jp'>お招きいただき、光栄の至りです。</span>（承蒙邀请，荣幸之至）<br><b>極まりない</b>＝某件事或某个态度「极度～」，多半拿来批评、抱怨：<span class='gd-jp'>連絡もなく欠席するなんて、失礼極まりない。</span>（连联络都没有就缺席，实在失礼至极）<br><b>に至る</b>＝动词，表示事情「发展到某个结果或地步」：<span class='gd-jp'>何度も話し合った結果、ようやく合意に至った。</span>（经过多次讨论，终于达成共识）</div><div class='gd-warn'>判断小诀窍：讲自己心情的「～之至」用の至り，骂人或抱怨「极度～」用極まりない，讲事情「演变到～」用に至る。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'><span class='gd-jp'>〜に堪えない</span>也是正式场合表达强烈心情的说法：<span class='gd-jp'>皆様のご支援には感謝に堪えません。</span>（对各位的支持感激不尽）</div>","n1-41":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜といったらない」就是中文的<b>「～得没话说」「～到不行」「～死了」</b>。字面上是「要说有多～，简直找不到话来形容」，用来夸张地强调某种感觉强烈到极点。好的坏的都能讲：高兴到不行、冷到不行、丢脸死了，都可以用。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>＋といったらない（最常见的是把形容词变成「～さ」的名词）<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い换成さ → <span class='gd-jp'>寒さといったらない</span></span><br><b>い形容词</b>：直接接<br><span class='gd-pair'><span class='gd-jp'>うれしい</span> → <span class='gd-jp'>うれしいといったらない</span></span><br><b>な形容词</b>：不加な，直接接<br><span class='gd-pair'><span class='gd-jp'>退屈</span> → <span class='gd-jp'>退屈といったらない</span></span></div><div class='gd-sec'>讲<b>过去</b>发生的事，改成「といったら<b>なかった</b>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて富士山を見た時の感動といったらなかった。</span>（第一次看到富士山时，那份感动真的无法形容）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日同じ作業ばかりで、退屈といったらない。</span>（每天都做一样的事，无聊到不行）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>ったらない</span>「といったらない」的口语缩短版，跟朋友聊天、发牢骚时很常听到，前面多半直接接い形容词。</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の工事、うるさいったらないよ。</span>（隔壁在施工，吵死了）</div><div class='gd-sec'><span class='gd-tag'>ったらありゃしない</span>更口语、更有情绪的说法，大多用在抱怨、丢脸、生气。</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの前で転ぶなんて、恥ずかしいったらありゃしない。</span>（在大家面前跌倒，丢脸死了）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这里的「ない」<b>不是否定</b>。<span class='gd-jp'>うれしいといったらない</span>是「高兴得不得了」，不是「不高兴」。<br>・な形容词不要加な：说<span class='gd-jp'>退屈といったらない</span>，不说退屈なといったらない。<br>・事情已经过去了，要用「といったらなかった」，不然听起来像现在还在发生。<br>・前面通常放形容词或名词，尤其是「～さ」；动词很少这样直接接。<br>・「ったらない」「ったらありゃしない」很口语，正式场合或对上司不要用。<br>・别跟「といったら（说到～）」搞混：<span class='gd-jp'>日本といったら、やっぱり寿司だ。</span>（说到日本，果然就是寿司）后面没有ない，意思完全不同。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>〜ったら（n1-44）</b>：前面接<b>人</b>，意思是「我说那个～啊」，带着无奈或抱怨，后面接一整句话。<br><span class='gd-jp'>うちの母ったら、また夜中に電話してきた。</span>（我妈真是的，又半夜打电话来）<br><span class='gd-jp'>うちの母、心配性ったらない。</span>（我妈爱操心到不行）</div><div class='gd-warn'>判断小诀窍：「ったら」后面紧接着「ない」、前面是形容词或「～さ」，就是在讲程度；前面是人、后面接一句话，就是在抱怨那个人。</div><div class='gd-sec'><b>〜極まりない（n1-34）</b>：也是「～到极点」，但比较生硬、偏书面，大多用在负面评价，像新闻、客诉信。「といったらない」比较像在讲自己的亲身感受，正面负面都能用。<br><span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（那个店员的态度失礼至极：像正式投诉）<br><span class='gd-jp'>あの店員の態度の悪さといったらなかった。</span>（那个店员态度差到不行：像在跟朋友讲经历）</div><div class='gd-warn'>判断小诀窍：写正式文章、严厉批评用「極まりない」；讲自己的感受、带点情绪夸张用「といったらない」。</div>","n1-42":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「Aと言わずBと言わず」就是中文的<b>「不管是A还是B，全都～」</b>。举出两个有代表性的部分，让人感觉到「<b>整个都是这样</b>」。像中文说「手上、脚上全是泥巴」，其实是在说整个人都脏兮兮。</div><div class='gd-ex-line'>・<span class='gd-jp'>手と言わず足と言わず、泥だらけになった。</span>（不管手还是脚，全都沾满了泥）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋と言わず＋名词＋と言わず，<b>两个名词后面都要各接一个「と言わず」</b>。<br>「言わず」是「言わない」比较文言的说法，字面是「不说是A、也不说是B」，意思就是「A、B都不分」。也常写成平假名<span class='gd-jp'>といわず</span>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>身体</span>从头到脚、全身都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>顔と言わず腕と言わず、蚊に刺されてしまった。</span>（脸上、手臂上，到处都被蚊子叮了）</div><div class='gd-sec'><span class='gd-tag'>地点</span>整个空间、整个地方都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>壁と言わず床と言わず、部屋中に落書きがしてあった。</span>（墙上也好地上也好，整个房间都是涂鸦）</div><div class='gd-sec'><span class='gd-tag'>时间</span>不分时段，一直都是。</div><div class='gd-ex-line'>・<span class='gd-jp'>昼と言わず夜と言わず、工事の音が響いている。</span>（不管白天晚上，施工的声音一直响个不停）</div><div class='gd-ex-line'>・<span class='gd-jp'>平日と言わず週末と言わず、この店はいつも行列ができている。</span>（不管平日还是周末，这家店总是在排队）</div><div class='gd-sec'>你会发现后半句常出现<span class='gd-jp'>部屋中</span>、<span class='gd-jp'>町中</span>、<span class='gd-jp'>いつも</span>、<span class='gd-jp'>だらけ</span>这类「全部」的字眼，跟前面的「不分A、B」互相呼应。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・两个「と言わず」都要写。<span class='gd-jp'>手と足と言わず</span>是错的，要说<span class='gd-jp'>手と言わず足と言わず</span>。<br>・A跟B要是<b>同一类东西</b>，而且是某个整体的一部分（手和脚＝全身、白天和晚上＝整天）。随便拿两个不相关的东西凑在一起会很怪。<br>・它是拿来<b>描述实际看到的状况</b>，而且常常是让人吃惊、不太好的状况（全身是泥、到处是伤、吵个不停）。<br>・这是书面、比较硬的说法，小说、报导比较常看到。平常聊天的话，日本人多半说<span class='gd-jp'>手も足も</span>、<span class='gd-jp'>どこもかしこも</span>。<br>・别跟单独出现的「と言わず」搞混：<span class='gd-jp'>明日と言わず、今すぐ行こう。</span>（别说明天了，现在就去吧）这是「不用等到A」的意思，跟本文法不一样。<br>・<span class='gd-jp'>何も言わずに帰った</span>（什么都没说就回去了）里的「言わず」是真的「没说话」，跟这个句型无关。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「不管A还是B」，<span class='gd-jp'>Aであれ Bであれ</span>的感觉不一样：<br><b>と言わず</b>＝<b>描述眼前的实际状况</b>，到处都这样：<br><span class='gd-jp'>駅前と言わず住宅街と言わず、どこも観光客であふれている。</span>（不管车站前还是住宅区，到处都挤满观光客）<br><b>であれ</b>＝<b>不管是哪一个，都适用同一个规定或判断</b>：<br><span class='gd-jp'>駅前であれ住宅街であれ、ごみを捨ててはいけない。</span>（不管是车站前还是住宅区，都不可以乱丢垃圾）<br>第二句在讲规定，换成と言わず就不自然了。</div><div class='gd-warn'>判断小诀窍：在描述「放眼看去到处都是」，用と言わず；在说「不管哪种都一样要～」的规定、判断，用であれ。</div>","n1-44":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「名词＋ったら」就是中文的<b>「我们家那个齁，真是的…」</b>。先把一个身边的人点出来，接着讲他让你又好气又好笑的事。重点是<b>无奈、抱怨，但带着亲暱</b>，不是真的在骂人。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词后面直接加「ったら」，不用变化。<br><span class='gd-pair'><span class='gd-jp'>弟</span> → <span class='gd-jp'>弟ったら</span></span><span class='gd-pair'><span class='gd-jp'>お母さん</span> → <span class='gd-jp'>お母さんったら</span></span><span class='gd-pair'><span class='gd-jp'>あなた</span> → <span class='gd-jp'>あなたったら</span></span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>跟别人抱怨</span>跟朋友聊家人、同事、宠物的时候，用来带出「他又来了」的话题。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの猫ったら、また私の椅子で寝てる。</span>（我家的猫真是的，又睡在我的椅子上）</div><div class='gd-ex-line'>・<span class='gd-jp'>父ったら、また眼鏡をなくしたの。</span>（我爸真是的，又把眼镜弄丢了）</div><div class='gd-sec'><span class='gd-tag'>当面念对方</span>直接叫对方，表示「你喔，真是的！」，常常配「もう」。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう、お母さんったら！その話はしないでって言ったでしょ。</span>（唉唷，妈！不是叫你不要讲那件事吗）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんったら、冗談ばっかり。</span>（田中你真是的，老爱开玩笑）</div><div class='gd-sec'>后面的话常常讲一半就停，像<span class='gd-jp'>弟ったら、また忘れ物して…。</span>（我弟真是的，又忘东西了…），没讲完的部分就是那声「唉」。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它<b>不是「如果」</b>。<span class='gd-jp'>雨が降ったら</span>的たら是「如果～的话」，名词＋ったら是「说到～真是的」，两个完全不同。<br>・语气很口语、很亲近，用在家人、朋友、宠物身上。对上司、客人当面讲，或在正式场合讲，都不适合。<br>・后面通常接<b>让你傻眼、无奈、有点不好意思</b>的事。单纯想夸人、谢谢人，用一般的「は」就好。要搭配好事时，也是「他太客气了啦，真是的」这种害羞或无奈的感觉。<br>・ったら前面有个小小的っ，要停一拍念成「ったら」，不要念成「たら」。<br>・你也会听到<span class='gd-jp'>お母さんってば</span>，语气跟ったら很像，都是口语。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ったら</b>＝无奈里带着疼爱，也可以当面叫对方：<br><span class='gd-jp'>うちの子ったら、またゲームばっかり。</span>（我家小孩真是的，又在打电动）<br><b>ときたら</b>＝比较认真地数落，负面感比较重，多半是跟别人讲，不会拿来当面叫对方：<br><span class='gd-jp'>うちの子ときたら、毎日ゲームばっかりで全然勉強しない。</span>（说到我家小孩，每天只会打电动，完全不念书）<br><b>ったらない</b>＝前面多半接形容词，意思是「～得要命」，跟抱怨某个人无关：<br><span class='gd-jp'>あの時は恥ずかしいったらなかった。</span>（那时候真是丢脸得要命）</div><div class='gd-warn'>判断小诀窍：嘴角带笑说「真是的」是ったら；皱着眉头数落是ときたら；ったら后面还有「ない」，而且前面是形容词，就是「～得要命」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着学<span class='gd-jp'>～ときたら</span>，把「亲暱抱怨」和「认真数落」这两种语气分清楚。</div>","n1-45":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ときたら」就像台湾人抱怨时说的<b>「说到我们家那个喔……真的是」</b>。先把一个让你受不了的人或东西点出来，后面接着数落它。整句的重点是<b>不满、傻眼、拿它没办法</b>。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接加ときたら，前面通常是人或东西。<br><span class='gd-pair'><span class='gd-jp'>うちの息子</span> → <span class='gd-jp'>うちの息子ときたら</span></span>（说到我家儿子）<br><span class='gd-pair'><span class='gd-jp'>このパソコン</span> → <span class='gd-jp'>このパソコンときたら</span></span>（说到这台电脑）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>数落身边的人</span>最常用在家人、同事、主管这些跟你很近、让你很头痛的人。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの息子ときたら、ゲームばかりしている。</span>（说到我家儿子，整天只会打电动）</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長ときたら、会議のたびに話が長い。</span>（说到我们部长，每次开会都讲超久）</div><div class='gd-sec'><span class='gd-tag'>抱怨东西</span>不好用的东西也可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>このパソコンときたら、すぐ固まるんだから。</span>（这台电脑真是的，动不动就当机）</div><div class='gd-sec'><span class='gd-tag'>骂自己</span>拿自己开刀也很自然。</div><div class='gd-ex-line'>・<span class='gd-jp'>私ときたら、また傘を電車に忘れてきた。</span>（我真是的，又把伞忘在电车上了）</div><div class='gd-sec'><span class='gd-tag'>后面不讲完</span>口语里常把抱怨的内容省略，只说到ときたら，靠语气让人听出不满。</div><div class='gd-ex-line'>・<span class='gd-jp'>まったく、うちの主人ときたら……</span>（真是的，我家那口子喔……）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它是<b>跟第三者</b>数落某人某物用的，不能当面喊对方。对着妈妈本人说「お母さんときたら！」是错的。<br>・后面接的是描述跟抱怨，不接「请～」「～吧」这种要求或决定。像<span class='gd-jp'>うちの部長ときたら、早く帰ってください</span>这样接一个请求，就不对。<br>・基本上是负面的，不要拿来夸人。<span class='gd-jp'>うちの息子ときたら、頭がいい</span>听起来会很怪。<br>・语感偏口语、闲聊，正式文章或报告里不太用。<br>・口语有时会听到<span class='gd-jp'>夏ときたら、やっぱりビールでしょ。</span>（说到夏天，当然就是啤酒啦）这种「说到A就想到B」的讲法，那是另一种用法，不是抱怨，听到别搞混。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ったら</b>：也能抱怨，但语气比较轻，常带点「真拿你没办法」的亲暱感，而且<b>可以当面叫对方</b>。<br><span class='gd-jp'>もう、お母さんったら！</span>（唉唷，妈你真是的！）：对着妈妈讲，可以<br><b>ときたら</b>：批评比较重，只能跟别人讲那个人的事。<br><span class='gd-jp'>うちの母ときたら、人の話を全然聞かない。</span>（说到我妈，完全不听人讲话）：跟朋友抱怨</div><div class='gd-sec'><b>に至っては</b>：先讲一群人或一堆事，再挑出<b>最夸张的那一个</b>。<br><span class='gd-jp'>みんな遅刻したが、田中さんに至っては来なかった。</span>（大家都迟到，田中更夸张，根本没来）<br><b>ときたら</b>不用跟别人比，就是直接点名某个人来数落。</div><div class='gd-warn'>判断小诀窍：当面喊「你真是的」用ったら；跟别人数落某个人用ときたら；从一群里挑最夸张的用に至っては。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>常跟「<span class='gd-jp'>まったく</span>」「<span class='gd-jp'>〜んだから</span>」一起出现，抱怨感更强：<span class='gd-jp'>うちの夫ときたら、まったく何もしないんだから。</span>（说到我老公，真的是什么都不做）</div>","n1-46":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜にあって」就是中文书面语的<b>「身处～之中」「身为～」</b>。前面放一个特别的时代、处境或身分，后面讲在这种环境下的状态、做法，或应该怎么做。新闻、演讲、文章常见，日常聊天几乎不讲。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>只接名词：名词＋にあって<br><span class='gd-pair'><span class='gd-jp'>非常時</span> → <span class='gd-jp'>非常時にあって</span></span>（在这种非常时期）<br><span class='gd-pair'><span class='gd-jp'>現代</span> → <span class='gd-jp'>現代にあって</span></span>（身处现代）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>特别的时代、状况</span>非常时期、不景气、资讯爆炸的年代这类。</div><div class='gd-ex-line'>・<span class='gd-jp'>この非常時にあって、リーダーは冷静であるべきだ。</span>（在这种非常时期，领导者应该冷静）</div><div class='gd-ex-line'>・<span class='gd-jp'>情報があふれる現代にあって、正しい情報を選ぶ力が必要だ。</span>（身处资讯泛滥的现代，需要分辨正确资讯的能力）</div><div class='gd-sec'><span class='gd-tag'>身分、立场</span>常写成「〜という立場にあって」。</div><div class='gd-ex-line'>・<span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（身为社长，不能随便乱说话）</div><div class='gd-sec'><span class='gd-tag'>身在某处</span>多半是「异国」「战场」这种不寻常的地方，带点文学味。</div><div class='gd-ex-line'>・<span class='gd-jp'>異国にあって、家族からの手紙が何よりの支えだった。</span>（身在异乡，家人的信是我最大的支柱）</div><div class='gd-h'>最常听到的两种变身</div><div class='gd-sec'><span class='gd-tag'>にあっても</span>加了「も」，变成<b>「即使身处～，也…」</b>，后面接「还是不放弃、还是很坚强」这类。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな苦境にあっても、彼女は笑顔を忘れなかった。</span>（不管身处多艰难的处境，她都没忘记微笑）</div><div class='gd-sec'><span class='gd-tag'>にあっては</span>加了「は」，强调<b>「在这种情况下，就（只能）…」</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>この不況下にあっては、どの会社も節約せざるを得ない。</span>（在这种不景气之下，每家公司都不得不节省）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・只接名词。想用动词，就先把它变成名词，或改说「〜という状況にあって」。<br>・前面要是<b>值得一提的特殊环境或身分</b>。「月曜日にあって」「普通の日にあって」这种平凡的时间很怪。<br>・很硬的书面语。跟朋友聊天说「忙しい中」「〜なのに」就好，讲にあって会像在念新闻稿。<br>・别跟单纯的「在哪里」搞混：<span class='gd-jp'>その店は駅前にあって便利だ。</span>（那家店在车站前，很方便）这里的あって只是「位在」的意思，不是这个文法。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>にあたって</b>（只差一个字，最常看错）＝<b>要做某件事之前、之际</b>，可以接动词。<br><span class='gd-jp'>社長に就任するにあたって、一言ご挨拶申し上げます。</span>（在就任社长之际，跟各位说几句话）<br><span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（身为社长，不能随便乱说话）<br>前一句重点是「就任这个时间点」，后一句是「一直身处社长这个位置」。</div><div class='gd-sec'><b>とあって</b>＝<b>因为是～，所以</b>（讲原因）。<br><span class='gd-jp'>不況とあって、就職が厳しい。</span>（因为不景气，找工作很难）<br><span class='gd-jp'>不況にあって、この会社は売り上げを伸ばしている。</span>（身处不景气之中，这家公司营收还在成长）<br>とあって是「因为这样所以那样」；にあって是「人在这个环境里，怎么表现」。</div><div class='gd-warn'>判断小诀窍：「身处～／身为～」用にあって，「要做～之际」用にあたって，「因为是～」用とあって。</div>","n1-48":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「～ともなれば」就是中文的<b>「都已经是～了，当然就…」</b>。前面放一个<b>比平常高一阶</b>的身分、年纪或时期，后面讲「到了这个层级，自然就会这样」。就像台湾人会说「人家都当到社长了，放假还要接工作电话很正常啊」，就是这种口气。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>身分、年纪升级</span>当上某个职位、到了某个年纪，责任和别人的期待就跟着变了。</div><div class='gd-ex-line'>・<span class='gd-jp'>プロともなれば、これくらいは当然できる。</span>（都是职业的了，这种程度当然做得到）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長ともなれば、休みの日も仕事の電話が来る。</span>（当到社长，连放假都会接到工作电话）</div><div class='gd-sec'><span class='gd-tag'>时期到了</span>到了某个特别的季节或日子，周围的状况自然就不一样了。</div><div class='gd-ex-line'>・<span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span>（一到 12 月，街上到处都是圣诞气氛）</div><div class='gd-sec'><span class='gd-tag'>真的要做大事</span>前面接动词，意思是「如果真的要做到这一步」，这时候「假如」的味道比较明显。</div><div class='gd-ex-line'>・<span class='gd-jp'>海外に引っ越すともなれば、準備することが山ほどある。</span>（如果真的要搬到国外，要准备的事可多了）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋ともなれば：<span class='gd-pair'><span class='gd-jp'>大学生</span> → <span class='gd-jp'>大学生ともなれば</span></span><br>动词辞书形＋ともなれば：<span class='gd-pair'><span class='gd-jp'>結婚する</span> → <span class='gd-jp'>結婚するともなれば</span></span><br>后面常接<span class='gd-jp'>当然</span>、<span class='gd-jp'>～なければならない</span>、<span class='gd-jp'>～ものだ</span>这种「理所当然」「本来就该」的说法。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面要让人觉得<b>已经到了不一样的层级</b>。<span class='gd-jp'>小学生ともなれば</span>可以，因为是跟幼稚园比，已经升了一级；随便放一个普通的词，句子会很怪。<br>・后面讲的是「自然会这样」，<b>不放自己的意志或请求</b>。想说「当上社长的话我想更努力」，不能说<span class='gd-jp'>社長ともなれば、もっと頑張りたい</span>，要说<span class='gd-jp'>社長になったら、もっと頑張りたい。</span><br>・语气偏正式，新闻、文章、演讲比较常见。平常聊天多半说<span class='gd-jp'>～になると</span>或<span class='gd-jp'>～となると</span>。<br>・别跟<span class='gd-jp'>となれば</span>搞混：少了那个<span class='gd-jp'>も</span>，就只是单纯的「如果是那样的话」，没有「都到这个层级了」的强调。例：<span class='gd-jp'>明日も雨となれば、試合は中止だ。</span>（如果明天也下雨，比赛就取消）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ともなると</b>：意思几乎一样，考试时两个大多可以互换。<br><span class='gd-jp'>12月ともなると、街はクリスマス一色になる。</span><br><span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span><br>两句都对。硬要分的话，<span class='gd-jp'>ともなれば</span>因为有<span class='gd-jp'>ば</span>，「假如真的到了那一步」的味道稍微多一点。</div><div class='gd-sec'><b>とあれば</b>：长得很像，方向却相反。它是「既然是为了～／既然是～的要求」，后面常接<b>自己愿意做、只好去做</b>的事。<br><span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（既然是社长的命令，只能照做）<br><span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（当到社长，责任自然也变重）</div><div class='gd-warn'>判断小诀窍：前面是「升了一级」，后面讲「自然会这样」，就用ともなれば／ともなると；前面是「特别的理由」，后面讲「那我就去做」，就用とあれば。</div>","n1-49":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'><span class='gd-jp'>ともなく</span>有两种用法，核心都是<b>「说不清楚」</b>。<br>一种是<b>动作没有目的</b>，像中文的「有一搭没一搭地看」：电视开着，你眼睛有在看，但根本没在看什么。<br>另一种是<b>说不出来源</b>：「不知道从哪里」「不知道是谁先开始的」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>不经意地做</span>没打算要做，却自然而然在做。最大的特征是<b>前后放同一个动词</b>，或意思很接近的动词。</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなく窓の外を見ていた。</span>（我没特别要看什么，就这样望着窗外）</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くともなく隣の席の話を聞いていた。</span>（我不是故意要听，隔壁桌的话还是传进耳朵里）</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなくテレビを眺めていたら、見覚えのある街が映った。</span>（我有一搭没一搭地看着电视，结果画面上出现了眼熟的街景）</div><div class='gd-sec'><span class='gd-tag'>说不出是谁、哪里</span>前面放「どこ、誰、いつ」这种问句用的字。后面常会带<span class='gd-jp'>から</span>、<span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>どこからともなく、いい匂いがしてきた。</span>（不知道从哪里飘来一股香味）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰からともなく拍手が起こった。</span>（不知道是谁先开始的，大家都鼓起掌来）</div><div class='gd-ex-line'>・<span class='gd-jp'>男はどこへともなく歩いていった。</span>（那个男人不知道往哪里走掉了）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にともなく「ありがとう」とつぶやいた。</span>（没有对着谁，只是小声说了句「谢谢」）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>动词</b>：用原本字典上的样子（辞书形）加<span class='gd-jp'>ともなく</span>，后面再接同一个动词。<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るともなく見る</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くともなく聞く</span></span><br><b>问句用的字</b>：「どこ、誰、いつ」加上助词，再加<span class='gd-jp'>ともなく</span>。<br><span class='gd-pair'><span class='gd-jp'>どこから</span> → <span class='gd-jp'>どこからともなく</span></span><span class='gd-pair'><span class='gd-jp'>誰から</span> → <span class='gd-jp'>誰からともなく</span></span></div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・动词要用辞书形：<span class='gd-jp'>見るともなく</span>。不能把ます拿掉接成「見ともなく」，也不能接过去形「見たともなく」。<br>・能这样用的动词很有限，几乎都是<span class='gd-jp'>見る</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>言う</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>待つ</span>这类眼睛、耳朵、嘴巴、脑袋会自然做的事。不要随便套到别的动词上。<br>・<span class='gd-jp'>どこからともなく</span>和<span class='gd-jp'>どことなく</span>只差一点点，意思不一样。<span class='gd-jp'>どことなく</span>是「总觉得哪里有点～」，讲的是感觉：<span class='gd-jp'>彼はどことなく父に似ている。</span>（他说不上哪里，就是有点像我爸）。要讲「从哪里来」，请用<span class='gd-jp'>どこからともなく</span>。<br>・「不经意」不是「没在做」。<span class='gd-jp'>見るともなく見る</span>还是有在看，只是没有目的。<br>・这是偏书面的说法，小说、散文很常见。日常聊天多半说<span class='gd-jp'>なんとなく</span>或<span class='gd-jp'>どこからか</span>。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同级的<b><span class='gd-jp'>ともなると</span></b>（和<span class='gd-jp'>ともなれば</span>意思相同）只差几个字，意思完全不同。它的意思是：一到了某个程度或立场，<b>自然就会～</b>。前面多半是名词，也可以接动词辞书形。<br>用同一个「一个人住」的情境比比看：<br><b><span class='gd-jp'>ともなく</span></b>（不经意）：<span class='gd-jp'>一人の部屋で、見るともなくテレビを見ていた。</span>（一个人在房间里，有一搭没一搭地看着电视）<br><b><span class='gd-jp'>ともなく</span></b>（说不出来源）：<span class='gd-jp'>夜中、どこからともなく猫の鳴き声が聞こえてきた。</span>（半夜不知道从哪里传来猫叫声）<br><b><span class='gd-jp'>ともなると</span></b>（名词）：<span class='gd-jp'>夜中ともなると、この辺りはすっかり静かになる。</span>（一到半夜，这一带就变得非常安静）<br><b><span class='gd-jp'>ともなると</span></b>（动词）：<span class='gd-jp'>一人暮らしをするともなると、家事も全部自分でやらなければならない。</span>（一旦要一个人住，家事就全部得自己来）</div><div class='gd-warn'>判断小诀窍：<br>・<span class='gd-jp'>ともなく</span>通常长成「同一个动词＋ともなく＋同一个动词」或「どこから／誰から＋ともなく」，意思是不经意、说不出是谁或哪里。<br>・<span class='gd-jp'>ともなると</span>后面会接「就会～、当然～」，意思是到了那个程度或立场，自然会有某种情况。<br>不要只看前面是名词还是动词，要看整句的形式和意思。</div>","n1-50":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AともBともつかない」就是中文的<b>「说A也不像A，说B也不像B」</b>，像「似笑非笑」「说蓝不蓝、说绿不绿」那种感觉。眼前的东西卡在两者中间，你分不出它到底算哪一边。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>A、B 放<b>名词</b>或<b>动词普通形</b>（辞书形、ている形、ない形这些不加ます的形），后面各加一个「とも」，最后接「つかない」。<br><span class='gd-pair'><span class='gd-jp'>本気</span>＋<span class='gd-jp'>冗談</span> → <span class='gd-jp'>本気とも冗談ともつかない</span></span><br><span class='gd-pair'><span class='gd-jp'>笑っている</span>＋<span class='gd-jp'>泣いている</span> → <span class='gd-jp'>笑っているとも泣いているともつかない</span></span><br>这里的「つかない」是「判断不出来、定不下来」的意思，通常写平假名。后面最常直接接名词，例如表情、声音、口气、回答、颜色。</div><div class='gd-h'>最常听到的两种样子</div><div class='gd-sec'><span class='gd-tag'>ともつかない</span>东西本身就模棱两可，你看了、听了也分不出来。</div><div class='gd-ex-line'>・<span class='gd-jp'>本気とも冗談ともつかない言い方だった。</span>（那种讲法，分不清他是认真还是开玩笑）</div><div class='gd-ex-line'>・<span class='gd-jp'>ため息ともあくびともつかない声が聞こえた。</span>（传来一个分不清是叹气还是打哈欠的声音）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は笑っているとも泣いているともつかない顔をしていた。</span>（她露出一种似笑非笑、像哭又不像哭的表情）</div><div class='gd-sec'><span class='gd-tag'>とも言わない</span>A、B 通常是一正一反，表示对方<b>不表态</b>，有点像中文的「不置可否」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行くとも行かないとも言わない。</span>（他没说要去，也没说不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はいいとも悪いとも言わなかった。</span>（部长没说好，也没说不好）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・「つかない」是指<b>那个东西本身</b>分不出来，用来形容表情、声音、回答这类眼前的东西。单纯「我不知道答案」不要用它：想说「我不知道他会不会来」，要讲<span class='gd-jp'>彼が来るか来ないか分からない</span>。<br>・A 和 B 后面<b>都要</b>加とも。只写一个，或写成「AかBともつかない」都不对。<br>・动词直接接とも，不需要多加「の」：写<span class='gd-jp'>笑っているとも</span>就好，不必写成笑っているのとも。<br>・这是偏书面、小说的写法。平常聊天说<span class='gd-jp'>冗談か本気か分からない</span>就够了。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>AともBとも言わない</b>：两个都<b>没说</b>，态度不明。<br><span class='gd-jp'>彼は賛成とも反対とも言わなかった。</span>（他没说赞成，也没说反对）<br><b>Aと言わずBと言わず</b>：不管是A还是B，<b>全部都</b>是那样。<br><span class='gd-jp'>手と言わず足と言わず泥だらけになった。</span>（手也好、脚也好，全身都是泥）<br>两个都是「A…B…」加上「言わ」，看起来很像，意思却完全不同：一个是「两边都不讲」，一个是「哪里都一样」。</div><div class='gd-sec'><b>〜ともなく</b>也有「とも」，但它只有<b>一格</b>，前面常接疑问词，意思是「说不上是哪里、是谁」。<br><span class='gd-jp'>どこからともなく音楽が聞こえてきた。</span>（不知道从哪里传来了音乐）</div><div class='gd-warn'>判断小诀窍：有两个选项、分不出是哪一个，用ともつかない；两边都不表态，用とも言わない；两个都包含、全部都是，用と言わず；只有一个疑问词「不知道从哪里、不知道是谁」，用ともなく。</div>","n1-51":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜てまで」就是中文的<b>「不惜～也要…」「甚至～也要…」</b>。为了达成某个目的，连平常不会做、代价很大的事都做了。日本人讲这句时，常常带着「有必要做到这样吗？」的口气。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>把动词变成て形，后面加「まで」，再接你真正想达成的目的。<br><span class='gd-pair'><span class='gd-jp'>借金する</span> → <span class='gd-jp'>借金して</span> → <span class='gd-jp'>借金してまで</span></span><br><span class='gd-pair'><span class='gd-jp'>無理をする</span> → <span class='gd-jp'>無理をしてまで</span></span><br><span class='gd-pair'><span class='gd-jp'>嘘をつく</span> → <span class='gd-jp'>嘘をついてまで</span></span><br>整句的骨架是<b>「Aてまで、B」＝为了B，不惜做A</b>。A是你付出的代价，B是你想要的东西。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>不值得</span>后面接「〜必要はない」「〜たくない」，意思是「为了这个做到那种地步，不划算」。这是最常见的用法。</div><div class='gd-ex-line'>・<span class='gd-jp'>借金してまで、ブランド品を買う必要はない。</span>（没必要为了买名牌去借钱）</div><div class='gd-ex-line'>・<span class='gd-jp'>体を壊してまで働きたくない。</span>（我不想为了工作把身体搞坏）</div><div class='gd-sec'><span class='gd-tag'>傻眼、质疑</span>觉得别人付出的代价太夸张，用问句表达。</div><div class='gd-ex-line'>・<span class='gd-jp'>そこまでして行きたいの？</span>（要做到那种地步你也想去？）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を裏切ってまで、出世したかったのか。</span>（你就那么想升官，不惜背叛朋友？）</div><div class='gd-sec'><span class='gd-tag'>单纯说有多拚</span>不一定是批评，也可以只是描述某人付出很多，有时还带点佩服。</div><div class='gd-ex-line'>・<span class='gd-jp'>徹夜してまで並んで、限定スイーツを手に入れた。</span>（不惜熬夜排队，终于买到了限定甜点）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は自分の給料を減らしてまで、社員を守った。</span>（社长不惜减自己的薪水，也要保住员工）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>顺序别放反</b>：てまで前面是「代价」，后面才是「目的」。<span class='gd-jp'>借金してまで買う</span>是「为了买而借钱」。如果写成「買ってまで借金する」，就变成「为了借钱而去买」，意思完全不通。<br>・前面要放<b>不寻常、牺牲很大</b>的事。轻松、本来就会做的事放进去，句子就没有「不惜」的感觉，听起来很怪。<br>・<span class='gd-jp'>そこまでして</span>是口语很常用的固定说法，意思是「做到那种地步」，跟てまで是同一种感觉。要注意它是在说<b>代价太大</b>，不是「都已经这种状况了」。<br>・名词要先加「する」或「をする」变成动词，才能接てまで：<span class='gd-jp'>借金してまで</span>、<span class='gd-jp'>無理をしてまで</span>、<span class='gd-jp'>家族を犠牲にしてまで</span>。不能直接写「借金まで」，那会变成「连借钱都…」，是另一个意思。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>都是动词后面加「まで」，只差在动词变成什么形，意思就完全不同：<br><b>辞书形＋まで</b>＝直到～<br>・<span class='gd-jp'>彼が来るまで待った。</span>（我一直等到他来）<br><b>て形＋まで</b>＝不惜～也要<br>・<span class='gd-jp'>3時間も待ってまで、彼に会いたかった。</span>（我不惜等三个小时，也想见到他）<br><b>辞书形＋までだ（放句尾）</b>＝大不了就～<br>・<span class='gd-jp'>彼が来ないなら、一人で行くまでだ。</span>（他不来的话，大不了我自己去）</div><div class='gd-warn'>判断小诀窍：まで前面是<b>て形</b>就是「不惜」；是<b>辞书形</b>而且句子还没结束，就是「直到」；<b>までだ</b>放在句尾，就是「大不了／只是」。</div>","n1-54":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜かろう」就是「〜いだろう」的<b>老派书面版</b>，意思是「大概～吧」「想必～吧」。<span class='gd-jp'>難しいだろう</span>写成<span class='gd-jp'>難しかろう</span>，意思不变，只是听起来像社论、小说，或是古装剧里的老爷爷在说话。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>只能接い形容词</b>：把最后的「い」拿掉，加「かろう」。<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → い拿掉 → <span class='gd-jp'>難しかろう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒かろう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろう</span></span><br><b>两个要特别记</b>：<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろう</span></span>（从<span class='gd-jp'>よい</span>变来的）<br><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかろう</span></span><br>「〜たい」的变化跟い形容词一样，所以也能接：<span class='gd-pair'><span class='gd-jp'>帰りたい</span> → <span class='gd-jp'>帰りたかろう</span></span>（大概很想回去吧）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>书面推测</span>文章、评论里推测情况，常跟<span class='gd-jp'>さぞ</span>（想必）一起出现。</div><div class='gd-ex-line'>・<span class='gd-jp'>山の上はさぞ寒かろう。</span>（山上想必很冷吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>最初は苦しかろうが、すぐに慣れる。</span>（一开始大概会很辛苦，但很快就会习惯）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>ではなかろうか</span>＝「是不是～呢」，论文、社论超常见，是比较委婉的主张。</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には無理があるのではなかろうか。</span>（这个计划是不是有点勉强呢）</div><div class='gd-sec'><span class='gd-tag'>よかろう</span>长辈或上司说「好吧，可以」，有种上对下、勉强答应的感觉。</div><div class='gd-ex-line'>・<span class='gd-jp'>まあ、よかろう。今回だけは許してやる。</span>（嗯，好吧。这次就饶了你）</div><div class='gd-sec'><span class='gd-tag'>固定说法</span><span class='gd-jp'>安かろう悪かろう</span>＝便宜没好货。</div><div class='gd-ex-line'>・<span class='gd-jp'>安かろう悪かろうの時代は終わった。</span>（便宜没好货的时代已经过去了）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・な形容词和名词<b>不能</b>接かろう：<span class='gd-jp'>静かかろう</span>是错的，要说<span class='gd-jp'>静かだろう</span>或<span class='gd-jp'>静かであろう</span>；名词也一样，要用<span class='gd-jp'>学生だろう</span>或<span class='gd-jp'>学生であろう</span>。<br>・动词也不能接：要说<span class='gd-jp'>行くだろう</span>或<span class='gd-jp'>行くであろう</span>。<br>・<span class='gd-jp'>いい</span>要变成<span class='gd-jp'>よかろう</span>，没有「いかろう」这种说法。<br>・「ろう」要拉长音念成ろー。<br>・跟朋友聊天说<span class='gd-jp'>暑かろう</span>会很像在演古装剧，平常讲<span class='gd-jp'>暑いだろう</span>就好。<br>・<span class='gd-jp'>よかろう</span>是上对下的口气，对上司、老师说会很失礼。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>「〜かろうが／〜かろうと」有两种意思，要看句子怎么搭：<br><b>大概～，但…</b>（推测再转折）：<span class='gd-jp'>その試験は難しかろうが、準備すれば突破できる。</span>（那场考试大概很难，但只要准备就能过）<br><b>不管～都…</b>（就是<span class='gd-jp'>〜ようが／〜ようと</span>的い形容词版）：<span class='gd-jp'>高かろうが安かろうが、必要なものは買う。</span>（不管贵还是便宜，需要的东西就买）<br><span class='gd-jp'>どんなに辛かろうと、最後までやり抜く。</span>（不管多辛苦，都要坚持到最后）</div><div class='gd-warn'>判断小诀窍：前面有「どんなに」「いくら」，或是两个成对出现（高かろうが安かろうが）→「不管～都」；只有一个，后面接「但…」→「大概～，但」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>动词、名词版的「不管～」就是<span class='gd-jp'>〜ようが／〜ようと</span>：<span class='gd-jp'>雨が降ろうが、試合は行われる。</span>（就算下雨，比赛还是照常举行）</div>","n1-58":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とばかりに」就是中文的<b>「一副『～』的样子」</b>。对方嘴巴没讲，可是动作、表情明显在说某句话，你就把那句<b>心里的台词</b>放在前面，后面接他做的动作。<br>像课长一直看手表，嘴巴没讲，但大家都看得出来他在说「快下班吧」，这时就用它。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>描写别人的样子</span>把对方动作背后的「台词」写出来，小说、报导、叙述场面最常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>「早く帰れ」とばかりに、課長は時計をちらちら見た。</span>（课长一直瞄手表，一副「快回去」的样子）</div><div class='gd-ex-line'>・<span class='gd-jp'>「遊ぼう」とばかりに、犬がボールをくわえて走ってきた。</span>（狗咬着球跑过来，一副「来玩嘛」的样子）</div><div class='gd-ex-line'>・<span class='gd-jp'>「待ってました」とばかりに、彼は勢いよく手を挙げた。</span>（他一副「就等这个了」的样子，用力举起手）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放的是<b>一句台词</b>，所以台词长什么样都可以：命令的口气（<span class='gd-jp'>帰れ</span>）、揪人的口气（<span class='gd-jp'>遊ぼう</span>）、ます形（<span class='gd-jp'>待ってました</span>）、一个单字或感叹都行。常会加上「」，让人一眼看出是台词。<br>后面要接名词时改成<b>とばかりの</b>：<br>・<span class='gd-jp'>「もう帰れ」とばかりの冷たい態度だった。</span>（摆出一副「快滚」的冷淡态度）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>ここぞとばかりに</span><span class='gd-jp'>ここぞ</span>＝「就是这里、就是现在」，整句变成「逮到机会似的、趁机猛～」，非常常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議で、彼はここぞとばかりに不満を言い始めた。</span>（开会时，他逮到机会似的开始大吐苦水）</div><div class='gd-sec'><span class='gd-tag'>今だとばかりに</span>「就是现在！」看准时机马上行动。</div><div class='gd-ex-line'>・<span class='gd-jp'>相手が転んだ瞬間、今だとばかりに走り出した。</span>（对手一跌倒，他就一副「就是现在」的样子冲了出去）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・这是<b>从旁边看别人</b>的说法，通常不拿来讲自己。自己心里想什么你自己最清楚，不需要「看起来像在说」。<br>・前面的话<b>其实没说出口</b>。如果对方真的讲了，就直接用「〜と言って」。<br>・这里的ばかり不是「只有」的意思，别翻成「只是～」。<br>・它不是只能接普通形，前面放命令、ます形、单字都可以，因为它就是在引用一句话。<br>・多半用在书面、描写场面；平常聊天比较少这样讲。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>とばかりに</b>＝前面放一句<b>台词</b>：「一副『～』的样子」<br><b>んばかりに</b>＝前面放一个<b>快要发生的动作</b>：「简直快要～」<br>同一个情境：小孩拿到礼物超开心。</div><div class='gd-ex-line'>・<span class='gd-jp'>「やった」とばかりに、子どもは両手を上げた。</span>（小孩举起双手，一副「太好了」的样子）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもは飛び上がらんばかりに喜んだ。</span>（小孩高兴得简直快跳起来）</div><div class='gd-sec'>んばかりに的接法：先变成ない形，把「ない」拿掉，加「ん」。<br><span class='gd-pair'><span class='gd-jp'>飛び上がる</span> → <span class='gd-jp'>飛び上がらない</span> → <span class='gd-jp'>飛び上がらんばかりに</span></span><br><span class='gd-pair'><span class='gd-jp'>泣き出す</span> → <span class='gd-jp'>泣き出さない</span> → <span class='gd-jp'>泣き出さんばかりに</span></span><br>※<b>する要变成「せん」</b>，不是「しん」：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかりに</span></span>（例：<span class='gd-jp'>今にも爆発せんばかりに</span>）<br>另外，<span class='gd-jp'>「帰れ」と言わんばかりに</span>（简直就要说出「回去」）的意思跟<span class='gd-jp'>「帰れ」とばかりに</span>几乎一样，可以互换。</div><div class='gd-warn'>判断小诀窍：前面是一句「台词」就用とばかりに；前面是「差一点就要做出来的动作」就用んばかりに。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样是在描写「样子」，可以接着看<span class='gd-jp'>〜んばかりに</span>（简直快要～），两个一起记最不容易混。</div>","n1-60":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「Aかたがた」就是中文书信里的<b>「兼致谢意」「顺道问候」</b>。去拜访或写信给某人时，顺便带上另一个目的，例如道谢、报告近况、问候。它是很正式的说法，常出现在拜访长辈、客户，或商务书信里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面放<b>名词</b>，而且多半是「动作」的名词，例如<span class='gd-jp'>お礼</span>（道谢）、<span class='gd-jp'>ご挨拶</span>（问候）、<span class='gd-jp'>ご報告</span>（报告）、<span class='gd-jp'>お見舞い</span>（探病）、<span class='gd-jp'>散歩</span>（散步）。<br><span class='gd-pair'><span class='gd-jp'>お礼</span> → <span class='gd-jp'>お礼かたがた</span></span><span class='gd-pair'><span class='gd-jp'>ご報告</span> → <span class='gd-jp'>ご報告かたがた</span></span><br>后面接的通常是「去拜访」或「写信、致词」这类动作，最常看到<span class='gd-jp'>伺う</span>、<span class='gd-jp'>お邪魔する</span>、<span class='gd-jp'>申し上げる</span>。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>登门拜访</span>说明自己今天来的目的。</div><div class='gd-ex-line'>・<span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>（今天来向您问候，也为前几天的事道谢）</div><div class='gd-ex-line'>・<span class='gd-jp'>近くまで来ましたので、ご挨拶かたがたお邪魔しました。</span>（刚好到附近，就顺道过来跟您打声招呼）</div><div class='gd-sec'><span class='gd-tag'>书信</span>商务信、问候信的结尾很常用，几乎是固定句。</div><div class='gd-ex-line'>・<span class='gd-jp'>略儀ながら書中をもちまして、お礼かたがたご挨拶申し上げます。</span>（请容我以书信代替，在此向您致谢并问候）</div><div class='gd-ex-line'>・<span class='gd-jp'>転勤のご報告かたがた、お手紙を差し上げます。</span>（写这封信，也是想向您报告我调职的消息）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面接名词，不接动词辞书形：要说<span class='gd-jp'>お礼かたがた</span>，不说<span class='gd-jp'>お礼を言うかたがた</span>。<br>・中文的「顺便」听起来好像那件事不重要，但日文的かたがた没有这个意思，道谢跟问候都是真心的目的。用<span class='gd-jp'>お礼かたがた</span>不会失礼，反而很得体。<br>・它很正式，后面常搭<span class='gd-jp'>伺う</span>、<span class='gd-jp'>申し上げる</span>这类谦虚说法。跟朋友讲「我顺便去超商」不会用它。<br>・<span class='gd-jp'>ご来場の方々</span>、<span class='gd-jp'>関係者の方々</span>里的「<span class='gd-jp'>方々</span>（かたがた）」意思是「各位」，只是发音一样，跟这个文法无关。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>かたがた</b>＝正式场合，拜访或写信时<b>兼带另一个目的</b>：<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺いました。</span>（去老师家拜访，也是去道谢）<br><b>がてら</b>＝日常口语，<b>出门做A，顺路做B</b>：<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（出去散步，顺便买了面包）<br><b>かたわら</b>＝长时间<b>一边做本业，一边做另一件事</b>，跟「顺便」没关系：<br><span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span>（他一边上班，一边写小说）</div><div class='gd-warn'>判断小诀窍：正式拜访、写信时「兼表谢意、顺道问候」用かたがた；日常出门顺路做点事用がてら；长期身兼两件事用かたわら。</div>","n1-61":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AかたわらB」就是<b>「在做A（本业）之余，还兼做B」</b>，有点像现在说的「斜杠」。<span class='gd-jp'>かたわら</span>本来的意思是「旁边」：主要的事摆中间，旁边还兼着另一件事。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>长期兼着做</span>讲一个人的生活或工作状态：本业是什么，另外还长期在做什么。常出现在人物介绍、报导、自我介绍的文章里。</div><div class='gd-ex-line'>・<span class='gd-jp'>会社に勤めるかたわら、週末は小説を書いている。</span>（在公司上班之余，周末都在写小说）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は大学で教えるかたわら、翻訳の仕事もしている。</span>（她在大学教书之外，也有在做翻译）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のかたわら、日本語の勉強を続けている。</span>（工作之余，一直持续在学日文）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词：辞书形（字典里的原形）＋かたわら<br><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働くかたわら</span></span><span class='gd-pair'><span class='gd-jp'>店を経営する</span> → <span class='gd-jp'>店を経営するかたわら</span></span><br>名词：名词＋の＋かたわら<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のかたわら</span></span><span class='gd-pair'><span class='gd-jp'>育児</span> → <span class='gd-jp'>育児のかたわら</span></span><br>名词通常是「工作、研究、育儿」这种本身就代表一件事的词。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它<b>不是</b>「同一个时间手上一边做这个、一边做那个」。<span class='gd-jp'>音楽を聞くかたわら勉強する</span>是错的，这种要用<span class='gd-jp'>聞きながら</span>。<br>・两件事都是<b>持续一段时间</b>的，所以后面很常配「〜ている」。只发生一次的事不适合。<br>・前面放<b>主要的</b>那件，后面放兼做的那件，不要放反。<br>・前面不接た形：<span class='gd-jp'>勤めたかたわら</span>是错的，一律用辞书形。<br>・这是书面语，跟朋友聊天很少讲，口语通常说<span class='gd-jp'>仕事しながら</span>或<span class='gd-jp'>本業のほかに</span>。<br>・看到<span class='gd-jp'>母のかたわらで</span>这种「名词のかたわらで」，大多是字面的「在～旁边」，不是这个文法。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ながら</b>＝同一个时间，手上同时做两件事：<br><span class='gd-jp'>音楽を聞きながら勉強する。</span>（边听音乐边念书）<br><b>かたわら</b>＝长期两种身分或两份事情：<br><span class='gd-jp'>会社で働くかたわら、夜間の大学に通っている。</span>（白天上班之余，晚上还去念夜间大学）<br><b>がてら</b>＝这一趟出门，顺便兼办另一件事，是短时间、一次性的：<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>（出去散散步，顺便把面包买回来了）<br><b>かたがた</b>＝意思跟がてら接近，但更正式，多用在拜访、道谢、问候。后面是实际的行动，前面是同时兼带的目的：<br><span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>（兼表前几天的谢意，前来拜访问候您）</div><div class='gd-warn'>判断小诀窍：讲一个人长期兼着两件事，用かたわら；这一趟出门兼办两件事，用がてら（正式场合用かたがた）；手上同一时间做两件事，用ながら。</div>","n1-65":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜いかん」就是中文公文里的<b>「视～而定」「端看～」</b>。汉字写作中文的「如何」两个字，但现在多半直接写平假名<span class='gd-jp'>いかん</span>。意思是：结果怎么样，要看前面那件事的状况。很硬、很正式，新闻、公告、合约、主管训话才会出现。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>只接<b>名词</b>，中间的「の」可加可不加，不加比较常见。<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力いかん</span></span>（看努力的程度）<br><span class='gd-pair'><span class='gd-jp'>試験の結果</span> → <span class='gd-jp'>試験の結果いかん</span></span>（看考试结果）<br>前面的名词要是<b>会有好有坏、有高有低</b>的东西，例如：<span class='gd-jp'>結果</span>、<span class='gd-jp'>努力</span>、<span class='gd-jp'>態度</span>、<span class='gd-jp'>対応</span>、<span class='gd-jp'>天候</span>、<span class='gd-jp'>返答</span>、<span class='gd-jp'>内容</span>。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>いかんだ／いかんにかかっている</span>放在句尾，「就看～了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できるかどうかは、本人の努力いかんだ。</span>（能不能考上，就看本人努不努力）</div><div class='gd-ex-line'>・<span class='gd-jp'>今期の業績は、チームの努力いかんにかかっている。</span>（本期业绩取决于团队的努力）</div><div class='gd-sec'><span class='gd-tag'>いかんで／いかんによって</span>放在句中，「依～而决定、而改变」。</div><div class='gd-ex-line'>・<span class='gd-jp'>参加費は人数いかんで変わります。</span>（参加费会依人数而有所不同）</div><div class='gd-sec'><span class='gd-tag'>いかんでは／いかんによっては</span>多了一个「は」，意思变成「视情况，<b>甚至有可能</b>～」，后面通常接一个特别的、常常是不太好的结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>天候いかんでは、試合が中止になることもあります。</span>（视天候状况，比赛也有可能取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の対応いかんでは、訴訟も考えています。</span>（看公司怎么处理，我们也考虑提告）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・念<b>いかん</b>。同样是「如何」两个字，在<span class='gd-jp'>如何ですか</span>里念いかが，别混在一起。<br>・不能直接接动词或形容词：说「看你努不努力」要写<span class='gd-jp'>努力いかんで</span>，不能写成「頑張るいかんで」。<br>・前面要是有变数的名词，像「明日」这种没有好坏高低可言的词就不能用。<br>・太正式了，跟朋友聊天说「天気いかんで決めよう」会很怪，口语请用<span class='gd-jp'>天気次第で決めよう</span>或<span class='gd-jp'>天気によって決めよう</span>。<br>・口语里单独一句<span class='gd-jp'>それはいかん</span>是「那可不行」，是另一个词，跟这个文法无关。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>次第</b>（N2）＝意思几乎一样，但口语、书面都能用，比较轻松：<br><span class='gd-jp'>結果次第で、計画を変えるかもしれない。</span>（看结果，计划可能会改）<br><b>いかん</b>＝同样的意思，换成公文、报告的口气：<br><span class='gd-jp'>結果いかんでは、計画を変更することもあり得る。</span>（视结果而定，计划亦可能变更）<br><b>いかんによらず／いかんにかかわらず</b>（n1-66）＝意思相反，「<b>不管</b>～怎么样都一样」：<br><span class='gd-jp'>理由のいかんにかかわらず、返金はいたしません。</span>（无论理由为何，恕不退款）</div><div class='gd-warn'>判断小诀窍：いかん后面接「で・によって・だ・にかかっている」，是「<b>要看它</b>」；接「によらず・にかかわらず・を問わず」，是「<b>不管它</b>」。想讲得轻松一点，就把いかん换成次第。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>接着学 n1-66 的<span class='gd-jp'>いかんによらず</span>、<span class='gd-jp'>いかんにかかわらず</span>，还有公告上很常看到的<span class='gd-jp'>理由のいかんを問わず</span>（不问理由）。</div>","n1-66":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜いかんによらず／いかんにかかわらず」就是中文公文里的<b>「不论～如何，一律……」</b>。前面放一个可能有各种状况的东西（理由、结果、天气），后面讲的结论<b>不会因此改变</b>。你在公告、合约、退票规定上最常看到它，平常聊天几乎不用。</div><div class='gd-h'>先拆开来看</div><div class='gd-sec'><span class='gd-jp'>いかん</span>写成汉字是<span class='gd-jp'>如何</span>，意思是「内容、状况怎么样」。<br><span class='gd-jp'>によらず</span>＝不依照、不取决于；<span class='gd-jp'>にかかわらず</span>＝跟～没关系。<br>两个意思一样，都是「不管～怎么样」。另外还有一个也很常见的说法：<span class='gd-jp'>いかんを問わず</span>（不问～如何）。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋の＋いかんによらず／いかんにかかわらず<br><span class='gd-pair'><span class='gd-jp'>理由</span> → <span class='gd-jp'>理由のいかんによらず</span></span><span class='gd-pair'><span class='gd-jp'>天候</span> → <span class='gd-jp'>天候のいかんにかかわらず</span></span><br>前面的名词要是<b>会有好几种可能</b>的东西，例如<span class='gd-jp'>理由</span>、<span class='gd-jp'>結果</span>、<span class='gd-jp'>事情</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>天候</span>。<br>正式文件里有时会把「の」省掉，写成<span class='gd-jp'>理由いかんにかかわらず</span>。你看得懂就好，自己写的时候先用有「の」的版本。</div><div class='gd-h'>最常看到的样子</div><div class='gd-sec'><span class='gd-tag'>规定・公告</span>店家或公司在讲「没有例外」。</div><div class='gd-ex-line'>・<span class='gd-jp'>理由のいかんを問わず、購入後のキャンセルはできません。</span>（不论理由为何，购买后都不能取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>天候のいかんにかかわらず、イベントは予定通り開催されます。</span>（不论天气如何，活动都会照常举行）</div><div class='gd-sec'><span class='gd-tag'>资格・条件</span>表示大家一视同仁。</div><div class='gd-ex-line'>・<span class='gd-jp'>国籍のいかんによらず、どなたでも応募できます。</span>（不论国籍，任何人都可以报名）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面只能接<b>名词</b>，不能直接接动词或形容词：<span class='gd-jp'>行くいかんによらず</span>是错的。<br>・前面要放「有各种状况」的词。<span class='gd-jp'>雨のいかんにかかわらず</span>不通，因为「雨」没有「怎么样」可言，要说<span class='gd-jp'>天候のいかん</span>。<br>・这里的<span class='gd-jp'>如何</span>念<b>いかん</b>。同样的汉字在<span class='gd-jp'>如何ですか</span>念いかが，不要搞混。<br>・非常硬，跟朋友讲会很怪。口语说<span class='gd-jp'>どんな理由でも</span>（不管什么理由）就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>〜いかんで／いかんによっては</b>（N1 的「〜如何」）意思刚好<b>相反</b>：结果<b>要看</b>前面怎么样。<br>・<span class='gd-jp'>面接の結果いかんで、採用が決まります。</span>（录不录取，要看面试结果）<br>・<span class='gd-jp'>面接の結果のいかんにかかわらず、交通費は支給します。</span>（不论面试结果如何，交通费都会发给你）</div><div class='gd-sec'><b>〜にかかわらず</b>（N2）是比较一般的「不管」，不用加いかん，前面也可以放<span class='gd-jp'>天気</span>、<span class='gd-jp'>年齢</span>这类词：<span class='gd-jp'>天気にかかわらず、試合は行われます。</span>（不管天气，比赛照常进行）<br>加上「のいかん」会更正式，更像官方文件的口气。</div><div class='gd-warn'>判断小诀窍：いかん后面接「によらず／にかかわらず／を問わず」，就是「不管」；接「で／によっては」，就是「要看」。</div>","n1-68":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜をもってしても」就是中文的<b>「就连靠～，也还是…」</b>。前面放一个很厉害、照理说应该有用的东西（最新技术、某人的实力），后面说「结果还是不行、还是很难」。重点在<b>「连这么强的都没办法」</b>，用来凸显事情有多难。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>直接接在名词后面：名词＋をもってしても<br><span class='gd-pair'><span class='gd-jp'>最新の技術</span> → <span class='gd-jp'>最新の技術をもってしても</span></span>（就连靠最新的技术）<br><span class='gd-pair'><span class='gd-jp'>彼の実力</span> → <span class='gd-jp'>彼の実力をもってしても</span></span>（就连以他的实力）<br>前面也可以直接放人，意思是「连他那么厉害的人」：<span class='gd-jp'>彼をもってしても</span></div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>技术、科学、方法</span>连目前最好的办法都做不到。</div><div class='gd-ex-line'>・<span class='gd-jp'>今の科学をもってしても、地震を正確に予知することはできない。</span>（就算靠现在的科学，也没办法准确预测地震）</div><div class='gd-sec'><span class='gd-tag'>人的能力</span>连很强的人都觉得难。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力をもってしても、優勝は難しいだろう。</span>（就连以他的实力，要拿冠军恐怕也很难）</div><div class='gd-ex-line'>・<span class='gd-jp'>天才と呼ばれた彼をもってしても、この問題は解けなかった。</span>（就连被称为天才的他，也解不开这道题）</div><div class='gd-sec'><span class='gd-tag'>言语、表达</span>演讲、致词常见的说法，表示感受强烈到讲不出来。</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな言葉をもってしても、この感謝の気持ちは伝えきれません。</span>（不管用什么样的言词，都表达不完我的感谢）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面几乎都是<b>「做不到、很难、还是不够」</b>这种结果，例如<span class='gd-jp'>できない</span>、<span class='gd-jp'>難しい</span>、<span class='gd-jp'>無理だ</span>。后面接「成功了」会整句很怪。<br>・前面要放<b>本来被期待很有用</b>的东西。放普通的东西，例如「用我的铅笔」，就没有「连这都不行」的张力。<br>・这是很正式的书面说法，新闻、论文、演讲常见。平常讲话说<span class='gd-jp'>最新の技術でも</span>（就算是最新技术也…）就好。<br>・它的重点是「靠这个力量去做」，不是「从～的角度来看」。不要翻成「以～来看」。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个「技术」，三种说法结果完全不同：<br><b>をもって</b>＝用、靠（单纯说手段）：<span class='gd-jp'>この技術をもって、問題を解決した。</span>（靠这个技术解决了问题）<br><b>をもってすれば</b>＝只要有～就做得到：<span class='gd-jp'>この技術をもってすれば、問題は解決できる。</span>（只要有这个技术，问题就能解决）<br><b>をもってしても</b>＝就算有～也做不到：<span class='gd-jp'>この技術をもってしても、問題は解決できない。</span>（就算有这个技术，问题也解决不了）<br>另外，<span class='gd-jp'>をもって</span>还有「以此为界」的用法，例如<span class='gd-jp'>本日をもって閉店します。</span>（本店营业到今天为止），这跟をもってしても无关，不要混在一起。</div><div class='gd-warn'>判断小诀窍：看中间那一小段。「すれば」是有它就行，「しても」是有它也不行。</div>","n1-71":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ずにはすまない」就是中文的<b>「不～说不过去」「不～这件事收不了场」</b>。<span class='gd-jp'>すむ</span>（済む）是「事情了结、过得去」，<span class='gd-jp'>すまない</span>就是「过不去」。整句的意思是：照情理、照现在的情况，不做这件事是交代不了的。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>道义上该做</span>做错事、出了包，不道歉、不赔偿、不负责，在人情上说不过去。</div><div class='gd-ex-line'>・<span class='gd-jp'>人の車に傷をつけたのだから、弁償せずにはすまない。</span>（既然刮伤了别人的车，不赔是说不过去的）</div><div class='gd-sec'><span class='gd-tag'>情势逼着做</span>事情闹大了，不处理就没办法收场。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここまで問題が大きくなれば、社長も記者会見をせずにはすまないだろう。</span>（问题都闹这么大了，社长恐怕也不得不开记者会吧）</div><div class='gd-sec'>前面常常会先讲理由，像是<span class='gd-jp'>〜のだから</span>、<span class='gd-jp'>〜以上</span>、<span class='gd-jp'>〜たら</span>，后面也常常加<span class='gd-jp'>だろう</span>，表示「照这情况看，应该躲不掉了」。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>ずにはすまない</b>：先变成ない形，把「ない」拿掉，再加「ずにはすまない」。<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝らない</span> → <span class='gd-jp'>謝らずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>払う</span> → <span class='gd-jp'>払わない</span> → <span class='gd-jp'>払わずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めずにはすまない</span></span><br><b>第三类要特别记</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはすまない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはすまない</span>（こずに）</span></div><div class='gd-sec'><b>ないではすまない</b>：ない形直接加「ではすまない」，不用拿掉任何东西，意思一样，口气稍微没那么硬。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議を無断で休んだのだから、部長に説明しないではすまない。</span>（会议没请假就缺席，不跟部长解释是过不去的）</div><div class='gd-sec'>还有前面接名词或「〜だけ」等的<span class='gd-jp'>〜ではすまない</span>，意思是「光这样是了结不了的」：</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談ではすまない。</span>（这不是开玩笑就能了事的）</div><div class='gd-ex-line'>・<span class='gd-jp'>謝るだけではすまない。</span>（光道歉是解决不了的）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・する要变<b>せずに</b>，不是「しずに」。<span class='gd-jp'>説明せずにはすまない</span>才对。<br>・这里的<span class='gd-jp'>すまない</span>不是「对不起」的意思，是「事情过不去」。<br>・它是书面、正式的说法，新闻、评论、正式场合比较常见。跟朋友聊天讲「该道歉了吧」，日本人通常说<span class='gd-jp'>謝らないとまずいよ</span>，或用<span class='gd-jp'>謝らないわけにはいかない</span>。<br>・重点是「外在的情理或情况逼你做」，不是你自己很想做，也不是情绪上忍不住。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「道歉」这件事，三个长得很像的说法意思差很多：<br><b>ずにはすまない</b>＝情理上不做说不过去（被情况逼）<br>・<span class='gd-jp'>ミスをしたのは私だから、謝らずにはすまない。</span>（错是我犯的，不道歉说不过去）<br><b>ずにはいられない</b>＝情绪上忍不住（N2 学过）<br>・<span class='gd-jp'>彼の涙を見て、謝らずにはいられなかった。</span>（看到他的眼泪，我忍不住道歉了）<br><b>ずにはおかない</b>＝一定要做到，不然不罢休（强烈的意志）<br>・<span class='gd-jp'>今度こそ、彼に謝らせずにはおかない。</span>（这次我一定要让他道歉）</div><div class='gd-warn'>判断小诀窍：「不做说不过去」是すまない，「忍不住」是いられない，「不做不罢休」是おかない。</div>","n1-73":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「ただ～のみ」就是中文的<b>「唯有～」「就只剩～」</b>，是「だけ」的正式、文言版。最常见的用法是讲决心：该做的都做了，眼前只剩一条路，例如<span class='gd-jp'>あとはただ待つのみだ</span>（接下来就只能等了）。语气很坚定，有种「不想别的，就专心做这件事」的味道。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>只有这个</span>强调范围只有这一个，没有别的。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格したのは、ただ一人のみだった。</span>（及格的只有一个人）</div><div class='gd-sec'><span class='gd-tag'>只剩这件事可做</span>放在句尾变成「～のみだ」，表示其他都不用想了，就是做这件事。演讲、比赛前的发言、新闻报导很常见。</div><div class='gd-ex-line'>・<span class='gd-jp'>やるべきことはすべてやった。あとはただ結果を待つのみだ。</span>（该做的都做了，接下来只能等结果）</div><div class='gd-ex-line'>・<span class='gd-jp'>今はただ無事を祈るのみです。</span>（现在只能祈求平安）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词</b>：ただ＋名词＋のみ　<span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>ただ一人のみ</span></span><br><b>动词</b>：ただ＋辞书形＋のみ　<span class='gd-pair'><span class='gd-jp'>前進する</span> → <span class='gd-jp'>ただ前進するのみだ</span></span><br>要讲得客气一点，就把最后的だ换成です：<span class='gd-jp'>祈るのみです</span>。<br>「ただ」可以省略，只用「のみ」意思也成立，加上ただ是为了更强调。</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>名词＋あるのみ</span>讲「只剩这件事要做」时，名词后面常加「ある」，几乎是固定说法：<span class='gd-jp'>努力あるのみ</span>、<span class='gd-jp'>前進あるのみ</span>、<span class='gd-jp'>練習あるのみ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合まであと一週間。練習あるのみだ。</span>（离比赛只剩一周，只能拚命练了）</div><div class='gd-sec'><span class='gd-tag'>告示牌</span>在日本街上常看到单独的「のみ」，意思是「限～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この席は会員のみご利用いただけます。</span>（这个座位限会员使用）</div><div class='gd-ex-line'>・<span class='gd-jp'>関係者のみ</span>（非相关人员请勿进入）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它很正式、很有气势。跟朋友聊午餐说「ただ食べるのみ」会很像在演戏，平常讲话用<span class='gd-jp'>だけ</span>就好：<span class='gd-jp'>あとは待つだけだ</span>。<br>・动词要用辞书形，不能接ます形：说<span class='gd-jp'>前進するのみです</span>，不能说「前進しますのみ」。<br>・<span class='gd-jp'>のみならず</span>长得很像，意思却是<b>「不只～」</b>，刚好相反：<span class='gd-jp'>ただ日本のみならず、世界中で人気がある。</span>（不只在日本，在全世界都很受欢迎）。看到のみ后面还有「ならず」，就要切换成「不只」。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>～のみだ</b>＝眼前<b>只有这条路</b>，专心往前：<span class='gd-jp'>ここまで来たら、ただ前進するのみだ。</span>（都走到这一步了，就只有往前冲）<br><b>～まで（のこと）だ</b>＝<b>大不了就～</b>，是先想好的退路，前面常有「だめなら」「失敗したら」：<span class='gd-jp'>だめなら、もう一度挑戦するまでだ。</span>（不行的话，大不了再挑战一次）</div><div class='gd-warn'>判断小诀窍：中文可以说「唯有／只能～」就用のみ；中文是「大不了就～」，前面还有「如果不行的话」，就用までだ。</div>","n1-74":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ないものでもない」就是中文的<b>「也不是不～啦」</b>。像朋友拜托你帮忙搬家，你嘴上说「看你请不请吃饭啰，也不是不能帮」。意思是有可能，但不是很情愿，也没有答应得很干脆。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词先变成否定的「ない」，后面直接加<b>ものでもない</b>。<br><span class='gd-pair'><span class='gd-jp'>引き受ける</span> → <span class='gd-jp'>引き受けない</span> → <span class='gd-jp'>引き受けないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許さない</span> → <span class='gd-jp'>許さないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合う</span> → <span class='gd-jp'>間に合わない</span> → <span class='gd-jp'>間に合わないものでもない</span></span><br>「不」加上「也不是」，两个否定抵消，变成<b>有点保留的「可以」</b>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>附条件答应</span>最常见的用法。前面常有「〜ば」「〜なら」「〜次第では（看～而定）」，先开条件，再说「也不是不行」。</div><div class='gd-ex-line'>・<span class='gd-jp'>条件次第では、引き受けないものでもない。</span>（看条件，也不是不能接）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちゃんと謝るなら、許さないものでもない。</span>（如果好好道歉，也不是不能原谅）</div><div class='gd-sec'><span class='gd-tag'>还有可能</span>判断一件事不是完全没希望。</div><div class='gd-ex-line'>・<span class='gd-jp'>あと一週間あれば、間に合わないものでもない。</span>（再多一个礼拜的话，也不是赶不上）</div><div class='gd-sec'><span class='gd-tag'>勉强能理解</span>对别人的想法表示「多少懂」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の気持ちも分からないものでもない。</span>（他的心情我也不是不能理解）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>「ない」不能漏掉。</b>写成<span class='gd-jp'>引き受けるものでもない</span>，意思就变成「也不是该接的事」，刚好反过来。像<span class='gd-jp'>お金で買えるものでもない</span>是「也不是用钱买得到的」，跟这个文法无关。<br>・它只代表「<b>有可能</b>」，不是「一定会」，也不是「很想」。翻成「我愿意」「没问题」就翻过头了。<br>・语气很硬，又是书面的说法，常带一点<b>「勉强答应你」「我在考虑看看」</b>的高姿态。对主管、客人说「手伝わないものでもないです」会很失礼，客气的时候不要用。<br>・前面接的通常是自己的行动或判断，像接不接、考不考虑、能不能理解，很少拿来说别人的事。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>意思几乎一样的还有<b>ないこともない</b>、<b>ないでもない</b>、<b>なくもない</b>，差别在场合：<br><b>ないものでもない</b>：书面、生硬，常出现在文章、谈判、比较正式的发言。<br><span class='gd-jp'>条件が合えば、協力しないものでもない。</span>（条件合的话，也不是不能合作）<br><b>ないこともない／ないでもない</b>：日常对话最常用。<br><span class='gd-jp'>時間があれば、行けないこともないよ。</span>（有时间的话，也不是不能去啦）<br><b>なくもない</b>：更口语、更随便。<br><span class='gd-jp'>まあ、分からなくもないけど。</span>（嗯，也不是不懂啦）</div><div class='gd-warn'>判断小诀窍：意思都是「也不是不～」。聊天用「ないこともない」，写文章、谈条件、想端点架子才用「ないものでもない」。</div>","n1-76":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ではあるまいし」就是中文的<b>「又不是～，（干嘛…／应该…）」</b>。妈妈看你在哭，说「又不是小孩子，哭什么哭」，就是这个语气：先丢出一个<b>明显不是事实</b>的情况，再用它来念对方、劝对方。</div><div class='gd-h'>它是怎么来的</div><div class='gd-sec'>拆开看就懂：<span class='gd-jp'>ではあるまい</span>是书面一点的「应该不是～吧」，<span class='gd-jp'>し</span>是「因为～」。合起来就是「又不是～，所以…」。<br>口语几乎都说<b><span class='gd-jp'>じゃあるまいし</span></b>，<span class='gd-jp'>ではあるまいし</span>比较常出现在文章或正式一点的场合。</div><div class='gd-h'>怎么接</div><div class='gd-sec'><span class='gd-tag'>名词</span>直接接：<span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供じゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供じゃあるまいし、自分のことは自分でやりなさい。</span>（又不是小孩，自己的事自己做）</div><div class='gd-ex-line'>・<span class='gd-jp'>神様じゃあるまいし、明日のことなんて分からないよ。</span>（我又不是神，哪知道明天会怎样）</div><div class='gd-sec'><span class='gd-tag'>动词</span>中间要先垫一个<b><span class='gd-jp'>の</span>（口语<span class='gd-jp'>ん</span>）或<span class='gd-jp'>わけ</span></b>，不能直接接。<br><span class='gd-pair'><span class='gd-jp'>遊びに行く</span> → <span class='gd-jp'>遊びに行くんじゃあるまいし</span></span><br><span class='gd-pair'><span class='gd-jp'>会えない</span> → <span class='gd-jp'>会えないわけじゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>遊びに行くんじゃあるまいし、もっとちゃんとした服を着ていきなさい。</span>（又不是去玩，穿正式一点再去）</div><div class='gd-ex-line'>・<span class='gd-jp'>一生会えないわけじゃあるまいし、そんなに泣かないで。</span>（又不是一辈子见不到，别哭成那样）</div><div class='gd-h'>后面通常接什么</div><div class='gd-sec'>后半句是你真正想讲的话，几乎都是<b>命令、禁止、劝告、批评或自己的判断</b>：「别再～」「自己做」「这种事不应该发生」。前半句则常用很夸张、一听就知道不是的东西，像<span class='gd-jp'>子供</span>、<span class='gd-jp'>神様</span>、<span class='gd-jp'>素人</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>素人じゃあるまいし、こんなミスは許されないよ。</span>（又不是外行人，这种错误说不过去）</div><div class='gd-sec'><span class='gd-tag'>口语倒装</span>讲话时很常把它放到最后补一句。</div><div class='gd-ex-line'>・<span class='gd-jp'>いちいち説明しなくても分かるよ。子供じゃあるまいし。</span>（不用每件事都解释，我懂啦，我又不是小孩）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・动词前面一定要有<span class='gd-jp'>の／ん／わけ</span>：是<span class='gd-jp'>死ぬわけじゃあるまいし</span>，不是「死ぬじゃあるまいし」。名词则反过来，不要加の，不会说「子供のじゃあるまいし」。<br>・前半句必须是<b>大家都知道「明明不是」</b>的事。如果只是单纯交代理由，例如「我不是学生，所以要付全票」，用这个就很怪，那种情况用<span class='gd-jp'>〜ではないので</span>就好。<br>・语气是在<b>念人、吐槽</b>，带点不耐烦。对主管、客人直接讲会很失礼。<br>・它不是「不会～吧」的推测句，重点在后面那句的责备或劝告。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>〜じゃないんだから</b>：意思几乎一样，「又不是～嘛」，但更日常、更常听到，N1 以下的人也会讲。<br>・<span class='gd-jp'>子供じゃないんだから、泣かないで。</span>（又不是小孩，别哭了）<br>・<span class='gd-jp'>子供じゃあるまいし、泣かないで。</span>（同上，语气稍微老派、带点念人的味道）</div><div class='gd-sec'><b>〜ではあるまいか</b>：只差最后一个字，意思完全不同，是书面语的「该不会是～吧／恐怕是～吧」，用来推测。<br>・<span class='gd-jp'>子供ではあるまいし、一人で行けるだろう。</span>（又不是小孩，一个人去得了吧）<br>・<span class='gd-jp'>彼は何か隠しているのではあるまいか。</span>（他是不是在隐瞒什么呢）</div><div class='gd-warn'>判断小诀窍：后面有「し」＋一句念人的话，就是「又不是～」；最后是「か」，就是在猜「该不会是～吧」。</div>","n1-78":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AあってのB」就是中文的<b>「有A才有B」「B全靠A」</b>。A是B能存在的前提，没有A，B就不存在。台湾店家常说「客人是我们的衣食父母」，日文就是：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）</div><div class='gd-h'>怎么接</div><div class='gd-sec'><b>名词＋あっての＋名词</b>。前面放名词，后面也一定接名词。<br>「あって」是「ある（有）」的て形，加上「の」就是「有了～的…」。<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様あっての商売</span></span>（有客人才有的生意）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'><span class='gd-tag'>AあってのBだ</span>讲一个道理或价值观：B是靠A撑起来的。</div><div class='gd-ex-line'>・<span class='gd-jp'>選手はファンあっての存在だ。</span>（选手是因为有球迷才存在的）</div><div class='gd-ex-line'>・<span class='gd-jp'>命あっての物種だ。無理はするな。</span>（人活着才有一切，不要硬撑）</div><div class='gd-sec'><span class='gd-tag'>〜あってのことだ</span>后面的名词换成「こと」，意思是「这都是靠～才有的」。得奖感言、致谢最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のご指導あってのことです。</span>（我能考上，全靠老师的指导）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの応援あっての優勝です。</span>（有大家的加油才有这次冠军）</div><div class='gd-sec'><span class='gd-tag'>あってこその</span>中间加「こそ」，语气更强：<span class='gd-jp'>家族あってこその私です。</span>（正因为有家人，才有现在的我）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・后面一定要接名词（或こと）。不能说「お客様あっての売れる」，要说<span class='gd-jp'>お客様あっての商売</span>。<br>・固定用「あっての」，不要写成「あるの」。<br>・它不是单纯的「因为」。「因为下雨所以取消」不能说「雨あっての中止」，要说<span class='gd-jp'>雨で中止になった</span>。A要是B<b>不可缺少的根本</b>，通常是客人、健康、支持、努力这类正面又重要的东西。<br>・语气比较正式、带点感性，多用在演讲、访谈、文章。跟朋友聊天直接说<span class='gd-jp'>お客さんがいるから</span>就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个意思，可以从正面讲，也可以从反面讲：<br><b>あっての</b>＝正面说「有A才有B」，后面接名词：<span class='gd-jp'>お客様あっての商売だ。</span>（有客人才有生意）<br><b>なくしては</b>＝反面说「没有A就不能B」，后面接否定：<span class='gd-jp'>お客様なくしては商売は成り立たない。</span>（没有客人，生意就做不起来）<br><b>ばこそ</b>＝「正因为～才…」，说明做某件事的理由，前面接ば形：<span class='gd-jp'>お客様のことを思えばこそ、品質にこだわるのだ。</span>（正因为替客人着想，才讲究品质）</div><div class='gd-warn'>判断小诀窍：讲「B是靠A才存在的」用あっての，后面放名词；讲「少了A就办不到」用なくしては，后面放否定；讲「正因为这样想或这样做」用ばこそ。</div>","n1-79":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「ともすると／ともすれば」就是中文的<b>「动不动就～」「一不小心就～」「往往容易～」</b>。它讲的是一种<b>不太好的倾向</b>：不是每次都这样，但稍微没注意就会往那个方向跑。像「人一闲下来就容易滑手机滑到半夜」这种感觉。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>它是一个<b>独立的词</b>，不用接在任何字后面，放在句子开头，或放在「要讲的那件坏事」前面就好。<br>后半句通常搭配表示「容易～」的说法，前后一起出现最自然：<br><span class='gd-tag'>常见搭配</span><span class='gd-jp'>〜がちだ</span>（常常会～）、<span class='gd-jp'>〜やすい</span>（容易～）、<span class='gd-jp'>〜てしまう</span>（不小心就～了）</div><div class='gd-ex-line'>・<span class='gd-jp'>人はともすると、楽なほうへ流れがちだ。</span>（人往往容易往轻松的方向走）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすれば食事を抜いてしまう。</span>（一忙起来，常常一不小心就没吃饭）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしだと、ともすると生活が不規則になりやすい。</span>（一个人住的话，生活很容易变得不规律）</div><div class='gd-sec'>「ともすると」和「ともすれば」意思一样，可以互换，挑顺口的用就好。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它不是接在别的字后面的文法，不能写成「忙しいともすると」。要分开放：<span class='gd-jp'>忙しいと、ともすると〜</span>。<br>・它讲的是<b>不好的倾向</b>。好习惯不会用它，例如想说「我常常不知不觉就去运动」，不会用ともすると。<br>・它讲的是「常有的倾向」，不是某一次发生的事。「昨天一不小心迟到了」只是一次的意外，不用ともすると，直接说<span class='gd-jp'>うっかり遅刻した</span>就好。<br>・语气偏书面、偏正式，文章、演讲、评论里很常见。跟朋友聊天比较常说<span class='gd-jp'>つい</span>、<span class='gd-jp'>すぐ</span>，例如<span class='gd-jp'>ついスマホを見ちゃう</span>（忍不住就一直看手机）。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>ともすると／ともすれば</b>：独立放在句中，讲<b>容易陷入的坏倾向</b>，后面常配がち、やすい。<br><b>ともなると／ともなれば</b>：前面接名词（多为身分、立场、时间、程度），也可以接动词辞书形，意思是<b>「一旦到了某种身分、时期、状况，就理所当然会～」</b>。<br>同样讲「忙到没吃饭」，对照看看：</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすると食事を抜きがちだ。</span>（一忙就容易不吃饭：讲坏习惯）</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、食事をする時間もない。</span>（一到年底，连吃饭的时间都没有：讲到了那个时期自然会这样）</div><div class='gd-sec'>ともなると的其他例子：<span class='gd-jp'>社長ともなると、なかなか休めない。</span>（当到社长，就很难休假）<br><span class='gd-jp'>海外に住むともなると、準備が大変だ。</span>（要是到了住国外这一步，准备起来可辛苦了）</div><div class='gd-warn'>判断小诀窍：前面有接名词或动词、讲「到了那个阶段就会～」的是ともなると；自己一个词站着、讲「动不动就～（坏事）」的是ともすると。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>同样讲「有不好的倾向」，可以接着看<span class='gd-jp'>〜嫌いがある</span>，它放在句尾：<span class='gd-jp'>彼は物事を悲観的に考える嫌いがある。</span>（他有把事情往悲观方向想的倾向）。两个也常一起用：<span class='gd-jp'>人はともすると、自分に甘くなる嫌いがある。</span>（人往往有对自己太宽容的毛病）</div>","n1-82":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜を限りに」就是<b>「就到〜为止，之后就不再〜了」</b>。像中文说「今天是最后一天」「做完这次就收山」，划一条线：线之前还有，线之后就没了。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面直接放时间点的名词，再加「を限りに」：<br><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日を限りに</span></span><span class='gd-pair'><span class='gd-jp'>今回</span> → <span class='gd-jp'>今回を限りに</span></span><span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日を限りに</span></span><br>最常见的是<span class='gd-jp'>今日・本日・今回・今月・今年度</span>这种「现在这个时间点」的词。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>下决心不再做</span>跟过去的自己切割，常常带点决心。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日を限りに、お酒はやめる。</span>（喝到今天为止，以后不喝了）</div><div class='gd-sec'><span class='gd-tag'>宣布结束</span>店收掉、选手退休、制度废除，常带一点感慨。</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の試合を限りに、引退します。</span>（打完这场比赛我就退休）</div><div class='gd-ex-line'>・<span class='gd-jp'>この路線は今年度を限りに廃止される。</span>（这条路线营运到本年度结束后就废除）</div><div class='gd-sec'><span class='gd-tag'>另一个意思</span>「<span class='gd-jp'>声を限りに</span>」是固定说法，意思是「用尽全力、扯开喉咙」，跟时间无关，看到要认得。</div><div class='gd-ex-line'>・<span class='gd-jp'>声を限りに助けを呼んだ。</span>（扯开喉咙拼命呼救）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・它不是「截止期限」。交作业的期限要用までに：<span class='gd-jp'>金曜日までに出してください。</span>（请在星期五前交），不能说「金曜日を限りに出してください」。<br>・后面接的多半是<b>结束、停止、不再做</b>的事，像<span class='gd-jp'>やめる・引退する・閉店する・解散する</span>。如果只是要说「从今天开始努力」，日文通常用<span class='gd-jp'>今日から</span>。<br>・这是偏正式、偏书面的说法。平常跟朋友讲，用<span class='gd-jp'>今日でやめる</span>或<span class='gd-jp'>今日限りでやめる</span>就好。<br>・别跟「动词＋限り」搞混：<span class='gd-jp'>生きている限り</span>是「只要还活着」，意思完全不同。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>をもって</b>也能表示「以〜为结束」，同一个关店公告两个都能用，但感觉不一样：<br><span class='gd-jp'>本日をもって閉店いたします。</span>（本店营业至今日止）<br>→ 公事公办的正式公告，只是通知「在这天结束」。<br><span class='gd-jp'>本日を限りに閉店いたします。</span>（今天是最后一天营业）<br>→ 重点在「就到今天，以后再也没有了」，比较有感情、有落幕的味道。<br>另外，<b>をもって</b>也能表示<b>开始</b>：<span class='gd-jp'>4月1日をもって新制度を実施します。</span>（自 4 月 1 日起实施新制度）；<b>を限りに</b>只能用在「最后」，不能拿来说开始。</div><div class='gd-warn'>判断小诀窍：想强调「最后一次、之后不再」用を限りに；正式通知某天开始或结束用をもって。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>意思刚好相反的是「<span class='gd-jp'>〜を皮切りに</span>」＝以〜为开端，接着一个个展开：<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まる。</span>（从东京场开始，展开全国巡回）</div>","n1-83":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'><span class='gd-jp'>めく</span>就是中文的<b>「有点～的味道」「透出一股～的气息」</b>。还没完全变成那样，但已经感觉得到了。像二月底某天突然回暖，你会说「有点春天的感觉了」，日文就是<span class='gd-jp'>春めいてきた</span>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>季节慢慢转换</span>最常见的用法，通常配<span class='gd-jp'>〜めいてきた</span>，表示「渐渐有了～的感觉」。</div><div class='gd-ex-line'>・<span class='gd-jp'>一気に春めいてきた。</span>（一下子有春天的感觉了）</div><div class='gd-ex-line'>・<span class='gd-jp'>風が少し秋めいてきた。</span>（风开始有点秋天的味道了）</div><div class='gd-sec'><span class='gd-tag'>形容人或说话方式</span>用<span class='gd-jp'>〜めいた</span>放在名词前面，表示「带点～味道的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はどこか謎めいた人だ。</span>（她是个有点神秘的人）</div><div class='gd-ex-line'>・<span class='gd-jp'>皮肉めいた言い方はやめてよ。</span>（别用那种带刺的讲法啦）</div><div class='gd-ex-line'>・<span class='gd-jp'>言い訳めいたことは言いたくない。</span>（我不想讲像在找借口的话）</div><div class='gd-h'>怎么接、怎么变</div><div class='gd-sec'>名词后面直接加<span class='gd-jp'>めく</span>，整个就变成一个动词，而且是<b>第一类（五段动词）</b>，变法跟<span class='gd-jp'>書く</span>一样。<br>接て、た的时候，く换成い：<br><span class='gd-pair'><span class='gd-jp'>春めく</span> → <span class='gd-jp'>春めいて</span></span> → <span class='gd-pair'><span class='gd-jp'>春めいてきた</span></span><br><span class='gd-pair'><span class='gd-jp'>謎めく</span> → <span class='gd-jp'>謎めいた</span></span> → <span class='gd-pair'><span class='gd-jp'>謎めいた事件</span></span>（神秘的事件）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>不是每个名词都能接</b>。<span class='gd-jp'>めく</span>只跟一小群固定的词搭配，常见的有<span class='gd-jp'>春めく</span>、<span class='gd-jp'>秋めく</span>、<span class='gd-jp'>謎めく</span>、<span class='gd-jp'>皮肉めく</span>、<span class='gd-jp'>冗談めく</span>、<span class='gd-jp'>言い訳めく</span>、<span class='gd-jp'>説教めく</span>。像「<span class='gd-jp'>学生めく</span>」「<span class='gd-jp'>先生めく</span>」就不自然，要说<span class='gd-jp'>学生らしい</span>或<span class='gd-jp'>学生っぽい</span>。<br>・放在名词前面几乎都用<b>めいた</b>：说<span class='gd-jp'>謎めいた人</span>，不太说謎めく人。<br>・て形是<span class='gd-jp'>めいて</span>，不是めくて，也不是めきて。<br>・<span class='gd-jp'>春めいてきた</span>是「有春天的感觉了」，不等于<span class='gd-jp'>春になった</span>（已经是春天了）。<br>・语感偏书面、偏文学，天气报导、小说里很常见。跟朋友随口聊天，一般用<span class='gd-jp'>っぽい</span>比较多。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「春天」：<br><span class='gd-jp'>だんだん春めいてきた。</span>（渐渐透出春天的气息了）：重点在<b>开始有迹象</b>。<br><span class='gd-jp'>今日は春らしい天気だ。</span>（今天是很有春天样子的天气）：重点在<b>很典型、名副其实</b>。<br><span class='gd-jp'>春っぽい服を買った。</span>（买了很春天感的衣服）：<b>口语</b>，随口说「很像～」。</div><div class='gd-warn'>判断小诀窍：「开始透出～的气息、带点～味道」用めく；「很有～该有的样子」用らしい；聊天随口说「很～的感觉」用っぽい。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'><span class='gd-jp'>めく</span>有个兄弟<span class='gd-jp'>めかす</span>，表示「故意弄成～的样子」：<span class='gd-jp'>冗談めかして本音を言った。</span>（用开玩笑的口气说出了真心话）</div>","n1-84":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>这组文法就是中文的<b>「足足有～」「多达～之多」</b>。前面放一个数字，说话的人想强调「这数字很大耶」，而且<b>可能还不只这样</b>。像你看到一个 30 公斤的行李会说「这个足足有 30 公斤欸」，日文就用它。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面一定是<b>数字＋单位</b>（100キロ、1万人、50万円），后面直接接からある／からする／からの。三个怎么选，看你在讲什么东西。</div><div class='gd-sec'><span class='gd-tag'>からある</span>重量、长度、高度、距离、大小。<br>日文本来就说「重さが<b>ある</b>」「長さが<b>ある</b>」，所以讲「有多重、有多长」用ある。</div><div class='gd-ex-line'>・<span class='gd-jp'>30キロからある荷物を一人で運んだ。</span>（一个人搬了足足 30 公斤的行李）</div><div class='gd-ex-line'>・<span class='gd-jp'>2メートルからある魚が釣れた。</span>（钓到一条足足两公尺长的鱼）</div><div class='gd-ex-line'>・<span class='gd-jp'>片道100キロからある道のりを毎日車で通っている。</span>（他每天开车通勤，单程足足一百公里）</div><div class='gd-sec'><span class='gd-tag'>からする</span>价钱。<br>日文讲「要价多少」本来就用する：<span class='gd-jp'>この時計は100万円する。</span>（这支表要一百万日圆）。所以价钱配からする。</div><div class='gd-ex-line'>・<span class='gd-jp'>一泊10万円からするホテルに泊まった。</span>（住了一晚要价足足十万日圆的饭店）</div><div class='gd-ex-line'>・<span class='gd-jp'>あのバッグは50万円からするらしい。</span>（听说那个包包要价高达五十万日圆）</div><div class='gd-sec'><span class='gd-tag'>からの</span>最常用在人数，后面<b>一定要接名词</b>（の就是「的」）。钱、债务这类数量也可以用からの＋名词。</div><div class='gd-ex-line'>・<span class='gd-jp'>会場には1万人からの人が集まった。</span>（会场聚集了多达一万人）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には1000万円からの借金がある。</span>（他背了多达一千万日圆的债）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・只能用在<b>大的数字</b>。<span class='gd-jp'>1キロからある荷物</span>很怪，因为一公斤没什么好强调的。<br>・からする只管<b>价钱</b>。重量要说<span class='gd-jp'>100キロからある</span>，不是100キロからする。<br>・からの后面一定要有名词：<span class='gd-jp'>1万人からの人</span>可以，句子停在「1万人からの。」就不行。<br>・这组文法有点书面、正式，新闻、报导、文章很常见。跟朋友聊天讲得出来，但比较口语的说法是用「も」（下面会讲）。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>一般的「から」</b>＝<b>从～起跳</b>（价格范围的最低价）：<br><span class='gd-jp'>この店の時計は1万円からあります。</span>（这家店的表一万日圆起跳）<br><b>からする</b>＝<b>足足要～</b>（强调很贵）：<br><span class='gd-jp'>この時計は100万円からする。</span>（这支表要价足足一百万日圆）<br>前者是在讲「最便宜的从哪里开始」，后者是在讲「这一个东西有够贵」。</div><div class='gd-sec'><b>数字＋も</b>＝口语的「竟然有～」：<span class='gd-jp'>この荷物、30キロもあるよ。</span>（这行李竟然有 30 公斤耶）<br><b>からある</b>＝比较书面，带有「至少这么多、说不定更多」的感觉：<span class='gd-jp'>30キロからある荷物</span>（足足有 30 公斤的行李）</div><div class='gd-warn'>判断小诀窍：店家写「～円から」是在报最低价；数字后面接からある／からする／からの，是说话的人在惊叹「这数字好大」。重量长度用ある、价钱用する、后面要接名词就用からの。</div>","n1-85":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜ようにも〜ない」就是中文的<b>「想～也～不了」</b>，像「想逃也逃不掉」「想忘也忘不掉」。心里真的想做，却被状况卡住，<b>根本做不到</b>，口气里带着无奈。</div><div class='gd-ex-line'>・<span class='gd-jp'>逃げようにも逃げられない状況だった。</span>（当时是想逃也逃不了的状况）</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>被外在状况卡住</span>受伤、没车、没有联络方式……不是你不想，是条件不允许。</div><div class='gd-ex-line'>・<span class='gd-jp'>終電がなくて、帰ろうにも帰れない。</span>（末班车没了，想回家也回不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがしていて、歩こうにも歩けない。</span>（脚受伤了，想走也走不了）</div><div class='gd-sec'><span class='gd-tag'>心里过不去</span>有时候卡住你的是情绪或回忆。</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れようにも忘れられない思い出だ。</span>（那是想忘也忘不掉的回忆）</div><div class='gd-ex-line'>・<span class='gd-jp'>状況が深刻すぎて、笑おうにも笑えなかった。</span>（情况太严重，想笑也笑不出来）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词的意向形（「〜う／〜よう」，就是「〜吧」那个形）＋にも＋<b>同一个动词</b>的「做不到」形（可能形的否定）。<br>中间常插一句原因：<span class='gd-jp'>帰ろうにも、終電がなくて帰れない。</span><br>后半也可以不重复动词，直接讲卡住你的原因：</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しようにも、番号が分からない。</span>（想打电话，却不知道号码）</div><div class='gd-h'>怎么变：先看动词是哪一类</div><div class='gd-sec'><b>第一类（五段动词）</b>：前半把最后一个音换成同一行的「お」段音，再加「う」；后半把最后一个音换成同一行的「え」段音，再加「ない」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く换成こ → <span class='gd-jp'>書こう</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → く换成け → <span class='gd-jp'>書けない</span></span><br>合起来：<span class='gd-jp'>書こうにも書けない</span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろうにも帰れない</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そうにも話せない</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おうにも会えない</span></span></div><div class='gd-sec'><b>第二类（一段动词）</b>：前半把「る」拿掉加「よう」；后半把「る」拿掉加「られない」。<br><span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げようにも逃げられない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れようにも忘れられない</span></span></div><div class='gd-sec'><b>第三类（只有两个，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようにもできない</span></span>，例：<span class='gd-jp'>予約しようにも予約できない</span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようにも来られない</span>（こようにもこられない）</span></div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前半一定要用意向形：是<span class='gd-jp'>帰ろうにも</span>，不是帰るようにも。它跟 N4 学的「〜ように」（为了～）没关系，别看到「よう」就接辞书形。<br>・后半要是「<b>做不到</b>」，不是「不做」：写成帰らない就变成「自己不想回」，跟前面的「想回」打架了。<br>・前提是本人<b>真的想做</b>。懒得做、没兴趣做，不能用这个句型。<br>・第二类的「做不到」，正式文章和考试要写<span class='gd-jp'>逃げられない</span>；口语常听到的「逃げれない」写作时要避免。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「逃」，看三种说法的差别：<br><b>ようにも</b>＝想做，但<b>根本做不到</b>：<span class='gd-jp'>逃げようにも、ドアに鍵がかかっていて逃げられない。</span>（想逃，但门锁住了，逃不了）<br><b>たところで</b>＝就算做了，<b>也没用</b>：<span class='gd-jp'>今さら逃げたところで、すぐに見つかるだろう。</span>（现在才逃，也很快会被找到）<br><b>ようと／ようが</b>＝<b>不管怎么做</b>，结果都一样：<span class='gd-jp'>どこへ逃げようと、必ず見つけ出す。</span>（不管你逃到哪里，我一定把你找出来）</div><div class='gd-warn'>判断小诀窍：「想做却做不到」用ようにも，「做了也白做」用たところで，「不管怎么做」用ようと／ようが。</div>","n1-86":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜とは言い条」就是中文的<b>「虽说是～，但…」「名义上是～，其实…」</b>。前面先承认一个说法，后面马上说「实际情况没那么简单」。意思跟「とはいえ」差不多，只是更老派、更像文章里的写法，日常讲话几乎不会用。</div><div class='gd-h'>先懂「言い条」这个字</div><div class='gd-sec'><span class='gd-jp'>言い条</span>念<b>いいじょう</b>，原本是「说法、说词」的意思。所以「Aとは言い条」照字面就是「说是A，那是一种说法」。言下之意是：<b>话是这么说，但现实是另一回事</b>。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词直接接：<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロとは言い条</span></span><br>动词、形容词用普通形（就是没有ます、です的说法）接：<span class='gd-pair'><span class='gd-jp'>分かっている</span> → <span class='gd-jp'>分かっているとは言い条</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとは言い条</span></span><br>实际看到最多的是<b>名词直接接</b>。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>名不符实</span>前面是大家公认的说法或名称，后面点出现实不是那样。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、朝晩はまだ冷える。</span>（虽说已经是春天，早晚还是很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>自由とは言い条、実際には多くの制約がある。</span>（名义上说是自由，实际上限制很多）</div><div class='gd-sec'><span class='gd-tag'>道理懂，做不到</span>承认前面那件事没错，但结果还是不理想。</div><div class='gd-ex-line'>・<span class='gd-jp'>頭では分かっているとは言い条、なかなか実行に移せない。</span>（虽然脑袋明白，却迟迟付诸不了行动）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロとは言い条、ミスを犯すこともある。</span>（虽说是专业人士，也难免会出错）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・念法是<b>いいじょう</b>。「条」念じょう（长音），不要念成「いうじょう」或短短的「じょ」。<br>・它放在<b>句子中间</b>，后面一定还要接一句「但是…」的内容，不能单独放在句尾就结束。<br>・这是很硬的书面语，用在评论、小说、文章里。跟朋友聊天说「春とは言い条」会很像在念古书，口语说「<span class='gd-jp'>春だけど</span>」就好。<br>・考试看到它，只要认得「虽说～但…」就够了，自己写作时用「とはいえ」比较不会怪。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>三个意思都是「虽说～但…」，差在<b>多正式、多老派</b>。同一个情境比一比：<br><b>とはいうものの</b>：书面、正式场合讲话也会用。<br></div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い。</span>（虽说是春天，还是很冷）</div><div class='gd-sec'><b>とはいえ</b>：书面为主，新闻、文章很常见，正式一点的口语也听得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、まだ寒い。</span>（虽说是春天，还是很冷）</div><div class='gd-sec'><b>とは言い条</b>：最古风，现代几乎只在文章、文学作品里看得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、まだ寒い。</span>（虽说是春天，还是很冷）</div><div class='gd-warn'>判断小诀窍：意思都一样是「虽说～但…」。越像古书、越文诌诌的就是「とは言い条」；平常写文章选「とはいえ」最保险。</div>","n1-87":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜かれ〜かれ」就是中文的<b>「迟早」「或多或少」「不管好坏」</b>。它不是可以自由套词的句型，而是<b>三组固定说法</b>，整组背起来就好。</div><div class='gd-h'>它是怎么来的</div><div class='gd-sec'>「かれ」是古文的命令形，大概等于「就算～也罢」。<br><span class='gd-jp'>多かれ少なかれ</span>原本的意思接近「多也罢、少也罢」，后来变成「不管多或少，反正都有」。<br>你不用学古文，只要知道：它是两个<b>意思相反</b>的形容词排在一起，表示「哪一边都一样，结果不会变」。</div><div class='gd-h'>最常听到的三组</div><div class='gd-sec'><span class='gd-tag'>遅かれ早かれ</span>念「おそかれはやかれ」，＝迟早、早晚。后面通常接「一定会发生」的事，有「躲不掉」的感觉，日常对话也常讲。</div><div class='gd-ex-line'>・<span class='gd-jp'>嘘は遅かれ早かればれるよ。</span>（谎话迟早会被拆穿的）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、決めなきゃいけないことだ。</span>（这件事早晚都得做决定）</div><div class='gd-sec'><span class='gd-tag'>多かれ少なかれ</span>念「おおかれすくなかれ」，＝或多或少。后面常接「誰でも」「みんな」，表示人人都有，只是程度不同。</div><div class='gd-ex-line'>・<span class='gd-jp'>多かれ少なかれ、誰にでも悩みはある。</span>（每个人或多或少都有烦恼）</div><div class='gd-sec'><span class='gd-tag'>善かれ悪しかれ</span>念「よかれあしかれ」，＝不管是好是坏。比前两组正式，多用在文章、评论。</div><div class='gd-ex-line'>・<span class='gd-jp'>善かれ悪しかれ、スマホは私たちの生活を大きく変えた。</span>（不管是好是坏，手机都大大改变了我们的生活）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・<b>不能自己造</b>：看到「形容词＋かれ」就想套<span class='gd-jp'>高い</span>、<span class='gd-jp'>大きい</span>，这样不行。实际上就是这三组。<br>・是<b>悪しかれ</b>，不是「悪かれ」。这里用的是古文的「悪し」，不是现代的「悪い」。<br>・顺序固定：讲<span class='gd-jp'>遅かれ早かれ</span>、<span class='gd-jp'>多かれ少なかれ</span>，不要前后颠倒。<br>・单独的<span class='gd-jp'>よかれと思って</span>是另一个说法，意思是「出于好意、以为这样对对方好」，跟「不管好坏」无关。<br>　<span class='gd-jp'>よかれと思って言ったのに、怒られた。</span>（我是好意才说的，结果被骂了）</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样是「不管A还是B」，<span class='gd-jp'>〜にせよ〜にせよ</span>和<span class='gd-jp'>〜であれ〜であれ</span>可以自由换词，<span class='gd-jp'>〜かれ〜かれ</span>不行。</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してね。</span>（不管去不去，都早点跟我说）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨であれ雪であれ、試合は行われる。</span>（不管下雨还是下雪，比赛都照常举行）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、ばれるよ。</span>（迟早会被发现的）</div><div class='gd-sec'>反过来，「迟早」也不会说成<span class='gd-jp'>遅いにせよ早いにせよ</span>。这样文法上没错，但听起来像在讨论「慢或快」两种情况，不是「迟早」这个固定讲法。日本人就是讲<span class='gd-jp'>遅かれ早かれ</span>。<br>另外注意：<span class='gd-jp'>であれ</span>前面接名词或な形容词，<b>不接い形容词</b>，所以「遅いであれ」本身就是错的。</div><div class='gd-warn'>判断小诀窍：想讲「迟早／或多或少／不管好坏」，直接用かれ的三组；其他「不管A还是B」，用にせよ或であれ。</div>","n1-88":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜始末だ」就是中文的<b>「搞到最后，居然还～」「落得～的下场」</b>。先讲一连串不像话的事，最后丢出一个更糟的结局，口气里带着<b>傻眼、受不了、数落</b>的感觉。像是你跟朋友抱怨：「他迟到就算了，东西也忘了带，结果咧？最后还被主管骂。」</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>数落别人</span>最典型的用法。讲某个人一路越来越离谱，最后到了夸张的地步。</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は毎晩ゲームばかりして、ついには学校を休む始末だ。</span>（儿子每天晚上都在打电动，最后居然搞到连学校都不去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何度注意しても聞かず、最近は返事もしない始末だ。</span>（他怎么讲都不听，最近甚至连回话都不回了）</div><div class='gd-sec'><span class='gd-tag'>自嘲</span>讲自己也可以，带着「我真是够了」的自我吐槽。</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊して駅まで走ったのに、財布を家に忘れる始末だ。</span>（睡过头一路冲到车站，结果还把钱包忘在家里）</div><div class='gd-h'>怎么接</div><div class='gd-sec'>动词辞书形＋始末だ：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休む始末だ</span></span><br>动词ない形＋始末だ：<span class='gd-pair'><span class='gd-jp'>しない</span> → <span class='gd-jp'>返事もしない始末だ</span></span><br>指示词＋始末だ：<span class='gd-jp'>この始末だ</span>、<span class='gd-jp'>あの始末だ</span>（「搞成这副德性」）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれほど言ったのに、この始末だ。</span>（我都讲成那样了，结果还是搞成这样）</div><div class='gd-h'>最常听到的样子</div><div class='gd-sec'>前面常搭配「到最后」这类的词，把「一路越来越糟」的感觉铺出来：<span class='gd-jp'>ついには</span>、<span class='gd-jp'>とうとう</span>、<span class='gd-jp'>最後には</span>、<span class='gd-jp'>挙句の果てには</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>借金を重ね、挙句の果てには夜逃げする始末だ。</span>（债越欠越多，到最后落得连夜跑路）</div><div class='gd-sec'>讲过去的事时，前面一样用辞书形，句尾可以用<span class='gd-jp'>始末だった</span>。</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・前面用<b>辞书形或ない形</b>，不要接た形：是<span class='gd-jp'>叱られる始末だ</span>，不是叱られた始末だ。<br>・<b>只能用在坏结果</b>。「努力读书，最后考上了」不能用始末だ。<br>・要有<b>前面的铺陈</b>。只丢一句「他迟到的始末だ」很怪，要先交代前面怎么一步步变糟。<br>・口气是在<b>数落、抱怨</b>，当着主管或客人的面这样讲他们，非常不客气。比较常出现在抱怨、文章、评论里。<br>・单独的<span class='gd-jp'>始末</span>还有「收拾、处理」的意思，像<span class='gd-jp'>後始末</span>（善后）、<span class='gd-jp'>始末書</span>（悔过书），跟这个句型是两回事。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同样讲「最后变成～」，还有 N2 学过的「末に」「羽目になる」，差在<b>结果好不好、在讲谁、说话的人什么心情</b>。<br><b>末に</b>＝经过一番过程后的结论，<b>中性</b>，好结果也行：<br><span class='gd-jp'>何度も話し合った末に、ゲームは一日一時間と決めた。</span>（讨论了好几次，最后决定一天只玩一小时）<br><b>羽目になる</b>＝<b>自己</b>被迫落得做某件麻烦事，带着后悔：<br><span class='gd-jp'>息子のゲームの課金を、私が払う羽目になった。</span>（儿子游戏课的金，最后变成我得来付）<br><b>始末だ</b>＝说话的人<b>傻眼、数落</b>某人「居然搞到这种地步」：<br><span class='gd-jp'>息子はゲームに夢中で、ついには学校を休む始末だ。</span>（儿子迷电动，最后居然连学校都不去了）</div><div class='gd-warn'>判断小诀窍：中性的「最后决定～」用末に；「害我不得不～」用羽目になる；想翻白眼说「搞到最后居然还～」就用始末だ。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>常跟「〜あげく」一起出现：<span class='gd-jp'>さんざん迷ったあげく、何も買わずに帰ってくる始末だ。</span>（犹豫了老半天，最后居然什么都没买就回来了）</div>","n1-90":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「〜にかこつけて」就是中文的<b>「藉～之名」「拿～当借口」</b>。表面上是为了 A，其实心里真正想做的是 B。像是说「我去出差」，结果大半时间都在逛街吃美食，这种「挂羊头卖狗肉」的感觉就是它。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>名词＋にかこつけて，后面接真正想做的事。<br><span class='gd-pair'><span class='gd-jp'>出張</span> → <span class='gd-jp'>出張にかこつけて</span></span>（藉出差之名）<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事にかこつけて</span></span>（拿工作当借口）<br>前面放的是「说得出口的正当理由」，后面才是「其实想做的事」。</div><div class='gd-h'>什么时候用</div><div class='gd-sec'><span class='gd-tag'>吐槽别人</span>最常见的用法。看不惯某人拿正当理由当幌子，带点批评。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は視察にかこつけて、毎年ハワイに行っている。</span>（部长每年都藉视察之名跑去夏威夷）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事にかこつけて、毎晩飲みに行っている。</span>（他拿工作当借口，每天晚上都跑去喝酒）</div><div class='gd-sec'><span class='gd-tag'>自嘲</span>讲自己也可以，等于自己承认「其实我是想做那件事啦」，口气有点不好意思、有点好笑。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの誕生日にかこつけて、自分が食べたいケーキを買った。</span>（藉孩子生日之名，买了我自己想吃的蛋糕）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にかこつけて、ジムをサボった。</span>（拿下雨当借口，翘掉了健身房）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・助词是<b>に</b>，不是を。意思很像的日常说法「〜を口実に」才用を，两个不要混在一起，写成「出張をかこつけて」是错的。<br>・它一定带<b>「表面理由跟真正目的不一样」</b>的味道。如果你真的是去出差，只是顺便看看风景，用它就会变成在说自己「假出差、真玩乐」。<br>・因为带批评或自嘲的口气，不适合在正式场合拿来说明自己的行程。例如跟主管报告时说「出張にかこつけて…」，等于自己承认在摸鱼。<br>・平常大多写成平假名。汉字写作「託けて」，不太常看到，认得就好。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'>同一个情境：出差时去了京都观光。<br><b>がてら</b>＝<b>顺便</b>，两件事都是真的，光明正大：<br><span class='gd-jp'>出張がてら、京都を観光した。</span>（出差顺便在京都观光）<br><b>かたがた</b>＝也是「顺便、兼」，但比较正式，常用在拜访、致谢这类场合：<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺った。</span>（去老师家拜访，顺便表达谢意）<br><b>にかこつけて</b>＝前面的理由只是<b>幌子</b>，真正目的是后面那件事：<br><span class='gd-jp'>出張にかこつけて、京都を観光した。</span>（藉出差之名，其实是去京都玩）</div><div class='gd-warn'>判断小诀窍：两件事都是真心要做的，用「がてら」，正式场合用「かたがた」；前面的理由只是借口、后面才是真正想做的，就用「にかこつけて」。</div><div class='gd-h'>学会之后可以接着学</div><div class='gd-sec'>日常对话更常听到「〜を口実に」，意思几乎一样，口气比较直接：<span class='gd-jp'>風邪を口実に、会社を休んだ。</span>（拿感冒当借口，跟公司请假）</div>","n1-92":"<div class='gd-h'>一句话先懂</div><div class='gd-sec'>「AとBが相まって」就是<b>「A 跟 B 两个因素凑在一起，效果加倍」</b>。像中文说「天时加上地利」「累加上没睡饱」：单看一个还好，两个一叠，结果就特别明显。好的坏的都能用，常出现在新闻、评论、文章里。</div><div class='gd-h'>怎么接</div><div class='gd-sec'>前面接<b>名词</b>。常见的有三种样子：<br><span class='gd-tag'>AはBと相まって</span>主角 A 跟另一个因素 B 结合。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は努力と相まって、大きな成果を生んだ。</span>（他的才能加上努力，创造了很大的成果）</div><div class='gd-sec'><span class='gd-tag'>AとBが相まって</span>两个因素并排放，一起造成后面的结果。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は料理の味と雰囲気の良さが相まって、いつも予約でいっぱいだ。</span>（这家店料理好吃，气氛又好，所以总是订满）</div><div class='gd-sec'><span class='gd-tag'>Bも相まって</span>新闻最常见。用「も」表示「本来就有其他原因，<b>再加上</b>B」。</div><div class='gd-ex-line'>・<span class='gd-jp'>円安も相まって、外国人観光客が急増している。</span>（再加上日圆贬值，外国观光客暴增）</div><div class='gd-sec'>前面如果是一整句话，要先加「こと」变成名词：<br><span class='gd-pair'><span class='gd-jp'>駅から近い</span> → <span class='gd-jp'>駅から近いことも相まって</span></span>（再加上离车站近）</div><div class='gd-h'>容易搞错的地方</div><div class='gd-warn'>・念<b>あいまって</b>，不是「そうまって」。<br>・一定要有<b>两个以上的因素</b>。只有一个原因时不能用：下雨害比赛取消，就直接说<span class='gd-jp'>雨で試合が中止になった</span>，不能说「雨と相まって中止になった」。<br>・不是只能用在好事，坏事一样可以用：<span class='gd-jp'>寝不足と疲れが相まって、熱を出してしまった。</span>（睡眠不足加上疲劳，结果发烧了）所以别把它想成中文的「相辅相成」，「相辅相成」只用在好事上。<br>・这是偏正式、偏书面的说法。跟朋友聊天时，说<span class='gd-jp'>〜もあって</span>、<span class='gd-jp'>〜も重なって</span>比较自然。</div><div class='gd-h'>跟长得很像的分清楚</div><div class='gd-sec'><b>に加えて</b>＝单纯「除了 A，还有 B」，只是把事情一件一件列出来：<br><span class='gd-jp'>円安に加えて、物価も上がっている。</span>（除了日圆贬值，物价也在上涨）<br><b>と相まって</b>＝两个因素<b>一起起作用</b>，造成某个结果：<br><span class='gd-jp'>円安と物価高が相まって、生活が苦しくなっている。</span>（日圆贬值加上物价高涨，生活变得很辛苦）</div><div class='gd-sec'><b>とあって</b>（只差一个字，很容易看错）＝「因为是～这种特别的情况，所以…」，原因只有一个：<br><span class='gd-jp'>連休とあって、どこも混んでいる。</span>（因为是连假，到处都人挤人）<br><b>と相まって</b>＝两个原因叠在一起：<br><span class='gd-jp'>連休と好天が相まって、どこも混んでいる。</span>（连假加上好天气，到处都人挤人）</div><div class='gd-warn'>判断小诀窍：只是「还有～」用に加えて；「因为是～」用とあって；「两个因素一叠，效果加倍」才用と相まって。</div>"});
